def _read_version():
    """VERSION file next to app.py (x.y.z); 0.0.0 when missing or malformed."""
    try:
        with open(os.path.join(APP_DIR, "VERSION"), encoding="utf-8") as f:
            v = f.read().strip()
    except OSError:
        return "0.0.0"
    return v if re.fullmatch(r"\d+\.\d+\.\d+", v) else "0.0.0"


