# ---------------------------------------------------------------- i18n
# English is the source language: tr("English text", *args) returns the text in the UI language.
# Translations are the same JSON files the web client loads (static/i18n/<code>.json, see TRANSLATING.md).
# The language is a per-user setting; pushes use the recipient's language. A list value = [one, other] (trn()).
I18N_DIR = os.path.join(os.path.dirname(os.path.abspath(__file__)), "static", "i18n")


def load_languages():
    """{code: dict} of every static/i18n/*.json; English is built in (the keys themselves)."""
    out = {"en": {"_meta": {"name": "English", "locale": "en-GB"}}}
    for fn in sorted(glob.glob(os.path.join(I18N_DIR, "*.json"))):
        code = os.path.basename(fn)[:-5]
        try:
            with open(fn, encoding="utf-8") as f:
                d = json.load(f)
            if re.fullmatch(r"[a-z]{2,3}(-[A-Za-z0-9]{2,8})?", code) and code != "en" and isinstance(d, dict):
                out[code] = d
        except (OSError, ValueError) as e:
            print("i18n: skipping", fn, e, flush=True)
    return out


LANGS = load_languages()


def languages():
    """[{code, name}] for the language selector, sorted by name."""
    return sorted(({"code": k, "name": (v.get("_meta") or {}).get("name") or k} for k, v in LANGS.items()),
                  key=lambda x: x["name"].casefold())


def lang(c=None, uid=None):
    """UI language of a user (request: the logged-in user; no user: the first admin). Works in
    requests and in the watchdog threads."""
    try:
        if uid is None and has_request_context() and getattr(g, "user", None):
            uid = g.user["id"]
        own = c is None and not has_request_context()
        c = c or (db() if has_request_context() else connect())
        try:
            if uid is None:
                uid = default_uid(c)
            r = c.execute("SELECT value FROM user_settings WHERE user_id=? AND key='lang'", (uid,)).fetchone() \
                if uid else None
        finally:
            if own:
                c.close()
        v = r[0] if r else USER_DEFAULTS["lang"]
        return v if v in LANGS else "en"
    except Exception:  # noqa: BLE001
        return "en"


def N_(s):
    """Marks a key for tools/i18n_check.py; translated later by a tr call on the variable."""
    return s


def _key(k):
    """English display of a key: 'Text|ctx' -> 'Text'."""
    b = k.find("|")
    return k[:b] if b > 0 else k


def tr(key, *a, lg=None):
    v = LANGS.get(lg or lang(), {}).get(key)
    s = v if isinstance(v, str) else _key(key)
    return s.format(*a) if a else s


def trn(one, other, n, *a, lg=None):
    """Plural: one/other picked by n (n == 1 -> one); {0} = n, {1}.. = a."""
    v = LANGS.get(lg or lang(), {}).get(one)
    s = v[0 if n == 1 else 1] if isinstance(v, list) and len(v) == 2 else _key(one if n == 1 else other)
    return s.format(n, *a)


def now_utc():
    return datetime.now(timezone.utc)


def iso(dt):
    return dt.astimezone(timezone.utc).isoformat(timespec="seconds")


def iso_ms(dt):
    """Timeline timestamps (comments, activity): milliseconds keep their order within one second."""
    return dt.astimezone(timezone.utc).isoformat(timespec="milliseconds")


def parse_iso(s):
    return datetime.fromisoformat(s)


def local_now():
    return datetime.now(TZ)


def db():
    if "db" not in g:
        g.db = connect()
    return g.db


def connect():
    c = sqlite3.connect(DB, timeout=10)
    c.row_factory = sqlite3.Row
    c.execute("PRAGMA foreign_keys=ON")
    c.execute("PRAGMA journal_mode=WAL")
    return c


@app.teardown_appcontext
def close_db(_):
    c = g.pop("db", None)
    if c is not None:
        c.close()


def random_topic():
    return "kalmido-" + secrets.token_urlsafe(9).replace("_", "").replace("-", "").lower()


def default_uid(c):
    """First enabled admin (owner of the migrated single-user data, target of env defaults)."""
    r = c.execute("SELECT id FROM users WHERE is_admin=1 AND disabled=0 ORDER BY id LIMIT 1").fetchone() \
        or c.execute("SELECT id FROM users ORDER BY id LIMIT 1").fetchone()
    return r[0] if r else None


def ensure_inbox(c, uid):
    if not c.execute("SELECT 1 FROM lists WHERE is_inbox=1 AND owner_id=?", (uid,)).fetchone():
        c.execute("INSERT INTO lists(name,is_inbox,sort,created_at,owner_id) VALUES('Eingang',1,-1,?,?)",
                  (iso(now_utc()), uid))


def adopt_orphans(c, uid):
    """Rows from the single-user era (no owner) belong to uid. Idempotent (only NULL owners)."""
    n = c.execute("UPDATE lists SET owner_id=? WHERE owner_id IS NULL", (uid,)).rowcount
    n += c.execute("UPDATE tasks SET created_by=? WHERE created_by IS NULL", (uid,)).rowcount
    for t in ("habits", "pomos", "filters"):
        n += c.execute(f"UPDATE {t} SET user_id=? WHERE user_id IS NULL", (uid,)).rowcount
    n += c.execute("UPDATE task_tags SET user_id=? WHERE user_id=0", (uid,)).rowcount
    return n


def create_user(c, username, display_name="", password=None, proxy_login=None, is_admin=False,
                ntfy_topic=None, seed_global=False, drop_token=None, paperless_access=None, onboard=False):
    """Inserts a user with settings (+ inbox unless the caller adopts an existing one). Returns the id.
    Paperless access defaults to admins only."""
    pl = is_admin if paperless_access is None else paperless_access
    uid = c.execute("""INSERT INTO users(username,display_name,password_hash,proxy_login,is_admin,drop_token,created_at,
                                         paperless_access) VALUES(?,?,?,?,?,?,?,?)""",
                    (username, display_name or username, generate_password_hash(password) if password else None,
                     proxy_login or None, 1 if is_admin else 0, drop_token or secrets.token_urlsafe(24),
                     iso(now_utc()), 1 if pl else 0)).lastrowid
    vals = dict(USER_DEFAULTS)
    # chosen in the first-run setup ("What do you want to use?"): modules + language of new users
    for k, gk in (("features", "default_features"), ("lang", "default_lang")):
        v = gsetting(c, gk)
        if v:
            vals[k] = v
    if seed_global:  # the single-user settings become this user's settings
        for r in c.execute("SELECT key, value FROM settings"):
            if r["key"] in USER_DEFAULTS:
                vals[r["key"]] = r["value"]
    if ntfy_topic is not None:
        vals["ntfy_topic"] = ntfy_topic
    if onboard and ONBOARDING_ENV:  # new account (setup / user admin): sample list + welcome tour on first start
        vals["tour"] = vals["onboard"] = "pending"
    if not vals["ntfy_topic"]:
        vals["ntfy_topic"] = random_topic()
    for k, v in vals.items():
        c.execute("INSERT OR REPLACE INTO user_settings(user_id,key,value) VALUES(?,?,?)", (uid, k, v))
    return uid


def feats8(c, uid, fs):
    """features_rev 8: "deps" / "fields" are switched on for a user who already has such data (dependencies of
    tasks in lists they can see / custom fields of those lists) or uses the timeline or project progress, so
    nothing disappears; everyone else follows the instance default (the setup's choice, else on)."""
    fs = list(fs)
    dflt = [x for x in (gsetting(c, "default_features") or USER_DEFAULTS["features"]).split(",") if x]
    vis = vis_sql()
    has = {"deps": bool(c.execute(f"""SELECT 1 FROM task_deps d JOIN tasks t ON t.id=d.task_id
                                      WHERE t.list_id IN {vis} OR d.created_by=? LIMIT 1""", (uid, uid, uid)).fetchone()),
           "fields": bool(c.execute(f"SELECT 1 FROM list_fields WHERE list_id IN {vis} LIMIT 1", (uid, uid)).fetchone())}
    for f in ("deps", "fields"):
        if f not in fs and (has[f] or "timeline" in fs or "progress" in fs or f in dflt):
            fs.append(f)
    return fs


# 2.0.0 (#279): never start over on top of existing data. The data dir gets a marker on the first start (and on the first
# start of 2.0 of an existing install); when the marker, attachments or backups are there but tasks.db is missing, empty,
# unreadable or damaged (e.g. I/O errors of a failing disk), the app REFUSES to start instead of creating a fresh, empty
# database -- whose first visitor would become the admin. A new database is only created in a data dir without any data.
DATA_MARKER = os.path.join(os.path.dirname(os.path.abspath(DB)), ".kalmido-initialized")


class DataDirError(SystemExit):
    pass


def _has_files(d):
    try:
        for _root, _dirs, files in os.walk(d):
            if files:
                return True
    except OSError:
        return True  # cannot even list it: treat as "there is something" (never start empty)
    return False


def startup_guard():
    """Raises DataDirError (exit code 3) when the database must not be (re)created or opened; returns True when this is a
    genuinely new install (empty data dir), False for an existing, readable database."""
    data = [p for p, ok in ((DATA_MARKER, os.path.exists(DATA_MARKER)), (ATT_DIR, _has_files(ATT_DIR)),
                            (BK_DIR, _has_files(BK_DIR))) if ok]
    try:
        size = os.path.getsize(DB) if os.path.exists(DB) else None
    except OSError as e:
        size = f"unreadable ({e})"
    problem = None
    if size is None or size == 0:
        if data:
            problem = "is missing" if size is None else "is empty"
    elif isinstance(size, str):
        problem = size
    else:
        try:
            c = sqlite3.connect(f"file:{os.path.abspath(DB)}?mode=ro", uri=True, timeout=10)
            try:
                # constraint findings (a NOT NULL / CHECK violation) leave the file readable: start, the admin alert reports them
                # (see "admin alerts"); anything else (damaged pages, broken indexes, unreadable) refuses the start
                rows = [r[0] for r in c.execute("PRAGMA quick_check").fetchall()]
                hard = [x for x in rows if x != "ok" and not re.match(r"(NULL value in |CHECK constraint failed in )", str(x))]
                if not rows or hard:
                    problem = f"failed the integrity check ({(hard or ['?'])[0]})"
                elif not c.execute("SELECT 1 FROM sqlite_master WHERE type='table' AND name='users'").fetchone() and data:
                    problem = "has no Kalmido tables"
            finally:
                c.close()
        except sqlite3.Error as e:
            problem = f"cannot be read ({e})"
    if problem:
        msg = (f"FATAL: the database {DB} {problem}, but the data dir holds Kalmido data ({', '.join(data) or 'the database file'}). "
               "Refusing to start so that no new, empty database replaces it. Check the disk / volume, restore tasks.db from a "
               "backup (data/backups/), then start again.")
        print(msg, flush=True)
        raise DataDirError(3)
    return size is None or size == 0


def init_db(guard=True):
    os.makedirs(os.path.dirname(DB), exist_ok=True)
    if guard:  # a restore checked its database itself (and must never exit the process)
        startup_guard()
    os.makedirs(ATT_DIR, exist_ok=True)
    c = connect()
    c.executescript(SCHEMA)
    c.isolation_level = None
    c.execute("BEGIN IMMEDIATE")
    try:
        for table, col, ddl in MIGRATIONS:
            if col not in {r[1] for r in c.execute(f"PRAGMA table_info({table})")}:
                c.execute(ddl)
        # task_tags from the single-user era: (task_id, tag) -> (task_id, user_id, tag); 0 = adopted below
        if "user_id" not in {r[1] for r in c.execute("PRAGMA table_info(task_tags)")}:
            c.execute("""CREATE TABLE task_tags_mu (task_id INTEGER NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
                         user_id INTEGER NOT NULL DEFAULT 0, tag TEXT NOT NULL, PRIMARY KEY (task_id, user_id, tag))""")
            c.execute("INSERT INTO task_tags_mu(task_id,user_id,tag) SELECT task_id, 0, tag FROM task_tags")
            c.execute("DROP TABLE task_tags")
            c.execute("ALTER TABLE task_tags_mu RENAME TO task_tags")
        c.execute("DROP INDEX IF EXISTS tasks_tt")  # tt_id is unique per user now (tasks_tt_user)
        c.execute("DROP TRIGGER IF EXISTS time_task_title")
        c.execute(TIME_TITLE_TRIGGER)
        for stmt in INDEXES.strip().split(";"):
            if stmt.strip():
                c.execute(stmt)
        for k, v in GLOBAL_DEFAULTS.items():
            c.execute("INSERT OR IGNORE INTO settings(key,value) VALUES(?,?)", (k, v))
        _COLLAB_ALL["on"] = gsetting(c, "collab_all") != "0"
        _TIME_ALL["on"] = gsetting(c, "time_all") != "0"
        # migration of a single-user install: its data belongs to the bootstrap admin
        if not c.execute("SELECT 1 FROM users").fetchone():
            has_data = (c.execute("SELECT COUNT(*) FROM lists").fetchone()[0] > 1
                        or c.execute("SELECT 1 FROM tasks").fetchone() or c.execute("SELECT 1 FROM habits").fetchone()
                        or c.execute("SELECT 1 FROM filters").fetchone() or c.execute("SELECT 1 FROM pomos").fetchone())
            if has_data:
                legacy_topic = (c.execute("SELECT value FROM settings WHERE key='ntfy_topic'").fetchone() or [""])[0]
                uid = create_user(c, BOOT_USER, BOOT_NAME, None, BOOT_PROXY, True,
                                  ntfy_topic=legacy_topic or NTFY_TOPIC or None, seed_global=True,
                                  drop_token=os.environ.get("TASKS_DROP_TOKEN") or None)
                n = adopt_orphans(c, uid)
                print(f"multi-user migration: created user {BOOT_USER!r} (id {uid}), adopted {n} rows", flush=True)
        first = default_uid(c)
        if first:
            n = adopt_orphans(c, first)
            if n:
                print("adopted", n, "ownerless rows for user", first, flush=True)
            if NTFY_TOPIC:  # env topic seeds the first admin's topic when it is still empty
                c.execute("UPDATE user_settings SET value=? WHERE user_id=? AND key='ntfy_topic' AND value=''",
                          (NTFY_TOPIC, first))
        # list types (package D2, once): checklists stay checklists; lists that already hold project data (time entries,
        # dependencies, custom fields or values, a project status; time only from 5 minutes tracked in total, so a
        # misclicked timer of a few seconds does not turn a household list into a project) become projects; the rest: list
        if gsetting(c, "migr_kind") != "1":
            c.execute("UPDATE lists SET kind='checklist' WHERE checklist=1")
            n = c.execute("""UPDATE lists SET kind='project' WHERE checklist=0 AND (
                               id IN (SELECT list_id FROM time_entries WHERE list_id IS NOT NULL
                                      GROUP BY list_id HAVING SUM(seconds) >= 300)
                               OR id IN (SELECT t.list_id FROM task_deps d JOIN tasks t ON t.id=d.task_id)
                               OR id IN (SELECT t.list_id FROM task_deps d JOIN tasks t ON t.id=d.blocker_id)
                               OR id IN (SELECT list_id FROM list_fields)
                               OR id IN (SELECT t.list_id FROM task_field_values v JOIN tasks t ON t.id=v.task_id)
                               OR status!='')""").rowcount
            gset(c, "migr_kind", "1")
            print("list types:", n, "lists with project data became projects", flush=True)
        # features_rev 8: the setup's default modules (from before 1.2) get "deps" / "fields" like the users below
        dfs = gsetting(c, "default_features")
        if dfs and gsetting(c, "migr_feat8") != "1":
            d = [x for x in dfs.split(",") if x]
            d += [f for f in ("deps", "fields") if f not in d and ("timeline" in d or "progress" in d)]
            gset(c, "default_features", ",".join(d))
        gset(c, "migr_feat8", "1")
        # features_rev 9 (2.0.6): comments became a module of their own, on by default (also in the setup's default)
        if dfs and gsetting(c, "migr_feat9") != "1":
            d = [x for x in (gsetting(c, "default_features") or "").split(",") if x]
            if "comments" not in d:
                gset(c, "default_features", ",".join(d + ["comments"]))
        gset(c, "migr_feat9", "1")
        for (uid,) in c.execute("SELECT id FROM users").fetchall():
            ensure_inbox(c, uid)
            for k, v in USER_DEFAULTS.items():
                c.execute("INSERT OR IGNORE INTO user_settings(user_id,key,value) VALUES(?,?,?)", (uid, k, v))
            # features_rev 2: paperless module added -> on by default for existing installs
            # features_rev 3: collab added (2026-09-26) -> on by default
            # features_rev 4: the "links" switch is gone (website link always on) -> dropped from the list
            # features_rev 5: statistics module added (2026-09-26) -> on by default
            # features_rev 6: time tracking module added (2026-09-27) -> on by default
            # features_rev 7: project progress / overview added (2026-09-27) -> on by default
            s = usettings(c, uid)
            rev, fs = int(s.get("features_rev") or 1), [x for x in s["features"].split(",") if x]
            if rev < 7:
                for f, since in (("paperless", 2), ("collab", 3), ("stats", 5), ("time", 6), ("progress", 7)):
                    if rev < since and f not in fs:
                        fs.append(f)
                fs = [f for f in fs if f != "links"]
                uset(c, uid, "features", ",".join(fs))
                uset(c, uid, "features_rev", "7")
            # features_rev 8 (package D2, 2026-09-29): dependencies + custom fields became modules of their own
            if rev < 8:
                fs = feats8(c, uid, fs)
                uset(c, uid, "features", ",".join(fs))
                uset(c, uid, "features_rev", "8")
            # features_rev 9 (2.0.6, #315): comments became a module of their own -> on for everyone
            if rev < 9:
                if "comments" not in fs:
                    fs.append("comments")
                uset(c, uid, "features", ",".join(fs))
                uset(c, uid, "features_rev", "9")
        if not gsetting(c, "cal_secret"):  # calendar subscriptions: key material for the stored links / passwords
            gset(c, "cal_secret", secrets.token_hex(32))
        if not gsetting(c, "auth_secret"):  # sign-in: key material for the TOTP secrets and the backup passphrase
            gset(c, "auth_secret", secrets.token_hex(32))
        if not gsetting(c, "undo_key"):  # signs the undo payloads handed to the client
            gset(c, "undo_key", secrets.token_hex(32))
        if not gsetting(c, "vapid_private"):  # Web Push: the instance's VAPID key (P-256), generated once
            gset(c, "vapid_private", _b64u(ec.generate_private_key(ec.SECP256R1()).private_numbers()
                                           .private_value.to_bytes(32, "big")))
            print("Web Push: generated the VAPID key", flush=True)
        _vapid_load(gsetting(c, "vapid_private"))
        # one-shot: completions from before completed_by existed belong to the task's creator (else the list owner)
        if gsetting(c, "migr_completed_by") != "1":
            n = c.execute("""UPDATE tasks SET completed_by=COALESCE(created_by, (SELECT owner_id FROM lists WHERE lists.id=tasks.list_id))
                             WHERE completed_by IS NULL AND status!=0 AND completed_at IS NOT NULL""").rowcount
            gset(c, "migr_completed_by", "1")
            print("completed_by: attributed", n, "earlier completions", flush=True)
        # 1.8.1: the global "Show completed" switch is gone (per view only, default shown): drop the stored values
        c.execute("DELETE FROM user_settings WHERE key='show_completed'")
        c.execute("DELETE FROM settings WHERE key='show_completed'")
        # 2.4.0 (#361): folders nest one level ("Clients/Company X", FOLDER_SEP). A "/" in an existing folder name would now
        # mean a subfolder, so it becomes the look-alike U+2215 once: every existing folder stays top-level, as it was
        if gsetting(c, "migr_folder_path") != "1":
            n = folder_path_migration(c)
            gset(c, "migr_folder_path", "1")
            if n:
                print("folders: kept", n, "folder names with a slash top-level", flush=True)
        # 2.4.1 (#379): tidying up is done by exactly one agent per list. Lists with tidy on get the agent that already
        # received their tidy events first (the first agent with edit rights), once
        if gsetting(c, "migr_tidy_agent") != "1":
            n = 0
            for (lid,) in c.execute("SELECT id FROM lists WHERE agent_tidy!='off' AND tidy_agent IS NULL").fetchall():
                aid = tidy_agent_of(c, lid)
                if aid:
                    c.execute("UPDATE lists SET tidy_agent=? WHERE id=?", (aid, lid))
                    n += 1
            gset(c, "migr_tidy_agent", "1")
            if n:
                print("tidy: assigned the tidy agent of", n, "list(s)", flush=True)
        if gsetting(c, "migr_auditfix") != "1":  # security audit 2026-09-28, one-shot
            n = c.execute("UPDATE users SET paperless_access=1 WHERE is_admin=1 AND paperless_access=0").rowcount
            counts = repair_data(c)
            gset(c, "migr_auditfix", "1")
            print("audit migration: Paperless access granted to", n, "admin(s); repaired:", counts, flush=True)
        c.execute("COMMIT")
    except Exception:
        c.execute("ROLLBACK")
        raise
    if c.execute("PRAGMA user_version").fetchone()[0] < SCHEMA_VERSION:
        c.execute(f"PRAGMA user_version={int(SCHEMA_VERSION)}")
    c.close()
    if not os.path.exists(DATA_MARKER):  # new install, or the first start of 2.0 on a readable database
        try:
            with open(DATA_MARKER, "w", encoding="utf-8") as f:
                f.write("This data dir belongs to Kalmido. While this file exists, Kalmido never creates a new empty database here.\n")
        except OSError as e:
            print("warning: could not write", DATA_MARKER, e, flush=True)


def repair_data(c):
    """Nulls / normalizes values the validation now rejects (they could break the shared watchdog, the
    calendar expansion or the client) and breaks parent_id cycles. Returns counts per kind of fix."""
    n = {}

    def bump_n(k, x=1):
        if x:
            n[k] = n.get(k, 0) + x
    for t in c.execute("SELECT id, due, due_time, start, duration, reminders, repeat, repeat_from, priority FROM tasks").fetchall():
        f = {}
        if t["due"] is not None and not valid_date(t["due"]):
            f.update(due=None, due_time=None, start=None, reminders="")
            bump_n("due")
        if "due_time" not in f and t["due_time"] is not None and not valid_hm(t["due_time"]):
            f["due_time"] = None
            bump_n("due_time")
        if "start" not in f and t["start"] is not None and not valid_date(t["start"]):
            f["start"] = None
            bump_n("start")
        d = t["duration"]
        if d is not None and (isinstance(d, bool) or not isinstance(d, int) or not 1 <= d <= DURATION_MAX):
            f["duration"] = None
            bump_n("duration")
        if "reminders" not in f and t["reminders"]:
            ok = [x.strip() for x in str(t["reminders"]).split(",")
                  if re.fullmatch(r"-?\d{1,6}", x.strip()) and REM_MIN <= int(x.strip()) <= REM_MAX]
            ok = ",".join(list(dict.fromkeys(str(int(x)) for x in ok))[:REM_COUNT])
            if ok != t["reminders"]:
                f["reminders"] = ok
                bump_n("reminders")
        if t["repeat"]:
            rep = rr_norm(t["repeat"])
            due = f.get("due", t["due"])
            if rr_problem(rep) or (due and not rr_feasible(rep, due)):
                f["repeat"] = ""
                bump_n("repeat")
            elif rep != t["repeat"]:
                f["repeat"] = rep
        if t["repeat_from"] not in ("due", "done"):
            f["repeat_from"] = "due"
            bump_n("repeat_from")
        if t["priority"] not in PRIORITIES:
            f["priority"] = 0
            bump_n("priority")
        if f:
            c.execute(f"UPDATE tasks SET {','.join(k + '=?' for k in f)} WHERE id=?", [*f.values(), t["id"]])
    # parent cycles (and parents that point at themselves): the task where a walk up meets itself goes top level
    parent = {r[0]: r[1] for r in c.execute("SELECT id, parent_id FROM tasks WHERE parent_id IS NOT NULL")}
    for tid in list(parent):
        seen, cur = [], tid
        while cur in parent and cur not in seen and len(seen) < 50:
            seen.append(cur)
            cur = parent[cur]
        if cur in seen:  # cycle: cut it at the node where it closes
            c.execute("UPDATE tasks SET parent_id=NULL WHERE id=?", (cur,))
            parent.pop(cur, None)
            bump_n("parent_cycle")
    for r in c.execute("SELECT id, name, color, folder, view FROM lists").fetchall():
        f = {}
        if r["color"] and not (isinstance(r["color"], str) and LIST_COLOR_RE.fullmatch(r["color"])):
            f["color"] = ""
        if r["view"] not in LIST_VIEWS:
            f["view"] = "list"
        fo = r["folder"] if isinstance(r["folder"], str) else ""
        if fo != clean_folder(fo, False) or not isinstance(r["folder"], str):
            f["folder"] = clean_folder(fo, False)
        if not isinstance(r["name"], str):
            f["name"] = str(r["name"])[:LIST_NAME_MAX]
        if f:
            c.execute(f"UPDATE lists SET {','.join(k + '=?' for k in f)} WHERE id=?", [*f.values(), r["id"]])
            bump_n("list")
    for r in c.execute("SELECT list_id, user_id, folder, view FROM list_members").fetchall():
        fo = r["folder"] if isinstance(r["folder"], str) else ""
        v = r["view"] if r["view"] in LIST_VIEWS else None
        if fo != r["folder"] or fo != clean_folder(fo, False) or v != r["view"]:
            c.execute("UPDATE list_members SET folder=?, view=? WHERE list_id=? AND user_id=?",
                      (clean_folder(fo, False), v, r["list_id"], r["user_id"]))
            bump_n("list_member")
    for h in c.execute("SELECT id, color, remind_at, goal, per_week, days FROM habits").fetchall():
        f = {}
        if h["color"] and not (isinstance(h["color"], str) and LIST_COLOR_RE.fullmatch(h["color"])):
            f["color"] = ""
        if h["remind_at"] and not valid_hm(h["remind_at"]):
            f["remind_at"] = ""
        if isinstance(h["goal"], bool) or not isinstance(h["goal"], int) or not 1 <= h["goal"] <= 1000:
            f["goal"] = 1
        if isinstance(h["per_week"], bool) or not isinstance(h["per_week"], int) or not 0 <= h["per_week"] <= 7:
            f["per_week"] = 0
        if not isinstance(h["days"], str) or not re.fullmatch(r"[1-7]+", h["days"]):
            f["days"] = "1234567"
        if f:
            c.execute(f"UPDATE habits SET {','.join(k + '=?' for k in f)} WHERE id=?", [*f.values(), h["id"]])
            bump_n("habit")
    for k, dflt, ok in (("allday_time", "09:00", valid_hm), ("digest_time", "", lambda v: v == "" or valid_hm(v))):
        for r in c.execute("SELECT user_id, value FROM user_settings WHERE key=?", (k,)).fetchall():
            if not ok(r["value"]):
                c.execute("UPDATE user_settings SET value=? WHERE user_id=? AND key=?", (dflt, r["user_id"], k))
                bump_n("setting_" + k)
    return n


def gsetting(c, key):
    r = c.execute("SELECT value FROM settings WHERE key=?", (key,)).fetchone()
    return r[0] if r else GLOBAL_DEFAULTS.get(key, "")


def gset(c, key, value):
    c.execute("INSERT INTO settings(key,value) VALUES(?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value",
              (key, str(value)))


def usettings(c, uid):
    s = dict(USER_DEFAULTS)
    s.update({r["key"]: r["value"] for r in c.execute("SELECT key, value FROM user_settings WHERE user_id=?", (uid,))})
    return s


def uset(c, uid, key, value):
    c.execute("INSERT INTO user_settings(user_id,key,value) VALUES(?,?,?) "
              "ON CONFLICT(user_id,key) DO UPDATE SET value=excluded.value", (uid, key, str(value)))


def bump(c):
    c.execute("UPDATE settings SET value=CAST(value AS INTEGER)+1 WHERE key='version'")


def err(msg, code=400):
    return jsonify(error=msg), code  # msg is already translated


def body():
    """The JSON body of the request (the REST API hands its translated body to the internal views via g.body)."""
    b = g.get("body") if has_request_context() else None
    if b is not None:
        return b
    return request.get_json(silent=True) or {}


# ---------------------------------------------------------------- auth

def me():
    return g.user["id"]


def _peer_trusted():
    """Direct peer is a trusted proxy (and the request came in on the proxy port, if one is set)."""
    try:
        ip = ipaddress.ip_address(request.remote_addr or "")
    except ValueError:
        return False
    if not any(ip in n for n in AUTH_TRUSTED):
        return False
    return not AUTH_PROXY_PORT or str(request.environ.get("SERVER_PORT", "")) == AUTH_PROXY_PORT


def proxy_login_value():
    """The trusted proxy header of this request, or '' (not configured / untrusted peer / bypassed path)."""
    if not AUTH_HEADER or request.path in PROXY_IGNORE or request.path.startswith(("/static/", ICAL_PREFIX, API_PREFIX, PUB_PREFIX)):
        return ""
    v = (request.headers.get(AUTH_HEADER) or "").strip()
    return v if v and _peer_trusted() else ""


def _token_hash(t):
    return hashlib.sha256(t.encode()).hexdigest()


def client_ip():
    xff = request.headers.get("X-Forwarded-For", "")
    if xff and _peer_trusted():
        return xff.split(",")[0].strip()
    return request.remote_addr or ""


def _is_open(path, method):
    return path in OPEN_PATHS or path.startswith(("/static/", ICAL_PREFIX, PUB_PREFIX)) or (path in ("/share", "/capture") and method == "GET")  # 2.4.0: /capture (#187)


def rate_ip():
    """Client address for rate limits: X-Forwarded-For from a trusted proxy peer on ANY port (the API is reached on the
    app port, where the peer is the same proxy). Never used for authentication, only to key limits and alerts."""
    xff = request.headers.get("X-Forwarded-For", "")
    try:
        peer = ipaddress.ip_address(request.remote_addr or "")
    except ValueError:
        return request.remote_addr or ""
    if xff and any(peer in n for n in AUTH_TRUSTED):
        return xff.split(",")[0].strip()[:64]
    return request.remote_addr or ""


# ---- maintenance gate (restore of a backup). Every request and every background tick is an "active holder"; a
# restore switches maintenance on, waits until it is the only holder left, swaps the data and switches it off.
# Meanwhile new requests get 503 (except the health check and static files) and background threads wait.
class _Gate:
    def __init__(self):
        self.cond = threading.Condition()
        self.active = 0
        self.maint = False

    def enter(self, block):
        with self.cond:
            if self.maint:
                if not block:
                    return False
                self.cond.wait_for(lambda: not self.maint)
            self.active += 1
            return True

    def leave(self):
        with self.cond:
            self.active -= 1
            self.cond.notify_all()

    @contextlib.contextmanager
    def bg(self):
        self.enter(True)
        try:
            yield
        finally:
            self.leave()

    def begin(self, own, timeout):
        """Maintenance on once at most `own` holders (the caller itself) are left; False after `timeout` s."""
        with self.cond:
            if self.maint:
                return False
            self.maint = True
            if not self.cond.wait_for(lambda: self.active <= own, timeout):
                self.maint = False
                self.cond.notify_all()
                return False
            return True

    def end(self):
        with self.cond:
            self.maint = False
            self.cond.notify_all()


GATE = _Gate()


def _accept_lang():
    """UI language from the browser (no database access: used while a restore runs)."""
    for part in (request.headers.get("Accept-Language") or "").split(","):
        code = part.split(";")[0].strip().lower()[:2]
        if code in LANGS:
            return code
    return "en"


@app.before_request
def maint_gate():
    g.gate = False
    if request.path == "/api/health" or request.path.startswith("/static/"):
        return None
    if not GATE.enter(False):
        return jsonify(error=tr("The server is restoring a backup, please try again in a minute", lg=_accept_lang()),
                       maint=True), 503
    g.gate = True
    return None


@app.teardown_request
def maint_leave(_):
    if g.pop("gate", False):
        GATE.leave()


@app.before_request
def authenticate():
    g.user, g.auth_via, g.auth_error, g.proxy_login, g.pushes = None, None, None, "", []
    if request.path.startswith(API_PREFIX) or request.path == API_PREFIX.rstrip("/"):
        return api_authenticate()  # bearer token only (package B)
    if request.path.startswith("/api/hooks/git/") and request.method == "POST":
        return None  # 2.2.0: inbound Git webhook: no user, no proxy header, the HMAC signature is the credential
    if request.path.startswith(PUB_PREFIX):
        return None  # public list link: no user; the token in the path is the credential (see "public links")
    c = db()
    val = proxy_login_value()
    if val:
        u = c.execute("SELECT * FROM users WHERE proxy_login=? COLLATE NOCASE", (val,)).fetchone()
        if u and not u["disabled"] and not is_agent(u):
            g.user, g.auth_via = u, "proxy"
        else:
            g.auth_error, g.proxy_login = ("disabled" if u else "no_account"), val
    if not g.user and not g.auth_error:
        tok = request.cookies.get(COOKIE)
        if tok:
            r = c.execute("""SELECT u.* FROM sessions s JOIN users u ON u.id=s.user_id
                             WHERE s.token_hash=? AND s.expires_at>? AND u.disabled=0 AND u.kind!='agent'""",
                          (_token_hash(tok), iso(now_utc()))).fetchone()
            if r:
                g.user, g.auth_via = r, "session"
    path = request.path
    if request.method not in ("GET", "HEAD", "OPTIONS") and path.startswith("/api/") \
            and request.headers.get(CSRF_HEADER) != CSRF_VALUE:
        return err(tr("Request blocked: header {0} missing", CSRF_HEADER), 403)
    if g.user or _is_open(path, request.method):
        return None
    if path.startswith("/api/"):
        if g.auth_error:
            msg = tr("This account is disabled") if g.auth_error == "disabled" else tr("No account for {0}", g.proxy_login)
            return jsonify(error=msg, auth=g.auth_error, login=g.proxy_login), 403
        setup = not c.execute("SELECT 1 FROM users").fetchone()
        return jsonify(error=tr("Please log in"), auth="setup" if setup else "login"), 401
    return redirect("/", 303)


_fails, _fail_lock = {}, threading.Lock()
_DUMMY_HASH = generate_password_hash(secrets.token_urlsafe(16))  # same algorithm / parameters as real ones
FAIL_WINDOW = 900  # s


def _rate_keys(username):
    return [("u:" + username, 5), ("ip:" + client_ip(), 20)]


def _rate_blocked(keys):
    now = time.time()
    with _fail_lock:
        for k, limit in keys:
            arr = [t for t in _fails.get(k, []) if now - t < FAIL_WINDOW]
            _fails[k] = arr
            if len(arr) >= limit:
                return True
    return False


def _rate_fail(keys):
    """Records a failure; returns the keys whose limit this failure just reached (the rate limit trips)."""
    out = []
    with _fail_lock:
        for k, limit in keys:
            arr = _fails.setdefault(k, [])
            arr.append(time.time())
            if len(arr) == limit:
                out.append(k)
    return out


def start_session(c, uid, remember, via="password"):
    """A new session (always a new random token: a login never adopts a token the browser brought along).
    via: password | 2fa | passkey | oidc."""
    tok = secrets.token_urlsafe(32)
    days = SESSION_DAYS if remember else 1
    c.execute("DELETE FROM sessions WHERE expires_at<?", (iso(now_utc()),))
    c.execute("INSERT INTO sessions(token_hash,user_id,created_at,expires_at,via) VALUES(?,?,?,?,?)",
              (_token_hash(tok), uid, iso(now_utc()), iso(now_utc() + timedelta(days=days)), via))
    return tok, (days * 86400 if remember else None)


def set_cookie(resp, tok, max_age):
    secure = request.is_secure or request.headers.get("X-Forwarded-Proto", "") == "https"
    resp.set_cookie(COOKIE, tok, max_age=max_age, httponly=True, samesite="Lax", secure=secure, path="/")
    return resp


def user_public(u):
    return {"id": u["id"], "username": u["username"], "display_name": u["display_name"] or u["username"],
            "avatar": avatar_url(u), **({"agent": True} if is_agent(u) else {})}


# ---- 1.9.0: profile pictures. A preset (funny sloths, static SVGs) or an own photo: the client crops it square, the
# server decodes it (Pillow, pixel limit), turns it upright, resizes it to AVATAR_PX and stores a fresh JPEG (no EXIF /
# GPS or other metadata survives) below ATT_DIR/avatars (so backups include it). Served with login to the user
# themselves, admins and the people who share a list with them; the file name carries a random token (new picture =
# new URL, cached for good). Without a picture everybody sees the initials, as before.
AVATAR_PRESETS = ("coffee", "headphones", "camera", "sleepy", "laptop", "plant", "robot", "shades", "party", "glasses")
AVATAR_PX = 256
AVATAR_MAX_MB = 8
AVATAR_DIR = os.path.join(ATT_DIR, "avatars")


def avatar_url(u):
    try:
        a = u["avatar"] or ""
    except (IndexError, KeyError):
        return ""
    if a.startswith("p:") and a[2:] in AVATAR_PRESETS:
        return f"/static/avatars/{a[2:]}.svg"
    if a.startswith("u:") and re.fullmatch(r"[A-Za-z0-9_-]{8,40}", a[2:]):
        return f"/api/avatar/{u['id']}/{a[2:]}.jpg"
    return ""


def avatar_path(uid, tok):
    return os.path.join(AVATAR_DIR, f"u{int(uid)}-{tok}.jpg")


def avatar_drop_file(uid, a):
    if a and a.startswith("u:") and re.fullmatch(r"[A-Za-z0-9_-]{8,40}", a[2:]):
        with contextlib.suppress(OSError):
            os.remove(avatar_path(uid, a[2:]))


def avatar_map(c, uid):
    """{user id: picture URL} of me and everybody sharing a list with me (only users that have a picture)."""
    rows = c.execute(f"""SELECT id, avatar FROM users WHERE avatar IS NOT NULL AND avatar!='' AND (id=? OR id IN
                         (SELECT owner_id FROM lists WHERE id IN {vis_sql()}) OR id IN
                         (SELECT user_id FROM list_members WHERE list_id IN {vis_sql()}))""", (uid, uid, uid, uid, uid)).fetchall()
    return {str(r["id"]): avatar_url(r) for r in rows if avatar_url(r)}


def avatar_process(raw):
    """Upload bytes -> square JPEG bytes (AVATAR_PX, no metadata). BadInput for anything that is not a picture."""
    try:
        from PIL import Image, ImageOps
    except ImportError:
        raise BadInput(tr("Photos are not available on this server"))
    Image.MAX_IMAGE_PIXELS = 30_000_000
    try:
        im = Image.open(io.BytesIO(raw))  # reads the header only
        if im.format not in ("JPEG", "PNG", "WEBP", "GIF", "BMP"):
            raise BadInput(tr("Please choose a JPEG, PNG or WebP picture"))
        if im.width * im.height > 60_000_000:  # the browser sends 512 px; this only stops huge direct uploads (memory)
            raise BadInput(tr("This picture cannot be read"))
        if im.format == "JPEG":
            im.draft("RGB", (AVATAR_PX * 2, AVATAR_PX * 2))  # decode big photos at a reduced scale (fast, little memory)
        im.load()
        im = ImageOps.exif_transpose(im)
        if im.mode in ("RGBA", "LA", "P"):
            im = im.convert("RGBA")
            bg = Image.new("RGB", im.size, (255, 255, 255))
            bg.paste(im, mask=im.getchannel("A"))
            im = bg
        else:
            im = im.convert("RGB")
        im = ImageOps.fit(im, (AVATAR_PX, AVATAR_PX), method=Image.Resampling.LANCZOS)
        out = io.BytesIO()
        im.save(out, "JPEG", quality=86, optimize=True)  # a new file: no EXIF, GPS or ICC data carried over
        return out.getvalue()
    except BadInput:
        raise
    except Exception:  # noqa: BLE001  (decompression bomb, truncated, unknown format ...)
        raise BadInput(tr("This picture cannot be read"))


# ---- 2.0.2: own list icons (same technique as the profile pictures): a preset (the sloth pictures or the app icon) or an
# own picture, cropped square in the browser, re-encoded here (PNG, LIST_ICON_PX, transparency kept, no metadata) below
# ATT_DIR/listicons (in backups). Served to everybody who sees the list; new picture = new token = new URL.
LIST_ICON_PRESETS = ("kalmido",) + AVATAR_PRESETS
LIST_ICON_PX = 128
LIST_ICON_DIR = os.path.join(ATT_DIR, "listicons")


def list_icon_url(r):
    try:
        a = r["icon"] or ""
    except (IndexError, KeyError):
        return ""
    if a == "p:kalmido":
        return "/static/icon.svg"
    if a.startswith("p:") and a[2:] in AVATAR_PRESETS:
        return f"/static/avatars/{a[2:]}.svg"
    if a.startswith("u:") and re.fullmatch(r"[A-Za-z0-9_-]{8,40}", a[2:]):
        return f"/api/list-icon/{r['id']}/{a[2:]}.png"
    return ""


def list_icon_path(lid, tok):
    return os.path.join(LIST_ICON_DIR, f"l{int(lid)}-{tok}.png")


def list_icon_drop_file(lid, a):
    if a and a.startswith("u:") and re.fullmatch(r"[A-Za-z0-9_-]{8,40}", a[2:]):
        with contextlib.suppress(OSError):
            os.remove(list_icon_path(lid, a[2:]))


def list_icon_process(raw):
    """Upload bytes -> square PNG bytes (LIST_ICON_PX, alpha kept, no metadata). BadInput for anything that is not a picture."""
    try:
        from PIL import Image, ImageOps
    except ImportError:
        raise BadInput(tr("Photos are not available on this server"))
    Image.MAX_IMAGE_PIXELS = 30_000_000
    try:
        im = Image.open(io.BytesIO(raw))
        if im.format not in ("JPEG", "PNG", "WEBP", "GIF", "BMP"):
            raise BadInput(tr("Please choose a JPEG, PNG or WebP picture"))
        if im.width * im.height > 60_000_000:
            raise BadInput(tr("This picture cannot be read"))
        if im.format == "JPEG":
            im.draft("RGB", (LIST_ICON_PX * 2, LIST_ICON_PX * 2))
        im.load()
        im = ImageOps.exif_transpose(im)
        im = im.convert("RGBA")
        im = ImageOps.fit(im, (LIST_ICON_PX, LIST_ICON_PX), method=Image.Resampling.LANCZOS)
        out = io.BytesIO()
        im.save(out, "PNG", optimize=True)  # a new file: no EXIF, GPS, text chunks or ICC data carried over
        return out.getvalue()
    except BadInput:
        raise
    except Exception:  # noqa: BLE001
        raise BadInput(tr("This picture cannot be read"))


@app.get("/api/auth/info")
def auth_info():
    """What the login screen needs (open): setup needed?, language, why a proxy login failed, the extra
    login buttons (OIDC provider, passkey)."""
    c = db()
    return jsonify(setup=not c.execute("SELECT 1 FROM users").fetchone(), lang=lang(),
                   languages=languages(), user=user_public(g.user) if g.user else None,
                   auth_error=g.auth_error, login=g.proxy_login or proxy_login_value(),
                   oidc={"label": OIDC_LABEL} if OIDC_ON else None, passkey_login=gsetting(c, "passkey_login") != "0",
                   login_errors={k: tr(v) for k, v in OIDC_ERRORS.items()} if OIDC_ON else {})


def finish_login(c, u, remember, via, extra=None):
    """Last step of every login: ends the session this browser brought along (if any), starts a new one, resets
    the failure counter of the user name."""
    old = request.cookies.get(COOKIE)
    if old:
        c.execute("DELETE FROM sessions WHERE token_hash=?", (_token_hash(old),))
    with _fail_lock:
        _fails.pop("u:" + u["username"], None)
    tok, age = start_session(c, u["id"], remember, via)
    c.commit()
    resp = set_cookie(jsonify(ok=True, user=user_public(u), **(extra or {})), tok, age)
    resp.delete_cookie(PEND_COOKIE, path="/api/auth")
    return resp


@app.post("/api/auth/login")
def auth_login():
    b = body()
    username = (b.get("username") or "").strip().lower()
    keys = _rate_keys(username)
    if _rate_blocked(keys):
        return err(tr("Too many failed logins, please wait a few minutes"), 429)
    c = db()
    u = c.execute("SELECT * FROM users WHERE username=?", (username,)).fetchone()
    pw = b.get("password") if isinstance(b.get("password"), str) else ""
    # exactly one hash check on every path (unknown user / no password: a real hash of the same kind)
    pw_ok = check_password_hash(u["password_hash"] if u and u["password_hash"] else _DUMMY_HASH, pw)
    ok = bool(u and u["password_hash"] and not u["disabled"] and pw_ok and not is_agent(u))
    if not ok:
        # admin alerts: only real usernames are named (a typo in the name field could be a password)
        for k in _rate_fail(keys):
            if not k.startswith("u:"):
                aa_now("security", "ratelimit:" + k, N_("Login rate limit reached for IP {0} (logins refused for {1} min)."),
                       [client_ip(), FAIL_WINDOW // 60])
            elif u:
                aa_now("security", "ratelimit:" + k, N_("Login rate limit reached for user {0} (logins refused for {1} min)."),
                       [username, FAIL_WINDOW // 60])
            else:
                aa_now("security", "ratelimit:u:?",
                       N_("Login rate limit reached for an unknown user name (logins refused for {0} min)."), [FAIL_WINDOW // 60])
        aa_count("security", "logins", client_ip(), user=username if u else "?")
        print("login failed for", repr(username), "from", client_ip(), flush=True)
        return err(tr("Wrong username or password"), 401)
    remember = bool(b.get("remember", True))
    methods = twofa_methods(c, u)
    if methods:  # second step: a code, a passkey or a recovery code (POST /api/auth/2fa...)
        tok = pend_new("2fa", u["id"], remember=remember)
        return pend_cookie(jsonify(ok=False, twofa=True, methods=methods), tok)
    if gsetting(c, "twofa_required") == "1":  # admin policy: enrol now, the session starts afterwards
        tok = pend_new("enrol", u["id"], remember=remember)
        return pend_cookie(jsonify(ok=False, enrol=True, methods=["totp", "passkey"]), tok)
    return finish_login(c, u, remember, "password")


@app.post("/api/auth/setup")
def auth_setup():
    """First start without users: creates the first admin. With a trusted proxy header the account is
    bound to that login and the password is optional."""
    b = body()
    c = db()
    c.execute("BEGIN IMMEDIATE")
    if c.execute("SELECT 1 FROM users").fetchone():
        c.rollback()
        return err(tr("Setup is already done"), 409)
    username = (b.get("username") or "").strip().lower()
    pw = b.get("password") or ""
    proxy = proxy_login_value() or None
    if not USERNAME_RE.fullmatch(username):
        c.rollback()
        return err(tr("Username: 1-32 characters a-z, 0-9, dot, dash, underscore"))
    if (pw or not proxy) and len(pw) < MIN_PASSWORD:
        c.rollback()
        return err(tr("Password: at least {0} characters", MIN_PASSWORD))
    uid = create_user(c, username, (b.get("display_name") or "").strip()[:60] or username, pw or None, proxy, True,
                      ntfy_topic=NTFY_TOPIC or None, seed_global=True,
                      drop_token=os.environ.get("TASKS_DROP_TOKEN") or None,
                      onboard=not c.execute("SELECT 1 FROM tasks LIMIT 1").fetchone())
    adopt_orphans(c, uid)
    ensure_inbox(c, uid)
    bump(c)
    tok, age = start_session(c, uid, True) if pw else (None, None)
    c.commit()
    resp = jsonify(ok=True)
    return set_cookie(resp, tok, age) if tok else resp


@app.post("/api/auth/logout")
def auth_logout():
    c = db()
    tok = request.cookies.get(COOKIE)
    if tok:
        c.execute("DELETE FROM sessions WHERE token_hash=?", (_token_hash(tok),))
        c.commit()
    resp = jsonify(ok=True, proxy=g.auth_via == "proxy")
    resp.delete_cookie(COOKIE, path="/")
    return resp


# ---------------------------------------------------------------- two-factor (built-in login): TOTP, recovery codes, passkeys
# Only for accounts with a password (the built-in login). Proxy-header SSO and OIDC logins leave the second factor
# to the proxy / identity provider. After a correct password a user with a second factor gets a short-lived ticket
# (HttpOnly cookie, path /api/auth, 5 min, 5 tries) instead of a session; the session starts after the code, a
# passkey or a recovery code. With the admin policy "Require 2FA" a user without one gets an enrolment ticket and
# must set up TOTP or a passkey first. Every failed code counts against the same limits as a wrong password.
# TOTP: RFC 6238 (SHA-1, 6 digits, 30 s, ±1 step), the secret is stored encrypted (AES-GCM, key from the server
# secret), a used time step is never accepted again. Recovery codes: 10 random one-time codes, SHA-256 at rest.
# Passkeys: WebAuthn via py_webauthn (attestation "none", the credential id, COSE public key and sign counter are
# stored); RP ID = KALMIDO_WEBAUTHN_RP_ID or the host of the page (only origins from PUBLIC_URL /
# KALMIDO_WEBAUTHN_ORIGINS or localhost), so a passkey only ever works on the address it was created on.
PEND_COOKIE = "kalmido_2fa"
PEND_TTL = 300           # s a login ticket / an enrolment secret / a WebAuthn challenge lives
PEND_TRIES = 5           # wrong codes per ticket
PEND_MAX = 5000
TOTP_STEP, TOTP_DIGITS = 30, 6
RC_COUNT = 10
RC_ALPHABET = "abcdefghjkmnpqrstuvwxyz23456789"
PASSKEY_NAME_MAX = 60
PASSKEY_MAX = 20         # per user
WA_TRANSPORTS = {"usb", "nfc", "ble", "internal", "hybrid", "smart-card", "cable"}
WA_RP_ID_ENV = os.environ.get("KALMIDO_WEBAUTHN_RP_ID", "").strip().lower().rstrip(".")
WA_ORIGINS_ENV = [o.strip().rstrip("/") for o in os.environ.get("KALMIDO_WEBAUTHN_ORIGINS", "").split(",") if o.strip()]
_PEND, _PEND_LOCK = {}, threading.Lock()
_AUTH_KEY = {}


def auth_key(c):
    if "k" not in _AUTH_KEY:
        _AUTH_KEY["k"] = HKDF(algorithm=hashes.SHA256(), length=32, salt=b"kalmido-auth",
                              info=b"sign-in secrets v1").derive(bytes.fromhex(gsetting(c, "auth_secret")))
    return _AUTH_KEY["k"]


def seal(c, purpose, s):
    """AES-GCM with the server key; purpose (e.g. 'totp:5') is bound as associated data."""
    if not s:
        return ""
    n = os.urandom(12)
    return "v1." + _b64u(n + AESGCM(auth_key(c)).encrypt(n, s.encode(), f"kalmido-auth:{purpose}".encode()))


def unseal(c, purpose, s):
    if not s:
        return ""
    raw = _b64u_dec(s[3:])
    return AESGCM(auth_key(c)).decrypt(raw[:12], raw[12:], f"kalmido-auth:{purpose}".encode()).decode()


# ---- tickets / challenges (in memory: a restart simply asks for the password again)
def _pend_gc():
    now = time.time()
    for k in [k for k, v in _PEND.items() if v["exp"] < now]:
        del _PEND[k]
    if len(_PEND) > PEND_MAX:
        for k in sorted(_PEND, key=lambda k: _PEND[k]["exp"])[:len(_PEND) - PEND_MAX]:
            del _PEND[k]


def pend_new(kind, uid, **data):
    tok = secrets.token_urlsafe(32)
    with _PEND_LOCK:
        _pend_gc()
        _PEND["t:" + _token_hash(tok)] = {"kind": kind, "uid": uid, "exp": time.time() + PEND_TTL, "tries": 0, **data}
    return tok


def pend_cookie(resp, tok):
    secure = request.is_secure or request.headers.get("X-Forwarded-Proto", "") == "https"
    resp.set_cookie(PEND_COOKIE, tok, max_age=PEND_TTL, httponly=True, samesite="Strict", secure=secure, path="/api/auth")
    return resp


def pend_get(kinds):
    """The ticket of this browser (dict, shared: changes stick) if it is one of `kinds`, else None."""
    tok = request.cookies.get(PEND_COOKIE) or ""
    if not tok:
        return None
    with _PEND_LOCK:
        _pend_gc()
        p = _PEND.get("t:" + _token_hash(tok))
    return p if p and p["kind"] in kinds else None


def pend_drop():
    tok = request.cookies.get(PEND_COOKIE) or ""
    with _PEND_LOCK:
        _PEND.pop("t:" + _token_hash(tok), None)


def pend_set(key, **data):
    """Per-user state of a logged-in user (TOTP enrolment secret, WebAuthn registration challenge)."""
    with _PEND_LOCK:
        _pend_gc()
        _PEND[key] = {"exp": time.time() + PEND_TTL, **data}


def pend_take(key):
    with _PEND_LOCK:
        _pend_gc()
        return _PEND.pop(key, None)


# ---- TOTP (RFC 6238 / RFC 4226)
def totp_code(key, step):
    mac = hmac.new(key, struct.pack(">Q", step), hashlib.sha1).digest()  # HOTP is defined with HMAC-SHA-1
    o = mac[-1] & 0x0F
    return str((struct.unpack(">I", mac[o:o + 4])[0] & 0x7FFFFFFF) % 10 ** TOTP_DIGITS).zfill(TOTP_DIGITS)


def totp_match(secret_b32, code, last_step=0):
    """The matching time step (now ±1, newer than last_step) or None."""
    code = re.sub(r"\s", "", str(code or ""))
    if not re.fullmatch(r"\d{%d}" % TOTP_DIGITS, code):
        return None
    try:
        key = base64.b32decode(secret_b32 + "=" * (-len(secret_b32) % 8))
    except (ValueError, TypeError):
        return None
    now = int(time.time() // TOTP_STEP)
    for st in (now - 1, now, now + 1):
        if st > (last_step or 0) and hmac.compare_digest(totp_code(key, st), code):
            return st
    return None


def totp_new_secret():
    return base64.b32encode(secrets.token_bytes(20)).decode().rstrip("=")


def totp_uri(secret, username):
    label = urllib.parse.quote(f"{APP_NAME}:{username}", safe=":@")
    return f"otpauth://totp/{label}?secret={secret}&issuer={urllib.parse.quote(APP_NAME)}&algorithm=SHA1&digits={TOTP_DIGITS}&period={TOTP_STEP}"


def totp_payload(secret, username):
    """What the client shows for the enrolment: secret (grouped), otpauth link and a QR code (SVG data URI, made here:
    no external request)."""
    uri = totp_uri(secret, username)
    return {"secret": " ".join(secret[i:i + 4] for i in range(0, len(secret), 4)), "uri": uri,
            "qr": segno.make(uri, error="m").svg_data_uri(scale=5, border=2, dark="#000", light="#fff")}


# ---- recovery codes
def rc_norm(code):
    return re.sub(r"[\s-]", "", str(code or "")).lower()


def rc_hash(code):
    return hashlib.sha256(("kalmido-recovery:" + rc_norm(code)).encode()).hexdigest()


def rc_new(c, uid):
    """10 new codes (the old ones stop working); returns them once, only the hashes are stored."""
    c.execute("DELETE FROM recovery_codes WHERE user_id=?", (uid,))
    codes = []
    for _ in range(RC_COUNT):
        raw = "".join(secrets.choice(RC_ALPHABET) for _ in range(10))
        codes.append(raw[:5] + "-" + raw[5:])
        c.execute("INSERT INTO recovery_codes(user_id,code_hash,created_at) VALUES(?,?,?)", (uid, rc_hash(raw), iso(now_utc())))
    return codes


def rc_use(c, uid, code):
    if len(rc_norm(code)) != 10:
        return False
    r = c.execute("SELECT id FROM recovery_codes WHERE user_id=? AND code_hash=? AND used_at IS NULL", (uid, rc_hash(code))).fetchone()
    if not r:
        return False
    return c.execute("UPDATE recovery_codes SET used_at=? WHERE id=? AND used_at IS NULL", (iso(now_utc()), r[0])).rowcount == 1


def rc_left(c, uid):
    return c.execute("SELECT COUNT(*) FROM recovery_codes WHERE user_id=? AND used_at IS NULL", (uid,)).fetchone()[0]


def twofa_methods(c, u):
    """Second factors of an account with a password: [] = none."""
    if not u["password_hash"]:
        return []
    out = []
    if u["totp_secret"]:
        out.append("totp")
    if c.execute("SELECT 1 FROM webauthn_creds WHERE user_id=?", (u["id"],)).fetchone():
        out.append("passkey")
    if out and rc_left(c, u["id"]):
        out.append("recovery")
    return out


def twofa_clear(c, uid):
    c.execute("UPDATE users SET totp_secret=NULL, totp_step=0 WHERE id=?", (uid,))
    c.execute("DELETE FROM webauthn_creds WHERE user_id=?", (uid,))
    c.execute("DELETE FROM recovery_codes WHERE user_id=?", (uid,))


def _user(c, uid):
    return c.execute("SELECT * FROM users WHERE id=?", (uid,)).fetchone()


def _code_fail(u, p=None):
    """A wrong second factor: counts like a wrong password; the ticket dies after PEND_TRIES."""
    keys = _rate_keys(u["username"])
    _rate_fail(keys)
    aa_count("security", "logins", client_ip(), user=u["username"])
    print("second factor failed for", repr(u["username"]), "from", client_ip(), flush=True)
    if p is not None:
        p["tries"] += 1
        if p["tries"] >= PEND_TRIES:
            pend_drop()


def _ticket(kinds):
    """(ticket, user) of this browser or an error response."""
    p = pend_get(kinds)
    if not p:
        return None, None, (jsonify(error=tr("The login has expired, please log in again"), expired=True), 401)
    u = _user(db(), p["uid"])
    if not u or u["disabled"] or not u["password_hash"]:
        pend_drop()
        return None, None, (jsonify(error=tr("The login has expired, please log in again"), expired=True), 401)
    if _rate_blocked(_rate_keys(u["username"])):
        return None, None, err(tr("Too many failed logins, please wait a few minutes"), 429)
    return p, u, None


# ---- WebAuthn (passkeys)
def _req_origin():
    o = (request.headers.get("Origin") or "").strip().rstrip("/")
    if o and o != "null":
        return o
    proto = request.headers.get("X-Forwarded-Proto", "") if _peer_trusted() else ""
    return f"{proto or request.scheme}://{request.host}"


def _origin_host(o):
    try:
        return (urllib.parse.urlsplit(o).hostname or "").lower()
    except ValueError:
        return ""


def wa_context():
    """(rp_id, [expected origins]) for this request. The page's origin counts when it is PUBLIC_URL, one of
    KALMIDO_WEBAUTHN_ORIGINS or localhost; otherwise PUBLIC_URL's host is the RP ID."""
    public = PUBLIC_URL.rstrip("/")
    allowed = [public] + WA_ORIGINS_ENV
    o = _req_origin()
    host = _origin_host(o)
    if o not in allowed and not (host == "localhost" or host.endswith(".localhost")):
        o = public
    rp = WA_RP_ID_ENV or _origin_host(o)
    origins = [x for x in dict.fromkeys(allowed + [o]) if _origin_host(x) == rp or _origin_host(x).endswith("." + rp)]
    return rp, origins


def wa_handle(c, u):
    if u["webauthn_handle"]:
        return _b64u_dec(u["webauthn_handle"])
    h = secrets.token_bytes(32)
    c.execute("UPDATE users SET webauthn_handle=? WHERE id=?", (_b64u(h), u["id"]))
    c.commit()
    return h


def wa_json(opts):
    return json.loads(webauthn.options_to_json(opts))


def wa_reg_options(c, u):
    rp, _ = wa_context()
    creds = c.execute("SELECT cred_id, transports FROM webauthn_creds WHERE user_id=?", (u["id"],)).fetchall()
    opts = webauthn.generate_registration_options(
        rp_id=rp, rp_name=APP_NAME, user_id=wa_handle(c, u), user_name=u["username"],
        user_display_name=u["display_name"] or u["username"],
        exclude_credentials=[wa_structs.PublicKeyCredentialDescriptor(id=_b64u_dec(r["cred_id"])) for r in creds],
        authenticator_selection=wa_structs.AuthenticatorSelectionCriteria(
            resident_key=wa_structs.ResidentKeyRequirement.PREFERRED,
            user_verification=wa_structs.UserVerificationRequirement.PREFERRED),
        attestation=wa_structs.AttestationConveyancePreference.NONE)
    return opts.challenge, rp, wa_json(opts)


def wa_reg_verify(c, u, cred, chal, rp, name):
    """Stores the new passkey; returns its row id or raises ValueError (message is safe to show)."""
    _, origins = wa_context()
    if not isinstance(cred, dict):
        raise ValueError(tr("The passkey could not be registered"))
    try:
        v = webauthn.verify_registration_response(credential=cred, expected_challenge=chal, expected_rp_id=rp,
                                                  expected_origin=origins, require_user_verification=False)
    except Exception as e:  # noqa: BLE001  (every parse / verification error of the library)
        print("passkey registration refused:", type(e).__name__, str(e)[:120], flush=True)
        raise ValueError(tr("The passkey could not be registered")) from None
    cid = _b64u(v.credential_id)
    if c.execute("SELECT 1 FROM webauthn_creds WHERE cred_id=?", (cid,)).fetchone():
        raise ValueError(tr("This passkey is already registered"))
    if c.execute("SELECT COUNT(*) FROM webauthn_creds WHERE user_id=?", (u["id"],)).fetchone()[0] >= PASSKEY_MAX:
        raise ValueError(tr("At most {0} passkeys", PASSKEY_MAX))
    resp = cred.get("response") if isinstance(cred.get("response"), dict) else {}
    tr_ = [t for t in (resp.get("transports") or []) if isinstance(t, str) and t in WA_TRANSPORTS] \
        if isinstance(resp.get("transports"), list) else []
    ext = cred.get("clientExtensionResults") if isinstance(cred.get("clientExtensionResults"), dict) else {}
    rk = (ext.get("credProps") or {}).get("rk") if isinstance(ext.get("credProps"), dict) else None
    name = (str(name or "").strip() or tr("Passkey"))[:PASSKEY_NAME_MAX]
    return c.execute("""INSERT INTO webauthn_creds(user_id,cred_id,public_key,sign_count,transports,name,rp_id,aaguid,backed_up,
                                                   discoverable,created_at) VALUES(?,?,?,?,?,?,?,?,?,?,?)""",
                     (u["id"], cid, v.credential_public_key, v.sign_count, ",".join(tr_), name, rp, str(v.aaguid or ""),
                      1 if v.credential_backed_up else 0, None if rk is None else (1 if rk else 0), iso(now_utc()))).lastrowid


def wa_auth_options(c, uid=None, uv=False):
    rp, _ = wa_context()
    allow = []
    if uid is not None:
        allow = [wa_structs.PublicKeyCredentialDescriptor(
            id=_b64u_dec(r["cred_id"]),
            transports=[wa_structs.AuthenticatorTransport(t) for t in r["transports"].split(",") if t in WA_TRANSPORTS - {"cable"}] or None)
            for r in c.execute("SELECT cred_id, transports FROM webauthn_creds WHERE user_id=?", (uid,))]
    opts = webauthn.generate_authentication_options(
        rp_id=rp, allow_credentials=allow,
        user_verification=wa_structs.UserVerificationRequirement.REQUIRED if uv else wa_structs.UserVerificationRequirement.PREFERRED)
    return opts.challenge, rp, wa_json(opts)


def wa_auth_verify(c, cred, chal, rp, uid=None, uv=False):
    """The user id the passkey belongs to (uid given: it must be that user's) or None."""
    if not isinstance(cred, dict) or not isinstance(cred.get("rawId") or cred.get("id"), str):
        return None
    cid = cred.get("rawId") or cred.get("id")
    row = c.execute("SELECT * FROM webauthn_creds WHERE cred_id=?", (cid[:1400],)).fetchone()
    if not row or (uid is not None and row["user_id"] != uid):
        return None
    u = _user(c, row["user_id"])
    if not u or u["disabled"]:
        return None
    resp = cred.get("response") if isinstance(cred.get("response"), dict) else {}
    try:
        uh = _b64u_dec(resp["userHandle"]) if resp.get("userHandle") else b""
        mine = _b64u_dec(u["webauthn_handle"]) if u["webauthn_handle"] else b""
    except (ValueError, TypeError):
        return None
    if uid is None and (not uh or not mine or not hmac.compare_digest(uh, mine)):
        return None  # passwordless: the discoverable credential must name this account
    _, origins = wa_context()
    try:
        v = webauthn.verify_authentication_response(credential=cred, expected_challenge=chal, expected_rp_id=rp,
                                                    expected_origin=origins, credential_public_key=row["public_key"],
                                                    credential_current_sign_count=row["sign_count"], require_user_verification=uv)
    except Exception as e:  # noqa: BLE001
        print("passkey assertion refused:", type(e).__name__, str(e)[:120], flush=True)
        return None
    c.execute("UPDATE webauthn_creds SET sign_count=?, last_used_at=?, backed_up=? WHERE id=?",
              (v.new_sign_count, iso(now_utc()), 1 if v.credential_backed_up else 0, row["id"]))
    return row["user_id"]


def passkey_public(r):
    return {"id": r["id"], "name": r["name"], "created_at": r["created_at"], "last_used_at": r["last_used_at"],
            "synced": bool(r["backed_up"]), "discoverable": r["discoverable"], "rp_id": r["rp_id"]}


# ---- login: second step
@app.post("/api/auth/2fa")
def auth_2fa():
    """{code} (authenticator app) or {recovery} after a correct password."""
    p, u, e = _ticket(("2fa",))
    if e:
        return e
    c, b = db(), body()
    ok, via = False, "totp"
    if b.get("recovery"):
        ok = rc_use(c, u["id"], b.get("recovery"))
        via = "recovery"
    elif u["totp_secret"]:
        try:
            secret = unseal(c, f"totp:{u['id']}", u["totp_secret"])
        except (InvalidTag, ValueError):
            secret = ""
        st = totp_match(secret, b.get("code"), u["totp_step"]) if secret else None
        if st:
            ok = c.execute("UPDATE users SET totp_step=? WHERE id=? AND totp_step<?", (st, u["id"], st)).rowcount == 1
    if not ok:
        _code_fail(u, p)
        c.rollback()
        return err(tr("Wrong code"), 401)
    pend_drop()
    left = rc_left(c, u["id"])
    if via == "recovery":
        aa_now("security", f"recovery:{u['username']}:{int(time.time())}",
               N_("{0} logged in with a recovery code ({1} left)."), [u["username"], left])
    return finish_login(c, u, p.get("remember", True), "2fa", {"recovery_left": left} if via == "recovery" else None)


