    uid = wa_auth_verify(c, body().get("credential"), chal, rp, uid=u["id"]) if chal else None
    if uid != u["id"]:
        _code_fail(u, p)
        c.rollback()
        return err(tr("The passkey was not accepted"), 401)
    pend_drop()
    return finish_login(c, u, p.get("remember", True), "2fa")


