@app.post("/api/me/passkeys")
def me_pk_add():
    u, c, b = g.user, db(), body()
    p = pend_take(f"wareg:{u['id']}")
    if not p:
        return err(tr("The setup has expired, please start again"), 409)
    first = not twofa_methods(c, u)
    try:
        wa_reg_verify(c, u, b.get("credential"), p["chal"], p["rp"], b.get("name"))
    except ValueError as x:
        c.rollback()
        return err(str(x), 400)
    codes = rc_new(c, u["id"]) if not rc_left(c, u["id"]) else None
    if first:
        _end_other_sessions(c, u["id"])
    c.commit()
    aa_now("security", f"2fa:{u['username']}:{int(time.time())}", N_("{0} turned on two-factor authentication ({1})."),
           [u["username"], {"t": N_("passkey")}])
    return jsonify(recovery_codes=codes, **twofa_state(c, _user(c, u["id"])))


@app.patch("/api/me/passkeys/<int:pid>")
def me_pk_rename(pid):
    u, c = g.user, db()
    name = str(body().get("name") or "").strip()[:PASSKEY_NAME_MAX]
    if not name:
        return err(tr("Name missing"))
    if not c.execute("UPDATE webauthn_creds SET name=? WHERE id=? AND user_id=?", (name, pid, u["id"])).rowcount:
        return err(tr("unknown"), 404)
    c.commit()
    return jsonify(twofa_state(c, u))


@app.delete("/api/me/passkeys/<int:pid>")
def me_pk_delete(pid):
    u, c, b = g.user, db(), body()
    e = _reauth(u, b)
    if e:
        return e
    if not c.execute("SELECT 1 FROM webauthn_creds WHERE id=? AND user_id=?", (pid, u["id"])).fetchone():
        return err(tr("unknown"), 404)
    e = _last_factor_guard(c, u, "passkey")
    if e:
        return e
    c.execute("DELETE FROM webauthn_creds WHERE id=? AND user_id=?", (pid, u["id"]))
    if not u["totp_secret"] and not c.execute("SELECT 1 FROM webauthn_creds WHERE user_id=?", (u["id"],)).fetchone():
        c.execute("DELETE FROM recovery_codes WHERE user_id=?", (u["id"],))
    c.commit()
    return jsonify(twofa_state(c, _user(c, u["id"])))


# ---------------------------------------------------------------- OIDC login (generic OpenID Connect provider)
# Authorization Code flow with PKCE (S256), state (bound to this browser by an HttpOnly cookie, one-time, 10 min) and
# nonce. Discovery from KALMIDO_OIDC_ISSUER/.well-known/openid-configuration; the ID token is checked here: signature
# with the provider's JWKS (RSA, RSA-PSS, ECDSA, Ed25519; never "none" or HMAC; keys cached for an hour, fetched again
# for an unknown key id), iss, aud, azp, exp, iat, nbf, nonce. Extra claims come from the userinfo endpoint (same sub).
# Every request to the provider goes through the SSRF guard of the calendar subscriptions (cal_http): public
# addresses only, unless the host is allow-listed (KALMIDO_OIDC_ALLOW_HOSTS or Settings > Users > Whole server).
# Accounts: a user linked to the subject (issuer|sub) logs in; otherwise the first login links the user whose
# username equals the username claim or whose e-mail equals the (verified) e-mail claim. Without a match: "no
# account", unless the admin turned on "Create accounts on first login". Optional required group; optional admin group
# (the admin flag then follows the group, the last active admin is never demoted). Secrets are never logged.
OIDC_ISSUER = os.environ.get("KALMIDO_OIDC_ISSUER", "").strip()
OIDC_CLIENT_ID = os.environ.get("KALMIDO_OIDC_CLIENT_ID", "").strip()
OIDC_CLIENT_SECRET = os.environ.get("KALMIDO_OIDC_CLIENT_SECRET", "").strip()
OIDC_SCOPES = " ".join((os.environ.get("KALMIDO_OIDC_SCOPES", "") or "openid profile email").replace(",", " ").split())
if "openid" not in OIDC_SCOPES.split():
    OIDC_SCOPES = "openid " + OIDC_SCOPES
OIDC_USERNAME_CLAIM = os.environ.get("KALMIDO_OIDC_USERNAME_CLAIM", "").strip() or "preferred_username"
OIDC_GROUPS_CLAIM = os.environ.get("KALMIDO_OIDC_GROUPS_CLAIM", "").strip() or "groups"
OIDC_REQUIRED_GROUP = os.environ.get("KALMIDO_OIDC_REQUIRED_GROUP", "").strip()
OIDC_ADMIN_GROUP = os.environ.get("KALMIDO_OIDC_ADMIN_GROUP", "").strip()
OIDC_LABEL = (os.environ.get("KALMIDO_OIDC_BUTTON_LABEL", "").strip() or "OpenID Connect")[:40]
OIDC_ALLOW_ENV = os.environ.get("KALMIDO_OIDC_ALLOW_HOSTS", "")
OIDC_ON = bool(OIDC_ISSUER and OIDC_CLIENT_ID)
OIDC_REDIRECT = PUBLIC_URL.rstrip("/") + "/api/auth/oidc/callback"
OIDC_COOKIE = "kalmido_oidc"
OIDC_STATE_TTL = 600
OIDC_CACHE = 3600
OIDC_LEEWAY = 60
OIDC_ALGS = {"RS256", "RS384", "RS512", "PS256", "PS384", "PS512", "ES256", "ES384", "ES512", "EdDSA"}
_OIDC = {"doc": None, "doc_at": 0.0, "jwks": None, "jwks_at": 0.0, "err": "", "err_at": ""}
_OIDC_STATES, _OIDC_LOCK = {}, threading.Lock()
OIDC_ERRORS = {"no_account": N_("There is no account for this login yet. Please ask the admin to create one."),
               "disabled": N_("This account is disabled."),
               "group": N_("Your account at the login provider is not allowed to use this app."),
               "state": N_("The login took too long or was started in another browser. Please try again."),
               "denied": N_("The login was cancelled at the login provider."),
               "taken": N_("The user name from the login provider is already used by another account."),
               "failed": N_("The login with the provider failed. Please try again or ask the admin.")}


class OidcError(Exception):
    def __init__(self, code, detail=""):
        super().__init__(code)
        self.code, self.detail = code, str(detail)[:80]


def oidc_allow(c):
    return frozenset(cal_allow(c) | set(cal_allow_parse(OIDC_ALLOW_ENV)[0]))


def _oidc_url_ok(u, allow):
    """https, or http for an allow-listed (internal) host."""
    p = urllib.parse.urlsplit(u or "")
    if not p.hostname or p.username or p.password:
        return False
    try:
        port = p.port
    except ValueError:
        return False
    return p.scheme == "https" or (p.scheme == "http" and cal_host_allowed(allow, p.hostname, port or 80))


def oidc_http_json(c, url, method="GET", data=None, headers=None, auth=None):
    allow = oidc_allow(c)
    if not _oidc_url_ok(url, allow):
        raise OidcError("config", "not https and not an allowed internal host")
    hd = {"User-Agent": f"{APP_NAME}/{APP_VERSION} (OpenID Connect)", "Accept": "application/json", **(headers or {})}
    try:
        st, h, raw, _ = cal_http(url, method=method, body=data, headers=hd, auth=auth, allow=allow)
    except CalError as e:
        if e.code in ("http", "auth", "not_found"):  # an HTTP error status: the body is not read (never logged)
            raise OidcError("http", e.detail or e.code) from None
        raise OidcError("network", e.code) from None
    try:
        j = json.loads(raw.decode("utf-8"))
    except (ValueError, UnicodeDecodeError):
        raise OidcError("json") from None
    if not isinstance(j, dict):
        raise OidcError("json")
    return j


def oidc_doc(c, force=False):
    now = time.time()
    if _OIDC["doc"] and not force and now - _OIDC["doc_at"] < OIDC_CACHE:
        return _OIDC["doc"]
    try:
        d = oidc_http_json(c, OIDC_ISSUER.rstrip("/") + "/.well-known/openid-configuration")
        if str(d.get("issuer") or "").rstrip("/") != OIDC_ISSUER.rstrip("/"):
            raise OidcError("config", "issuer mismatch")
        allow = oidc_allow(c)
        for k in ("authorization_endpoint", "token_endpoint", "jwks_uri"):
            if not isinstance(d.get(k), str) or not _oidc_url_ok(d[k], allow):
                raise OidcError("config", k)
        if d.get("userinfo_endpoint") and not _oidc_url_ok(str(d["userinfo_endpoint"]), allow):
            d["userinfo_endpoint"] = None
        _OIDC.update(doc=d, doc_at=now, err="")
        return d
    except OidcError as e:
        _OIDC.update(err=e.code + (":" + e.detail if e.detail else ""), err_at=iso(now_utc()))
        aa_fail("oidc", e.code)
        raise


def oidc_jwks(c, doc, force=False):
    now = time.time()
    if _OIDC["jwks"] is not None and not force and now - _OIDC["jwks_at"] < OIDC_CACHE:
        return _OIDC["jwks"]
    if force and now - _OIDC["jwks_at"] < 10:  # an unknown key id asks again at most every 10 s
        return _OIDC["jwks"] or []
    j = oidc_http_json(c, doc["jwks_uri"])
    keys = [k for k in (j.get("keys") or []) if isinstance(k, dict)] if isinstance(j.get("keys"), list) else []
    _OIDC.update(jwks=keys, jwks_at=now)
    return keys


def _b64u_int(s):
    return int.from_bytes(_b64u_dec(s), "big")


_EC = {"ES256": (ec.SECP256R1, "P-256", hashes.SHA256, 32), "ES384": (ec.SECP384R1, "P-384", hashes.SHA384, 48),
       "ES512": (ec.SECP521R1, "P-521", hashes.SHA512, 66)}
_SHA = {"256": hashes.SHA256, "384": hashes.SHA384, "512": hashes.SHA512}


def jwk_verify(k, alg, data, sig):
    """True when sig is a valid signature of data by the JWK k with alg (the key type must fit the algorithm)."""
    try:
        if k.get("use") not in (None, "sig") or (k.get("alg") and k["alg"] != alg):
            return False
        if alg[:2] in ("RS", "PS"):
            if k.get("kty") != "RSA":
                return False
            pub = rsa.RSAPublicNumbers(_b64u_int(k["e"]), _b64u_int(k["n"])).public_key()
            if pub.key_size < 2048:
                return False
            h = _SHA[alg[2:]]()
            pad = padding.PKCS1v15() if alg[:2] == "RS" else padding.PSS(mgf=padding.MGF1(h), salt_length=h.digest_size)
            pub.verify(sig, data, pad, h)
            return True
        if alg in _EC:
            curve, crv, h, n = _EC[alg]
            if k.get("kty") != "EC" or k.get("crv") != crv or len(sig) != 2 * n:
                return False
            pub = ec.EllipticCurvePublicNumbers(_b64u_int(k["x"]), _b64u_int(k["y"]), curve()).public_key()
            pub.verify(encode_dss_signature(int.from_bytes(sig[:n], "big"), int.from_bytes(sig[n:], "big")), data, ec.ECDSA(h()))
            return True
        if alg == "EdDSA":
            if k.get("kty") != "OKP" or k.get("crv") != "Ed25519":
                return False
            ed25519.Ed25519PublicKey.from_public_bytes(_b64u_dec(k["x"])).verify(sig, data)
            return True
    except (InvalidSignature, KeyError, ValueError, TypeError):
        return False
    return False


def oidc_verify_id_token(c, doc, tok, nonce):
    parts = tok.split(".") if isinstance(tok, str) and len(tok) < 20000 else []
    if len(parts) != 3:
        raise OidcError("token", "format")
    try:
        head = json.loads(_b64u_dec(parts[0]))
        claims = json.loads(_b64u_dec(parts[1]))
        sig = _b64u_dec(parts[2])
    except (ValueError, TypeError):
        raise OidcError("token", "format") from None
    if not isinstance(head, dict) or not isinstance(claims, dict):
        raise OidcError("token", "format")
    alg = head.get("alg")
    offered = doc.get("id_token_signing_alg_values_supported")
    if alg not in OIDC_ALGS or (isinstance(offered, list) and alg not in offered):
        raise OidcError("token", "alg")
    if head.get("crit"):
        raise OidcError("token", "crit")
    data = (parts[0] + "." + parts[1]).encode()
    kid = head.get("kid")

    def pick(keys):
        return [k for k in keys if not kid or k.get("kid") == kid]
    keys = pick(oidc_jwks(c, doc))
    if not keys and kid:
        keys = pick(oidc_jwks(c, doc, force=True))
    if not any(jwk_verify(k, alg, data, sig) for k in keys):
        raise OidcError("token", "signature")
    now = time.time()
    aud = claims.get("aud")
    auds = aud if isinstance(aud, list) else [aud]
    if str(claims.get("iss") or "") != str(doc["issuer"]):
        raise OidcError("token", "iss")
    if OIDC_CLIENT_ID not in auds:
        raise OidcError("token", "aud")
    if (len(auds) > 1 or "azp" in claims) and claims.get("azp") != OIDC_CLIENT_ID:
        raise OidcError("token", "azp")
    for k in ("exp", "iat"):
        if isinstance(claims.get(k), bool) or not isinstance(claims.get(k), (int, float)):
            raise OidcError("token", k)
    if claims["exp"] < now - OIDC_LEEWAY:
        raise OidcError("token", "exp")
    if claims["iat"] > now + OIDC_LEEWAY * 5:
        raise OidcError("token", "iat")
    if isinstance(claims.get("nbf"), (int, float)) and claims["nbf"] > now + OIDC_LEEWAY:
        raise OidcError("token", "nbf")
    if not isinstance(claims.get("nonce"), str) or not hmac.compare_digest(claims["nonce"], nonce):
        raise OidcError("token", "nonce")
    if not isinstance(claims.get("sub"), str) or not 0 < len(claims["sub"]) <= 255:
        raise OidcError("token", "sub")
    return claims


def _oidc_groups(v):
    if isinstance(v, str):
        return {x.strip() for x in v.split(",") if x.strip()}
    if isinstance(v, list):
        return {str(x) for x in v if isinstance(x, (str, int))}
    return set()


def _truthy(v):
    return v is True or (isinstance(v, str) and v.lower() == "true")


def oidc_account(c, claims):
    """The user for these claims (links / creates as configured) or OidcError(no_account|disabled|group|taken)."""
    subject = f"{claims['iss']}|{claims['sub']}"
    groups = _oidc_groups(claims.get(OIDC_GROUPS_CLAIM))
    if OIDC_REQUIRED_GROUP and OIDC_REQUIRED_GROUP not in groups:
        raise OidcError("group")
    uname = str(claims.get(OIDC_USERNAME_CLAIM) or "").strip().lower()
    email = str(claims.get("email") or "").strip().lower() if _truthy(claims.get("email_verified")) else ""
    u = c.execute("SELECT * FROM users WHERE oidc_subject=?", (subject,)).fetchone()
    how = "subject"
    if not u and uname:
        u = c.execute("SELECT * FROM users WHERE username=? AND oidc_subject IS NULL", (uname,)).fetchone()
        how = "username"
    if not u and email:
        u = c.execute("SELECT * FROM users WHERE lower(email)=? AND oidc_subject IS NULL", (email,)).fetchone()
        how = "email"
    if not u:
        if gsetting(c, "oidc_autocreate") != "1":
            raise OidcError("no_account", uname or "?")
        if not USERNAME_RE.fullmatch(uname):
            raise OidcError("taken", "invalid username claim")
        if c.execute("SELECT 1 FROM users WHERE username=?", (uname,)).fetchone():
            raise OidcError("taken", uname)
        name = str(claims.get("name") or "").strip()[:60] or uname
        uid = create_user(c, uname, name, None, None, bool(OIDC_ADMIN_GROUP and OIDC_ADMIN_GROUP in groups), onboard=True)
        ensure_inbox(c, uid)
        c.execute("UPDATE users SET oidc_subject=?, email=? WHERE id=?", (subject, email or None, uid))
        bump(c)
        aa_now("security", f"oidc:new:{uname}", N_("{0} was created by the first login with the OIDC provider."), [uname])
        return _user(c, uid)
    if u["disabled"]:
        raise OidcError("disabled", u["username"])
    if how != "subject":
        c.execute("UPDATE users SET oidc_subject=? WHERE id=?", (subject, u["id"]))
        aa_now("security", f"oidc:link:{u['username']}", N_("{0} was linked to the OIDC provider (matched by {1})."),
               [u["username"], {"t": N_("user name") if how == "username" else N_("e-mail")}])
    if OIDC_ADMIN_GROUP:
        want = OIDC_ADMIN_GROUP in groups
        if want != bool(u["is_admin"]) and (want or _active_admins(c, u["id"])):
            c.execute("UPDATE users SET is_admin=? WHERE id=?", (1 if want else 0, u["id"]))
            aa_now("security", f"oidc:admin:{u['username']}:{int(want)}",
                   N_("{0} is now an admin (set by {1}).") if want else N_("{0} is no longer an admin (OIDC group)."),
                   [u["username"], "OIDC"] if want else [u["username"]])
    return _user(c, u["id"])


def _oidc_fail_redirect(code):
    resp = redirect("/#login-error=" + code, 303)
    resp.delete_cookie(OIDC_COOKIE, path="/api/auth/oidc")
    return resp


@app.get("/api/auth/oidc/start")
def oidc_start():
    if not OIDC_ON:
        return err(tr("OIDC login is not configured"), 404)
    ip_key = [("oidc:" + client_ip(), 60)]
    if _rate_blocked(ip_key):
        return err(tr("Too many failed logins, please wait a few minutes"), 429)
    _rate_fail(ip_key)  # every start counts (60 per 15 min and IP): the state table cannot be flooded
    c = db()
    try:
        doc = oidc_doc(c)
    except OidcError as e:
        print("OIDC discovery failed:", e.code, e.detail, flush=True)
        return _oidc_fail_redirect("failed")
    state, nonce, verifier, bind = (secrets.token_urlsafe(32) for _ in range(4))
    now = time.time()
    with _OIDC_LOCK:
        for k in [k for k, v in _OIDC_STATES.items() if v["exp"] < now]:
            del _OIDC_STATES[k]
        if len(_OIDC_STATES) >= 1000:
            del _OIDC_STATES[min(_OIDC_STATES, key=lambda k: _OIDC_STATES[k]["exp"])]
        _OIDC_STATES[state] = {"bind": _token_hash(bind), "nonce": nonce, "verifier": verifier, "exp": now + OIDC_STATE_TTL,
                               "remember": request.args.get("remember", "1") != "0"}
    q = {"response_type": "code", "client_id": OIDC_CLIENT_ID, "redirect_uri": OIDC_REDIRECT, "scope": OIDC_SCOPES,
         "state": state, "nonce": nonce, "code_challenge_method": "S256",
         "code_challenge": _b64u(hashlib.sha256(verifier.encode()).digest())}
    ae = doc["authorization_endpoint"]
    resp = redirect(ae + ("&" if "?" in ae else "?") + urllib.parse.urlencode(q), 302)
    secure = request.is_secure or request.headers.get("X-Forwarded-Proto", "") == "https"
    resp.set_cookie(OIDC_COOKIE, bind, max_age=OIDC_STATE_TTL, httponly=True, samesite="Lax", secure=secure, path="/api/auth/oidc")
    return resp


@app.get("/api/auth/oidc/callback")
def oidc_callback():
    if not OIDC_ON:
        return err(tr("OIDC login is not configured"), 404)
    state = request.args.get("state") or ""
    with _OIDC_LOCK:
        st = _OIDC_STATES.pop(state, None) if state else None
    bind = request.cookies.get(OIDC_COOKIE) or ""
    if not st or st["exp"] < time.time() or not bind or not hmac.compare_digest(st["bind"], _token_hash(bind)):
        return _oidc_fail_redirect("state")
    if request.args.get("error"):
        return _oidc_fail_redirect("denied")
    code = request.args.get("code") or ""
    if not code or len(code) > 4000:
        return _oidc_fail_redirect("failed")
    c = db()
    try:
        doc = oidc_doc(c)
        form = {"grant_type": "authorization_code", "code": code, "redirect_uri": OIDC_REDIRECT, "code_verifier": st["verifier"]}
        methods = doc.get("token_endpoint_auth_methods_supported") or ["client_secret_basic"]
        auth = None
        if OIDC_CLIENT_SECRET and "client_secret_basic" in methods:
            auth = (urllib.parse.quote(OIDC_CLIENT_ID, safe=""), urllib.parse.quote(OIDC_CLIENT_SECRET, safe=""))
        else:
            form["client_id"] = OIDC_CLIENT_ID
            if OIDC_CLIENT_SECRET:
                form["client_secret"] = OIDC_CLIENT_SECRET
        tokr = oidc_http_json(c, doc["token_endpoint"], "POST", urllib.parse.urlencode(form).encode(),
                              {"Content-Type": "application/x-www-form-urlencoded"}, auth)
        claims = oidc_verify_id_token(c, doc, tokr.get("id_token"), st["nonce"])
        at = tokr.get("access_token")
        if doc.get("userinfo_endpoint") and isinstance(at, str) and at and str(tokr.get("token_type", "")).lower() == "bearer":
            try:
                ui = oidc_http_json(c, doc["userinfo_endpoint"], headers={"Authorization": "Bearer " + at})
                if ui.get("sub") == claims["sub"]:
                    claims = {**{k: v for k, v in ui.items() if k not in ("iss", "aud", "exp", "iat", "nbf", "nonce", "azp")}, **claims}
            except OidcError as e:
                print("OIDC userinfo skipped:", e.code, e.detail, flush=True)
        u = oidc_account(c, claims)
    except OidcError as e:
        c.rollback()
        if e.code in ("no_account", "disabled", "group", "taken"):
            print("OIDC login refused:", e.code, e.detail, flush=True)
            aa_count("security", "logins", client_ip(), user="oidc:" + e.code)
            return _oidc_fail_redirect(e.code)
        print("OIDC login failed:", e.code, e.detail, flush=True)
        _OIDC.update(err=e.code + (":" + e.detail if e.detail else ""), err_at=iso(now_utc()))
        aa_fail("oidc", e.code)
        return _oidc_fail_redirect("failed")
    aa_ok("oidc")
    _OIDC["err"] = ""
    old = request.cookies.get(COOKIE)
    if old:
        c.execute("DELETE FROM sessions WHERE token_hash=?", (_token_hash(old),))
    tok, age = start_session(c, u["id"], st["remember"], "oidc")
    c.commit()
    resp = set_cookie(redirect("/", 303), tok, age)
    resp.delete_cookie(OIDC_COOKIE, path="/api/auth/oidc")
    return resp


def oidc_public(c):
    return {"configured": OIDC_ON, "issuer": OIDC_ISSUER, "client_id": OIDC_CLIENT_ID, "secret_set": bool(OIDC_CLIENT_SECRET),
            "scopes": OIDC_SCOPES, "username_claim": OIDC_USERNAME_CLAIM, "groups_claim": OIDC_GROUPS_CLAIM,
            "required_group": OIDC_REQUIRED_GROUP, "admin_group": OIDC_ADMIN_GROUP, "label": OIDC_LABEL,
            "redirect_uri": OIDC_REDIRECT, "autocreate": gsetting(c, "oidc_autocreate") == "1",
            "error": _OIDC["err"], "error_at": _OIDC["err_at"] if _OIDC["err"] else "",
            "linked": c.execute("SELECT COUNT(*) FROM users WHERE oidc_subject IS NOT NULL").fetchone()[0]}


# ---------------------------------------------------------------- access control
# A list is visible to its owner and its members; role 'view' is read-only. Objects the user cannot
# see answer 404 (their existence is not revealed), writes with a view-only role 403.

class Denied(Exception):
    def __init__(self, code=404, msg=None):
        super().__init__(code)
        self.code, self.msg = code, msg

    def text(self):
        return self.msg or (tr("No permission (view only)") if self.code == 403 else tr("unknown"))


@app.errorhandler(Denied)
def denied(e):
    return err(e.text(), e.code)


# Collaboration for everyone (admin switch, settings.collab_all). Off: list memberships are ignored (shared
# lists are only visible to their owner), and sharing, assigning, @mentions, activity, News, status updates
# and collaboration pushes are off. Nothing is deleted; switching it on brings everything back. One process
# (waitress threads) and only the admin endpoint writes the value, so this cache is authoritative.
_COLLAB_ALL = {"on": True}


def collab_all():
    return _COLLAB_ALL["on"]


def need_collab():
    if not collab_all():
        raise Denied(403, tr("Collaboration is turned off on this server (an admin can turn it on)"))


# Time tracking for everyone (admin switch, settings.time_all), same pattern: off = the time endpoints refuse,
# no timers, no focus -> time entries, no timer pushes; entries stay. Timers running at that moment are stopped
# (end = the moment of switching off), so nothing keeps counting unseen.
_TIME_ALL = {"on": True}


def time_all():
    return _TIME_ALL["on"]


def need_time():
    if not time_all():
        raise Denied(403, tr("Time tracking is turned off on this server (an admin can turn it on)"))


# the user's own module switches (Settings > Layout): the action endpoints of a switched-off module refuse like the
# list-type gating (409 with the reason); reading, stopping and the data stay. deps / fields keep their API (D2 rule).
FEAT_OFF = {"pomo": N_("Focus (Pomodoro) is turned off in your settings"), "habits": N_("Habits are turned off in your settings"),
            "time": N_("Time tracking is turned off in your settings"), "comments": N_("Comments are turned off in your settings")}


def need_feat(f):
    if f not in (usettings(db(), me()).get("features") or "").split(","):
        raise Denied(409, tr(FEAT_OFF[f]))


def _members_on():
    return "" if collab_all() else " AND 0"


def vis_sql():
    """Subquery of the list ids the current user may see (two ? = user id)."""
    return f"(SELECT id FROM lists WHERE owner_id=? UNION SELECT list_id FROM list_members WHERE user_id=?{_members_on()})"


def wr_sql():
    """Subquery of the list ids the current user may change as a whole (two ? = user id). Participants are not in it:
    what they may change is decided per task (tvis(..., write=True))."""
    return f"(SELECT id FROM lists WHERE owner_id=? UNION SELECT list_id FROM list_members WHERE user_id=? AND role IN ('edit', 'admin'){_members_on()})"


# ---------------------------------------------------------------- list roles (1.10.0)
# Roles of a list member (list_members.role; the owner is lists.owner_id, never a member row):
#   admin       sees and changes everything, manages members and their roles (not the owner)
#   edit        "Member": sees and changes everything (the role every share had before 1.10.0)
#   view        "Viewer": sees everything, changes nothing (may comment)
#   participant sees ONLY the tasks assigned to them (with all their subtasks, comments, files) and, read-only and
#               without notes / comments / files, the parent chain of an assigned subtask as context. Sections,
#               progress, search, calendar, statistics, time, API, webhooks, News: everything is filtered on the server.
#               They may add tasks to the list (always assigned to themselves) and subtasks under their tasks.
# The stored values edit / view stay (API compatibility); the app shows them as Member / Viewer.
ROLES = ("admin", "edit", "participant", "view")
FULL_ROLES = ("owner", "admin", "edit", "view")  # see the whole list
WRITE_ROLES = ("owner", "admin", "edit")         # change the whole list
MANAGE_ROLES = ("owner", "admin")                # members + roles, moderate comments


def plists(c, uid):
    """Ids of the lists in which uid is a participant (empty while collaboration is off: memberships are ignored)."""
    if not uid or not collab_all():
        return []
    return [r[0] for r in c.execute("SELECT list_id FROM list_members WHERE user_id=? AND role='participant' ORDER BY list_id",
                                    (int(uid),))]


def _pset_sql(uid, pl, write=False):
    """SELECT of the task ids uid sees (write: may change) in the participant lists pl (ints, inlined; no ? params):
    assigned to uid + all their subtasks; for reading also the parent chain of those (context)."""
    q, u, depth_cap = ",".join(str(int(x)) for x in pl), int(uid), MAX_DEPTH + 7
    base = f"""WITH RECURSIVE pa(id) AS (SELECT id FROM tasks WHERE assignee_id={u} AND list_id IN ({q})),
               dn(id, lvl) AS (SELECT id, 0 FROM pa UNION
                               SELECT t.id, dn.lvl + 1 FROM tasks t JOIN dn ON t.parent_id=dn.id
                               WHERE dn.lvl < {depth_cap} AND t.list_id IN ({q}))"""
    if write:
        return base + " SELECT id FROM dn"
    return base + f""", up(id, lvl) AS (SELECT t.parent_id, 1 FROM tasks t JOIN pa ON pa.id=t.id WHERE t.parent_id IS NOT NULL UNION
                               SELECT t.parent_id, up.lvl + 1 FROM tasks t JOIN up ON t.id=up.id
                               WHERE t.parent_id IS NOT NULL AND up.lvl < {depth_cap})
               SELECT id FROM dn UNION SELECT id FROM up"""


def tvis(c, uid, a="", write=False):
    """SQL condition (no ? params) that keeps only the task rows uid may see (write: change) among tasks of lists uid
    can access at all. Combine it with the list-level filter (vis_sql / wr_sql / a list id): it only removes the tasks
    a participant must not see. "1" when uid is a participant nowhere (the usual case)."""
    pl = plists(c, uid)
    if not pl:
        return "1"
    q = ",".join(str(int(x)) for x in pl)
    return f"({a}list_id NOT IN ({q}) OR {a}id IN ({_pset_sql(uid, pl, write)}))"


def pvis(c, uid, lid=None):
    """(visible, writable, context) task id sets of uid in their participant lists (or only in list lid)."""
    pl = plists(c, uid)
    if lid is not None:
        pl = [x for x in pl if x == lid]
    if not pl:
        return set(), set(), set()
    vis = {r[0] for r in c.execute(_pset_sql(uid, pl))}
    wr = {r[0] for r in c.execute(_pset_sql(uid, pl, write=True))}
    return vis, wr, vis - wr


def task_visible(c, tid, uid, write=False, full=False):
    """May uid see (write: change) task tid? Full roles: the list decides; participants: the task (full: not only as
    context, i.e. with notes, comments and files)."""
    r = c.execute("SELECT list_id FROM tasks WHERE id=?", (tid,)).fetchone() if tid else None
    if not r:
        return False
    role = list_role(c, r[0], uid)
    if role == "participant":
        vis, wr, _ = pvis(c, uid, r[0])
        return tid in (wr if write or full else vis)
    return bool(role) and (not write or role in WRITE_ROLES)


def list_role(c, lid, uid=None):
    uid = uid or me()
    r = c.execute("SELECT owner_id FROM lists WHERE id=?", (lid,)).fetchone()
    if not r:
        return None
    if r[0] == uid:
        return "owner"
    m = c.execute("SELECT role FROM list_members WHERE list_id=? AND user_id=?", (lid, uid)).fetchone()
    return m[0] if m and collab_all() else None


def need_list(c, lid, write=True, owner=False, manage=False):
    """Role of the current user in list lid; 404 when they cannot see it, 403 when the action needs more:
    write = change the list as a whole (participants and viewers cannot), manage = members / roles."""
    role = list_role(c, lid) if lid else None
    if not role:
        raise Denied(404)
    if (owner and role != "owner") or (manage and role not in MANAGE_ROLES) or (write and role not in WRITE_ROLES):
        raise Denied(403)
    return role


# list types (package D2): time tracking, dependencies, custom fields and project status only in project lists
PROJECT_ONLY = {"time": N_("Make this list a project to track time"),
                "deps": N_("Make both lists projects to link their tasks"),
                "fields": N_("Make this list a project to use custom fields"),
                "status": N_("Make this list a project to set a status")}
PROJ_SQL = "(SELECT id FROM lists WHERE kind='project')"


def is_project(c, lid):
    r = c.execute("SELECT kind FROM lists WHERE id=?", (lid,)).fetchone() if lid else None
    return bool(r) and r[0] == "project"


def need_project(c, lid, what):
    if not is_project(c, lid):
        raise Denied(409, tr(PROJECT_ONLY[what]))


def need_task(c, tid, write=True, full=False):
    """Role of the current user in the task's list; 404 when they cannot see the task, 403 when they cannot change it.
    Participants: only their tasks (and subtasks); the parent chain of an assigned subtask is context -- readable with
    full=False only (no notes, comments, files, history)."""
    r = c.execute("SELECT list_id FROM tasks WHERE id=?", (tid,)).fetchone()
    if not r:
        raise Denied(404)
    role = list_role(c, r[0])
    if role == "participant":
        vis, wr, ctx = pvis(c, me(), r[0])
        if tid not in vis or (full and tid in ctx):
            raise Denied(404)
        if write and tid not in wr:
            raise Denied(403)
        return role
    return need_list(c, r[0], write)


def list_people(c, lid):
    """Owner + member ids of a list."""
    r = c.execute("SELECT owner_id FROM lists WHERE id=?", (lid,)).fetchone()
    ids = {r[0]} if r else set()
    ids.update(x[0] for x in c.execute("SELECT user_id FROM list_members WHERE list_id=?", (lid,)))
    return ids


def my_inbox(c, uid=None):
    uid = uid or me()
    r = c.execute("SELECT id FROM lists WHERE is_inbox=1 AND owner_id=?", (uid,)).fetchone()
    if r:
        return r[0]
    ensure_inbox(c, uid)
    return c.execute("SELECT id FROM lists WHERE is_inbox=1 AND owner_id=?", (uid,)).fetchone()[0]


def my_max_sort(c, uid):
    a = c.execute("SELECT COALESCE(MAX(sort),0) FROM lists WHERE owner_id=?", (uid,)).fetchone()[0]
    b = c.execute("SELECT COALESCE(MAX(sort),0) FROM list_members WHERE user_id=?", (uid,)).fetchone()[0]
    return max(a, b)


# ---------------------------------------------------------------- serializers

def task_dict(r, tags):
    d = dict(r)
    d.pop("reminded", None)
    d["tags"] = tags.get(r["id"], [])
    return d


def tags_for(c, ids=None, uid=None):
    out = {}
    uid = uid or me()
    for r in c.execute("SELECT task_id, tag FROM task_tags WHERE user_id=? ORDER BY tag", (uid,)):
        if ids is None or r["task_id"] in ids:
            out.setdefault(r["task_id"], []).append(r["tag"])
    return out


def load_tasks(c, where, args=()):
    rows = c.execute(f"SELECT * FROM tasks WHERE {where}", args).fetchall()
    # 1.10.0 safety net: a participant never gets a task of that list they must not see, whatever the caller's query;
    # context tasks (parents of an assigned subtask) come without notes, link, files, fields and comments
    ctx, pl, pv = set(), set(), set()
    viewer = g.user["id"] if has_request_context() and getattr(g, "user", None) else None
    if viewer and rows:
        pl = set(plists(c, viewer))
        if pl:
            pv, _, ctx = pvis(c, viewer)
            rows = [r for r in rows if r["list_id"] not in pl or r["id"] in pv]
    ids = {r["id"] for r in rows}
    tags = tags_for(c, ids)
    ltags = ltags_for(c, ids) if ids else {}
    atts = {}  # the task's own files; files of comments are shown inside their comment (timeline)
    for a in c.execute("SELECT id, task_id, name, mime, size, created_at FROM attachments WHERE comment_id IS NULL ORDER BY id"):
        if a["task_id"] in ids:
            atts.setdefault(a["task_id"], []).append({k: a[k] for k in ("id", "name", "mime", "size", "created_at")})
    pls = {}
    pl_ok = pl_usable_ids(c, viewer) if ids else set()  # 2.1.0: per connection (0 = the legacy one)
    for p in c.execute("SELECT id, task_id, doc_id, title, correspondent, created, status, message, att_id, conn_id "
                       "FROM paperless_links ORDER BY id"):
        if p["task_id"] in ids:
            d = {k: p[k] for k in p.keys() if k not in ("task_id", "conn_id")}
            d["conn"] = p["conn_id"] or 0
            if d["conn"] not in pl_ok:  # a connection the viewer cannot use: they only learn that there is a document
                d.update(doc_id=None, title=tr("Paperless document"), correspondent="", created="", message="", hidden=True, conn=None)
            pls.setdefault(p["task_id"], []).append(d)
    # comment count + unread (comments of others newer than the last one I have seen)
    cms, uid = {}, (g.user["id"] if has_request_context() and getattr(g, "user", None) else None)
    if uid and ids:
        for r in c.execute("""SELECT k.task_id, COUNT(*) AS n,
                                     SUM(CASE WHEN k.id > COALESCE(s.seen_id, 0) AND k.user_id IS NOT ? THEN 1 ELSE 0 END) AS u
                              FROM comments k LEFT JOIN task_seen s ON s.task_id=k.task_id AND s.user_id=?
                              WHERE k.deleted_at IS NULL GROUP BY k.task_id""", (uid, uid)):
            if r["task_id"] in ids:
                cms[r["task_id"]] = (r["n"], r["u"] or 0)
    # custom field values (fields of the task's current list) and dependencies: blocked = open blockers
    # (also ones I cannot see), blockers = the open ones I can see, blocking = open tasks waiting on it
    fvs, blk, bing = {}, {}, {}
    if ids:
        for r in c.execute("""SELECT v.task_id, v.field_id, v.value FROM task_field_values v JOIN list_fields f ON f.id=v.field_id
                              JOIN tasks t ON t.id=v.task_id WHERE f.list_id=t.list_id"""):
            if r["task_id"] in ids:
                fvs.setdefault(r["task_id"], {})[str(r["field_id"])] = r["value"]
        for r in c.execute(f"""SELECT d.task_id, d.blocker_id, b.list_id FROM task_deps d JOIN tasks b ON b.id=d.blocker_id
                              JOIN tasks w ON w.id=d.task_id
                              WHERE b.status=0 AND b.deleted_at IS NULL AND b.list_id IN {PROJ_SQL} AND w.list_id IN {PROJ_SQL}"""):
            if r["task_id"] in ids:
                blk.setdefault(r["task_id"], []).append((r["blocker_id"], r["list_id"]))
        for r in c.execute(f"""SELECT d.blocker_id, COUNT(*) AS n FROM task_deps d JOIN tasks t ON t.id=d.task_id
                              JOIN tasks b ON b.id=d.blocker_id
                              WHERE t.status=0 AND t.deleted_at IS NULL AND t.list_id IN {PROJ_SQL} AND b.list_id IN {PROJ_SQL}
                              GROUP BY d.blocker_id"""):
            if r["blocker_id"] in ids:
                bing[r["blocker_id"]] = r["n"]
    vis = vis_ids(c, uid) if blk and uid else set()
    aiu = {}  # 2.1.1 (#326): model usage agents reported for the task ("AI usage" in the task panel)
    if ids and uid and c.execute("SELECT 1 FROM agent_usage WHERE task_id IS NOT NULL LIMIT 1").fetchone():
        for r in c.execute("""SELECT task_id, COUNT(*) AS n, SUM(input_tokens+output_tokens+cache_write_tokens) AS tok,
                                     SUM(cost_usd) AS cost FROM agent_usage WHERE task_id IS NOT NULL GROUP BY task_id"""):
            if r["task_id"] in ids:
                aiu[r["task_id"]] = {"tokens": r["tok"] or 0, "cost": round(r["cost"], 4) if r["cost"] is not None else None,
                                     "calls": r["n"]}
    gcode = git_code_for(c, ids) if ids else {}  # 2.2.0 (#271): linked pull requests + commits
    out = []
    for r in rows:
        d = task_dict(r, tags)
        d["ltags"] = ltags.get(r["id"], [])
        if r["id"] in gcode and r["id"] not in ctx:
            d["code"] = gcode[r["id"]]
        d["attachments"] = atts.get(r["id"], [])
        d["paperless"] = pls.get(r["id"], [])
        d["comment_count"], d["unread"] = cms.get(r["id"], (0, 0))
        d["fields"] = fvs.get(r["id"], {})
        d["blocked"] = len(blk.get(r["id"], []))
        d["blockers"] = [b for b, lid in blk.get(r["id"], []) if lid in vis and (lid not in pl or b in pv)]
        d["blocking"] = bing.get(r["id"], 0)
        if r["id"] in aiu and r["id"] not in ctx:
            d["ai_usage"] = aiu[r["id"]]
        if r["id"] in ctx:
            d.update(content="", url=None, attachments=[], paperless=[], comment_count=0, unread=0, fields={},
                     blockers=[], blocked=0, blocking=0, context=True)
        out.append(d)
    return out


def attachment_files(c, task_ids):
    """Paths of all attachments of these tasks (and their subtasks), to unlink after a hard delete."""
    ids = set(task_ids)
    for t in list(ids):
        ids.update(descendants(c, t))
    if not ids:
        return []
    q = ",".join("?" * len(ids))
    return [r[0] for r in c.execute(f"SELECT path FROM attachments WHERE task_id IN ({q})", list(ids))]


def unlink_files(paths):
    for p in paths:
        try:
            full = os.path.join(ATT_DIR, p)
            os.remove(full)
            d = os.path.dirname(full)
            if d != ATT_DIR and not os.listdir(d):
                os.rmdir(d)
        except OSError:
            pass


def running_pomo(c, uid=None):
    r = c.execute("SELECT * FROM pomos WHERE end IS NULL AND user_id=? ORDER BY id DESC LIMIT 1", (uid or me(),)).fetchone()
    return dict(r) if r else None


