@app.post("/api/admin/setup")
def admin_setup():
    """Step 2 of the first-run setup ("What do you want to use?"): {lang, collab_all, time_all, modules: [...], sample?}.
    Sets the instance switches, the modules of new users (default_features; the admin gets them too) and the
    language. Collaboration and time tracking stay in the modules list: the instance switch alone decides, so
    turning one on later in Settings makes it available to everyone at once. Admin only; all changeable later."""
    need_admin()
    b, c = body(), db()
    mods = b.get("modules")
    if not isinstance(mods, list) or not all(isinstance(m, str) for m in mods):
        return err(tr("Invalid value: {0}", "modules"))
    lang = b.get("lang")
    if lang is not None and lang not in LANGS:
        return err(tr("Invalid value: {0}", "lang"))
    e = _apply_instance(c, {k: b[k] for k in ("collab_all", "time_all") if k in b})
    if e:
        return e
    fs = ",".join(f for f in USER_DEFAULTS["features"].split(",") if f in ("collab", "time") or f in mods)
    gset(c, "default_features", fs)
    uset(c, me(), "features", fs)
    if lang:
        gset(c, "default_lang", lang)
        uset(c, me(), "lang", lang)
    pt = b.get("project_type")  # 2.4.0 (#243): "Start with a project" of a built-in type
    if pt not in (None, "") and pt not in PTYPES:
        return err(tr("Invalid value: {0}", "project_type"))
    if pt:
        ptype_create(c, me(), pt, tr(PTYPE_NAMES[pt], lg=lang or None))
    if b.get("sample") is True and not sample_state(c, me()):  # 1.8.0: "Create a sample project"
        sample_create(c, me())
    elif "sample" in b:
        uset(c, me(), "sample_ask", "0")  # decided here: the welcome tour does not ask again
    bump(c)
    c.commit()
    return jsonify(about_info(c, g.user))


AUTH_SWITCHES = ("twofa_required", "passkey_login", "oidc_autocreate", "public_links")


def _apply_instance(c, b):
    """Stores the instance switches of b (caller commits); an error response for a non-boolean value."""
    keys = ("collab_all", "time_all", "update_check") + AUTH_SWITCHES
    if any(k in b and not isinstance(b[k], bool) for k in keys):
        return err(tr("Invalid value: {0}", next(k for k in keys if k in b and not isinstance(b[k], bool))))
    for k in keys:
        if k in b:
            gset(c, k, "1" if b[k] else "0")
    if "collab_all" in b:
        _COLLAB_ALL["on"] = b["collab_all"]
        if b["collab_all"] and b.get("collab_personal_on") is True:  # "Turn on collaboration now?" (second user)
            for (uid,) in c.execute("SELECT id FROM users WHERE disabled=0").fetchall():
                fs = [f for f in usettings(c, uid)["features"].split(",") if f]
                if "collab" not in fs:
                    uset(c, uid, "features", ",".join(fs + ["collab"]))
    if "time_all" in b:
        if not b["time_all"] and time_all():  # stop running timers now (entries kept, end = now)
            now, ts = now_utc(), iso(now_utc())
            for r in c.execute("SELECT * FROM time_entries WHERE end IS NULL").fetchall():
                stop_timer(c, r, now, ts)
        _TIME_ALL["on"] = b["time_all"]
    return None


def _update_now():
    c = connect()
    try:
        update_check(c, force=True)
    finally:
        c.close()


# ---------------------------------------------------------------- state

def visible_lists(c, uid):
    """Lists the user sees, with role, sharing info and the user's own folder / sort / view."""
    rows = c.execute(f"""SELECT l.*, m.role AS m_role, m.folder AS m_folder, m.sort AS m_sort, m.view AS m_view
                        FROM lists l LEFT JOIN list_members m ON m.list_id=l.id AND m.user_id=?
                        WHERE l.owner_id=? OR (m.user_id IS NOT NULL{_members_on()})""", (uid, uid)).fetchall()
    ids = [r["id"] for r in rows]
    members, names = {}, {}
    if ids and collab_all():
        q = ",".join("?" * len(ids))
        for m in c.execute(f"""SELECT m.list_id, m.role, u.id, u.username, u.display_name FROM list_members m
                               JOIN users u ON u.id=m.user_id WHERE m.list_id IN ({q}) ORDER BY m.added_at, u.id""", ids):
            members.setdefault(m["list_id"], []).append({"user_id": m["id"], "name": m["display_name"] or m["username"],
                                                         "role": m["role"], "username": m["username"]})  # 2.4.2 (#389): @username
    if ids:
        owners = {r["owner_id"] for r in rows}
        q2 = ",".join("?" * len(owners))
        names = {u["id"]: u["display_name"] or u["username"]
                 for u in c.execute(f"SELECT id, username, display_name FROM users WHERE id IN ({q2})", list(owners))}
    subs = usettings(c, uid).get("progress_subtasks") == "1"
    prog = list_progress(c, ids, subs, uid)
    ltags = ltags_of_lists(c, ids)
    ag = agent_ids(c)
    for ms in members.values():
        for m in ms:
            if m["user_id"] in ag:
                m["agent"] = True
    snames = user_names(c, [r["status_by"] for r in rows])
    bells = {r[0]: r[1] for r in c.execute("SELECT list_id, mode FROM list_bell WHERE user_id=?", (uid,))}
    repos = git_repos_of_lists(c, ids)  # 2.2.0 (#271)
    out = []
    for r in rows:
        d = {k: r[k] for k in r.keys() if not k.startswith("m_")}
        d["progress"] = prog.get(r["id"], {"done": 0, "total": 0, "overdue": 0, "next_due": None})
        d["status_by_name"] = snames.get(r["status_by"], "")
        if r["owner_id"] != uid:
            d.update(folder=r["m_folder"], sort=r["m_sort"], view=r["m_view"] or r["view"], role=r["m_role"])
        else:
            d["role"] = "owner"
        d["members"] = members.get(r["id"], [])
        d["shared"] = bool(d["members"])
        d["tags"] = ltags.get(r["id"], [])
        d["owner_name"] = names.get(r["owner_id"], "")
        d["icon"] = list_icon_url(r)  # 2.0.2: URL of the own list icon, "" = none
        d["bell"] = bells.get(r["id"], "default")  # 2.1.0 (#317): my bell for this list
        d["repos"] = repos.get(r["id"], [])
        # 2.4.1 (#379): the one agent that tidies it up (same rule as tidy_agent_of, from the rows already loaded)
        cands = sorted(([r["owner_id"]] if r["owner_id"] in ag else [])
                       + [m["user_id"] for m in d["members"] if m.get("agent") and m["role"] in WRITE_ROLES])
        d["tidy_agent_id"] = r["tidy_agent"] if r["tidy_agent"] in cands else (cands[0] if cands else None)
        d.pop("tidy_agent", None)
        out.append(d)
    out.sort(key=lambda d: (-d["is_inbox"], d["sort"], d["id"]))
    return out


def visible_sections(c, uid, tasks=None):
    """Sections of the lists uid sees. In a participant list only the sections that hold a task uid sees (tasks: the
    already loaded visible tasks; else they are queried)."""
    rows = [dict(r) for r in c.execute(f"SELECT * FROM sections WHERE list_id IN {vis_sql()} ORDER BY sort, id", (uid, uid))]
    pl = set(plists(c, uid))
    if not pl:
        return rows
    if tasks is None:
        used = {r[0] for r in c.execute(f"SELECT DISTINCT section_id FROM tasks WHERE section_id IS NOT NULL AND deleted_at IS NULL "
                                        f"AND list_id IN ({','.join(str(x) for x in pl)}) AND {tvis(c, uid)}")}
    else:
        used = {t["section_id"] for t in tasks if t.get("section_id")}
    return [r for r in rows if r["list_id"] not in pl or r["id"] in used]


