def _folders(c):
    try:
        return json.loads(usettings(c, me()).get("folders") or "[]")
    except (TypeError, ValueError):
        return []


def _folder_paths(c, uid):
    """Every folder path of the user: the stored order plus any folder one of their lists is in."""
    used = [r[0] for r in c.execute("SELECT folder FROM lists WHERE owner_id=? AND folder!='' UNION ALL "
                                    "SELECT folder FROM list_members WHERE user_id=? AND folder!=''", (uid, uid))]
    return list(dict.fromkeys([x for x in _folders(c) if isinstance(x, str)] + used))


def _folder_move(c, uid, fn):
    """Applies fn(path) -> new path to the user's lists, member rows, folder order and closed folders."""
    for tbl, who, key in (("lists", "owner_id", "id"), ("list_members", "user_id", "list_id")):
        for r in c.execute(f"SELECT {key} AS k, folder FROM {tbl} WHERE {who}=? AND folder!=''", (uid,)).fetchall():
            nf = fn(r["folder"])
            if nf != r["folder"]:
                c.execute(f"UPDATE {tbl} SET folder=? WHERE {key}=? AND {who}=?", (nf, r["k"], uid))
    for k in ("folders", "folders_closed"):
        try:
            arr = json.loads(usettings(c, uid).get(k) or "[]")
        except (TypeError, ValueError):
            arr = []
        arr = [fn(x) for x in arr if isinstance(x, str)]
        uset(c, uid, k, json.dumps(list(dict.fromkeys(x for x in arr if x)), ensure_ascii=False))


@app.post("/api/folders/rename")
def folder_rename():
    """{old, new}: renames or moves a folder (paths, 2.4.0 #361): "A" -> "B" renames, "A/x" -> "B/x" moves a subfolder
    into another folder, "A/x" -> "x" makes it a top-level folder, "A" -> "B/A" nests a folder (only one without
    subfolders: at most FOLDER_DEPTH levels). Its lists and subfolders go along; an existing target folder is merged."""
    b = body()
    old, new = clean_folder(str(b.get("old") or ""), False), clean_folder(b.get("new") or "")
    if not old or not new:
        return err(tr("Name missing"))
    if new == old:
        return jsonify(ok=True)
    if folder_under(new, old):
        return err(tr("A folder cannot go into itself"))
    c = db()
    uid = me()
    subs = any(p != old and folder_under(p, old) for p in _folder_paths(c, uid))
    if subs and new.count(FOLDER_SEP) + 1 >= FOLDER_DEPTH:
        return err(tr("Folders nest at most {0} levels deep", FOLDER_DEPTH))
    _folder_move(c, uid, lambda p: new + p[len(old):] if folder_under(p, old) else p)
    bump(c)
    c.commit()
    return jsonify(ok=True)


@app.post("/api/folders/delete")
def folder_delete():
    """Removes the folder only: its lists and subfolders move up one level (2.4.0: a top folder's subfolders become
    top-level folders, a subfolder's lists go to its parent folder)."""
    name = clean_folder(str(body().get("name") or ""), False)
    if not name:
        return err(tr("Name missing"))
    c = db()
    uid = me()
    parent = name.rsplit(FOLDER_SEP, 1)[0] if FOLDER_SEP in name else ""

    def up(p):
        if p == name:
            return parent or "\0"  # a top folder's own lists: top level (dropped from the order below)
        if folder_under(p, name):
            rest = p[len(name) + 1:]
            return (parent + FOLDER_SEP + rest) if parent else rest
        return p
    _folder_move(c, uid, lambda p: "" if up(p) == "\0" else up(p))
    bump(c)
    c.commit()
    return jsonify(ok=True)


def need_section(c, sid):
    r = c.execute("SELECT list_id FROM sections WHERE id=?", (sid,)).fetchone()
    if not r:
        raise Denied(404)
    need_list(c, r[0])


def _sec_tasks(c, sid):
    return [r[0] for r in c.execute("SELECT id FROM tasks WHERE section_id=? AND deleted_at IS NULL ORDER BY id", (sid,))]


def _sec_sort(v):
    try:
        v = float(v)
    except (TypeError, ValueError):
        raise BadInput(tr("Invalid value: {0}", "sort")) from None
    if not math.isfinite(v):
        raise BadInput(tr("Invalid value: {0}", "sort"))
    return v


@app.post("/api/sections")
def section_create():
    """{list_id, name, sort?, tasks?}. D4 (undo of a deleted section): sort = its old place, tasks = the tasks that were
    in it -- each moves back only while it is still in that list without a section (else it is reported in skipped)."""
    b = body()
    name = (b.get("name") or "").strip()
    if not name or not b.get("list_id"):
        return err(tr("Name/list missing"))
    c = db()
    lid = as_int(b["list_id"], "list_id", 1)
    need_list(c, lid)
    srt = _sec_sort(b["sort"]) if b.get("sort") is not None else \
        c.execute("SELECT COALESCE(MAX(sort),0)+1 FROM sections WHERE list_id=?", (lid,)).fetchone()[0]
    tids = b.get("tasks") or []
    if not isinstance(tids, list) or len(tids) > 5000 or any(isinstance(i, bool) or not isinstance(i, int) for i in tids):
        return err(tr("Invalid value: {0}", "tasks"))
    cur = c.execute("INSERT INTO sections(list_id,name,sort) VALUES(?,?,?)", (lid, name[:200], srt))
    sid, moved, skipped = cur.lastrowid, [], []
    for tid in tids:
        r = c.execute("SELECT list_id, section_id, deleted_at FROM tasks WHERE id=?", (tid,)).fetchone()
        if not r or r["deleted_at"] or r["list_id"] != lid or r["section_id"] is not None:
            skipped.append(tid)
            continue
        before = c.execute("SELECT * FROM tasks WHERE id=?", (tid,)).fetchone()
        c.execute("UPDATE tasks SET section_id=?, updated_at=? WHERE id=?", (sid, iso(now_utc()), tid))
        log_changes(c, tid, before)
        moved.append(tid)
    bump(c)
    c.commit()
    return jsonify({**dict(c.execute("SELECT * FROM sections WHERE id=?", (sid,)).fetchone()), "moved": moved, "skipped": skipped})


@app.patch("/api/sections/<int:sid>")
def section_update(sid):
    """{name?, sort?, _prev?: {name}}: with _prev (undo / redo) a name changed elsewhere meanwhile stays (conflicts)."""
    b = body()
    c = db()
    need_section(c, sid)
    conflicts = []
    prev = b.get("_prev") if isinstance(b.get("_prev"), dict) else {}
    cur = c.execute("SELECT name FROM sections WHERE id=?", (sid,)).fetchone()
    if "name" in b:
        name = str(b["name"] or "").strip()[:200]
        if not name:
            return err(tr("Name missing"))
        if "name" in prev and cur["name"] != str(prev["name"] or "") and cur["name"] != name:
            conflicts.append({"field": "name", "server": cur["name"], "mine": name})
        else:
            c.execute("UPDATE sections SET name=? WHERE id=?", (name, sid))
    if "sort" in b:
        c.execute("UPDATE sections SET sort=? WHERE id=?", (_sec_sort(b["sort"]), sid))
    bump(c)
    c.commit()
    return jsonify(ok=True, conflicts=conflicts)


@app.post("/api/lists/<int:lid>/sections/order")
def sections_order(lid):
    """{ids: [...], _prev?: [...]}: the list's sections in their new order (every one exactly once), one transaction, edit
    rights. Returns the previous order (the client's undo sends it back). With _prev (undo / redo): only while the order
    is still the expected one, else nothing changes and the answer carries a conflict."""
    c = db()
    need_list(c, lid)
    b = body()
    ids, prev = b.get("ids"), b.get("_prev")
    cur = [r[0] for r in c.execute("SELECT id FROM sections WHERE list_id=? ORDER BY sort, id", (lid,))]
    bad = not isinstance(ids, list) or any(isinstance(i, bool) or not isinstance(i, int) for i in ids)
    if prev is not None and (bad or not isinstance(prev, list) or prev != cur or sorted(ids) != sorted(cur)):
        return jsonify(ok=False, prev=cur, ids=cur, conflicts=[{"field": "order", "server": cur, "mine": ids}])
    if bad or sorted(ids) != sorted(cur):
        return err(tr("Invalid value: {0}", "ids"))
    c.executemany("UPDATE sections SET sort=? WHERE id=?", [(k, i) for k, i in enumerate(ids)])
    bump(c)
    c.commit()
    return jsonify(ok=True, prev=cur, ids=ids, conflicts=[])


@app.delete("/api/sections/<int:sid>")
def section_delete(sid):
    """Deletes a section, its tasks stay (without a section). Returns the section and the ids of its tasks (the undo
    recreates it with them). Optional body {_prev: {name, tasks}} (undo / redo): only while the section still has that
    name and exactly those tasks, else nothing happens and the answer carries a conflict."""
    c = db()
    need_section(c, sid)
    sec = dict(c.execute("SELECT id, list_id, name, sort FROM sections WHERE id=?", (sid,)).fetchone())
    tids = _sec_tasks(c, sid)
    prev = body().get("_prev")
    if isinstance(prev, dict):
        want = prev.get("tasks") if isinstance(prev.get("tasks"), list) else []
        if sec["name"] != str(prev.get("name") or "") or sorted(tids) != sorted(x for x in want if isinstance(x, int)):
            return jsonify(ok=False, section=sec, tasks=tids,
                           conflicts=[{"field": "section", "server": {"name": sec["name"], "tasks": tids}, "mine": prev}])
    c.execute("DELETE FROM sections WHERE id=?", (sid,))
    bump(c)
    c.commit()
    return jsonify(ok=True, section=sec, tasks=tids, conflicts=[])


# ---------------------------------------------------------------- tasks

TASK_FIELDS = ("list_id", "section_id", "parent_id", "title", "content", "priority",
               "due", "due_time", "reminders", "repeat", "repeat_from", "sort",
               "pinned", "start", "duration", "assignee_id", "url", "ttype")
# 2.4.0 (#340): ticket types of a task (API v1 / MCP / events: "type"); '' = none
TICKET_TYPES = ("bug", "feature", "task")


# ---------------------------------------------------------------- activity (task history)
# Structured events, rendered (and translated) by the client: kind + data. Logged by the mutation
# endpoints, never for noise (sort order, pin, reminders, private tags, view state). Repeated edits of
# the same kind by the same user within ACT_MERGE_S update the last entry instead of adding lines
# (typing in the title / description, clicking through dates).
ACT_MERGE = {"title", "content", "due", "snooze", "priority", "assign", "list", "section", "repeat", "link", "parent", "field"}
ACT_MERGE_S = 600


def log_act(c, tid, kind, data=None, uid=None):
    if uid is None and has_request_context() and getattr(g, "user", None):
        uid = g.user["id"] or None  # 0 = someone via a public link (no user)
    via = act_via()
    if via:  # package B: "via API" / "via the public link" in the history
        data = {**(data or {}), "via": via}
    if has_request_context():
        wh_note(c, tid, kind)  # webhooks: collected per request, queued after a successful response
    ts, js = iso_ms(now_utc()), json.dumps(data or {}, ensure_ascii=False)
    if kind in ACT_MERGE:
        last = c.execute("SELECT id, user_id, kind, data, created_at FROM activity WHERE task_id=? ORDER BY id DESC LIMIT 1",
                         (tid,)).fetchone()
        if last and last["kind"] == kind and last["user_id"] == uid \
                and (kind != "field" or json.loads(last["data"] or "{}").get("id") == (data or {}).get("id")) \
                and (now_utc() - parse_iso(last["created_at"])).total_seconds() < ACT_MERGE_S:
            c.execute("UPDATE activity SET data=?, created_at=? WHERE id=?", (js, ts, last["id"]))
            return
    c.execute("INSERT INTO activity(task_id,user_id,kind,data,created_at) VALUES(?,?,?,?,?)", (tid, uid, kind, js, ts))


def log_changes(c, tid, old, act=None):
    """Compares the task row before a change (old) with the stored row now and logs what a person
    would care about."""
    new = c.execute("SELECT * FROM tasks WHERE id=?", (tid,)).fetchone()
    if not old or not new:
        return
    ch = lambda k: _norm(old[k]) != _norm(new[k])  # noqa: E731
    if ch("title"):
        log_act(c, tid, "title", {"to": new["title"][:200]})
    if ch("content"):
        log_act(c, tid, "content")
    if ch("due") or ch("due_time") or ch("start"):
        log_act(c, tid, "snooze" if act == "snooze" and new["due"] else "dep_shift" if act == "dep_shift" else "due",
                {"due": new["due"], "time": new["due_time"], "start": new["start"]})
    if ch("priority"):
        log_act(c, tid, "priority", {"p": new["priority"]})
    if ch("assignee_id"):
        log_act(c, tid, "assign", {"to": new["assignee_id"], "from": old["assignee_id"]})
    if ch("list_id"):
        lst = c.execute("SELECT name, is_inbox FROM lists WHERE id=?", (new["list_id"],)).fetchone()
        log_act(c, tid, "list", {"name": lst["name"] if lst else "", "inbox": bool(lst and lst["is_inbox"])})
    elif ch("section_id") and not ch("parent_id"):  # indenting follows the parent's section: not a move
        sec = c.execute("SELECT name FROM sections WHERE id=?", (new["section_id"],)).fetchone() if new["section_id"] else None
        log_act(c, tid, "section", {"name": sec["name"] if sec else None})
    if ch("parent_id"):
        par = c.execute("SELECT title FROM tasks WHERE id=?", (new["parent_id"],)).fetchone() if new["parent_id"] else None
        log_act(c, tid, "parent", {"title": par["title"][:200] if par else None})
    if ch("repeat"):
        log_act(c, tid, "repeat", {"rule": new["repeat"]})
    if ch("url"):
        log_act(c, tid, "link", {"url": new["url"]})
    if ch("ttype"):  # 2.4.0 (#340)
        log_act(c, tid, "ttype", {"to": new["ttype"] or None})


def check_url(f):
    """Normalizes f['url'] ('' -> NULL); error message if it is not an http(s) link."""
    if "url" not in f:
        return None
    u = (f["url"] or "").strip() if isinstance(f["url"], (str, type(None))) else ""
    f["url"] = u or None
    return tr("The link must start with http:// or https://") if u and not valid_url(u) else None


# ---- input validation (security audit 2026-09-28): the watchdog and the calendar code parse these
# fields for every user, so nothing malformed may be stored (one bad row used to stop all reminders).
DATE_RE = re.compile(r"\d{4}-\d{2}-\d{2}")
HM_RE = re.compile(r"(?:[01]\d|2[0-3]):[0-5]\d")
DATE_MIN_Y, DATE_MAX_Y = 1900, 2999
REM_MIN, REM_MAX, REM_COUNT = -1440, 366 * 1440, 10   # reminder offsets (minutes before due)
DURATION_MAX = 7 * 1440
TITLE_MAX, CONTENT_MAX = 2000, 200000
PRIORITIES = (0, 1, 3, 5)


def valid_date(v):
    if not isinstance(v, str) or not DATE_RE.fullmatch(v):
        return False
    try:
        return DATE_MIN_Y <= date.fromisoformat(v).year <= DATE_MAX_Y
    except ValueError:
        return False


def valid_hm(v):
    return isinstance(v, str) and bool(HM_RE.fullmatch(v))


def as_int(v, what, lo=None, hi=None):
    """int from a client value (int or digit string, never bool / float text); BadInput otherwise."""
    if isinstance(v, bool) or not isinstance(v, (int, str)) or (isinstance(v, str) and not re.fullmatch(r"-?\d{1,12}", v.strip())):
        raise BadInput(tr("Invalid value: {0}", what))
    v = int(v)
    if (lo is not None and v < lo) or (hi is not None and v > hi):
        raise BadInput(tr("Invalid value: {0}", what))
    return v


def clean_reminders(v):
    """'0,15' / [0, 15] -> '0,15' (minutes before due, ints within bounds); BadInput otherwise."""
    if v in (None, ""):
        return ""
    items = v if isinstance(v, list) else str(v).split(",") if isinstance(v, (str, int)) and not isinstance(v, bool) else None
    if items is None:
        raise BadInput(tr("Invalid value: {0}", tr("Reminder")))
    out = []
    for x in items:
        if isinstance(x, str) and not x.strip():
            continue
        out.append(str(as_int(x.strip() if isinstance(x, str) else x, tr("Reminder"), REM_MIN, REM_MAX)))
    out = list(dict.fromkeys(out))
    if len(out) > REM_COUNT:
        raise BadInput(tr("Invalid value: {0}", tr("Reminder")))
    return ",".join(out)


# RRULE: only what the calendar code can expand cheaply. No SECONDLY / MINUTELY / HOURLY and no
# BYHOUR / BYMINUTE / BYSECOND (the UI offers daily and longer; sub-daily rules made the occurrence
# expansion explode). Expansion is additionally capped (count + time window) where it is used.
RR_FREQS = ("DAILY", "WEEKLY", "MONTHLY", "YEARLY")
RR_KEYS = ("FREQ", "INTERVAL", "COUNT", "UNTIL", "BYDAY", "BYMONTHDAY", "BYMONTH", "BYSETPOS", "WKST",
           "BYYEARDAY", "BYWEEKNO")
RR_MAX_LEN = 300
RR_PROBE_DAYS = 3660          # a rule must have a date within ~10 years of its start
RR_OCC_PER_TASK, RR_OCC_TOTAL, RR_OCC_SECONDS = 120, 5000, 3.0


def rr_norm(rep):
    return (rep or "").strip().removeprefix("RRULE:").strip().rstrip(";") if isinstance(rep, str) else ""


@functools.lru_cache(maxsize=4096)
def rr_problem(rep):
    """None if the (normalized) rule is acceptable, else an error text. Structural check + parse."""
    if len(rep) > RR_MAX_LEN or not RRULE_OK.fullmatch(rep):
        return N_("Repeat: invalid rule")
    parts = dict(p.split("=", 1) for p in rep.split(";"))
    if len(parts) != rep.count(";") + 1 or any(k not in RR_KEYS for k in parts):
        return N_("Repeat: invalid rule")
    if parts.get("FREQ") not in RR_FREQS:
        return N_("Repeat: only daily, weekly, monthly or yearly rules")
    if "INTERVAL" in parts and not (parts["INTERVAL"].isdigit() and 1 <= int(parts["INTERVAL"]) <= 999):
        return N_("Repeat: invalid rule")
    if "COUNT" in parts and not (parts["COUNT"].isdigit() and 1 <= int(parts["COUNT"]) <= 9999):
        return N_("Repeat: invalid rule")
    if "UNTIL" in parts and not re.fullmatch(r"\d{8}(T\d{6}Z?)?", parts["UNTIL"]):
        return N_("Repeat: invalid rule")
    try:
        rrulestr(rep, dtstart=datetime(2026, 1, 1))
    except (ValueError, TypeError, OverflowError):
        return N_("Repeat: invalid rule")
    return None


@functools.lru_cache(maxsize=4096)
def rr_feasible(rep, d0):
    """True if the rule (without COUNT / UNTIL) has a date within RR_PROBE_DAYS after the local date d0.
    dateutil scans up to the year 9999 for a rule that never matches (seconds of CPU): the probe runs
    shifted by whole 400-year Gregorian cycles (same weekdays, same calendar) close to 9999, so a rule that
    never matches costs a fraction of a second, once (cached)."""
    if rr_problem(rep):
        return False
    try:
        d = date.fromisoformat(d0)
        base = ";".join(p for p in rep.split(";") if not p.startswith(("COUNT=", "UNTIL=")))
        k = max(0, (9800 - d.year) // 400)
        st = datetime(d.year + 400 * k, d.month, d.day)
        nxt = rrulestr(base, dtstart=st).after(st, inc=True)
        return bool(nxt) and (nxt - st).days <= RR_PROBE_DAYS
    except (ValueError, TypeError, OverflowError):
        return False


def rr_rule(rep, d0):
    """Parsed rrule for expansion from the local date d0 (datetime at midnight), or None if the rule is
    not acceptable / never matches (such rows are treated as not recurring)."""
    rep = rr_norm(rep)
    if not rep or not valid_date(d0) or not rr_feasible(rep, d0):
        return None
    d = date.fromisoformat(d0)
    return rrulestr(rep, dtstart=datetime(d.year, d.month, d.day))


def clean_repeat(v):
    rep = rr_norm(v) if isinstance(v, str) else None
    if rep is None:
        raise BadInput(tr("Repeat: invalid rule"))
    if rep:
        e = rr_problem(rep)
        if e:
            raise BadInput(tr(e))
    return rep


# 2.4.0 (#340): the built-in note templates of new tickets (in the language of the person creating the ticket); a list
# can have its own (lists.ticket_tpl, json {bug, feature}; Markdown, at most TICKET_TPL_MAX characters each)
TICKET_TPL = {"bug": N_("**Steps to reproduce**\n1. \n\n**Expected**\n\n**Actual**\n\n**Environment**\n"),
              "feature": N_("**Goal**\n\n**Acceptance criteria**\n- \n")}
TICKET_TPL_MAX = 5000


def clean_ticket_tpl(v):
    """{bug?, feature?} from a client -> the stored json ('' = both built-in)."""
    if v in (None, ""):
        return ""
    if not isinstance(v, dict) or any(k not in TICKET_TPL for k in v):
        raise BadInput(tr("Invalid value: {0}", "ticket_tpl"))
    out = {}
    for k, x in v.items():
        if x is not None and not isinstance(x, str):
            raise BadInput(tr("Invalid value: {0}", "ticket_tpl"))
        x = (x or "").replace("\r\n", "\n")[:TICKET_TPL_MAX]
        if x.strip():
            out[k] = x
    return json.dumps(out, ensure_ascii=False) if out else ""


def ticket_template(c, lid, kind):
    """The note template of a new ticket of this kind in list lid ('' when the list has ticket types off, or for "task")."""
    if kind not in TICKET_TPL:
        return ""
    r = c.execute("SELECT tickets, ticket_tpl FROM lists WHERE id=?", (lid,)).fetchone()
    if not r or not r["tickets"]:
        return ""
    try:
        own = json.loads(r["ticket_tpl"] or "{}").get(kind)
    except (ValueError, AttributeError):
        own = None
    return own if isinstance(own, str) and own.strip() else tr(TICKET_TPL[kind])


def clean_task(b):
    """Client values -> column values (validated; BadInput with a message otherwise)."""
    out = {}
    for k in TASK_FIELDS:
        if k in b:
            v = b[k]
            if k in ("due", "due_time", "section_id", "parent_id", "start", "duration", "list_id") and v in ("", None):
                v = None
            if k == "assignee_id" and v in ("", None, 0):
                v = None
            if k == "title":
                if v is not None and not isinstance(v, str):
                    raise BadInput(tr("Invalid value: {0}", tr("Title")))
                v = (v or "").strip()[:TITLE_MAX]
            if k == "content":
                if v is not None and not isinstance(v, str):
                    raise BadInput(tr("Invalid value: {0}", tr("Description")))
                v = (v or "")[:CONTENT_MAX]
            if k in ("list_id", "section_id", "parent_id", "assignee_id") and v is not None:
                v = as_int(v, k, 1)
            if k == "priority":
                v = as_int(v or 0, tr("Priority"))
                if v not in PRIORITIES:
                    raise BadInput(tr("Invalid value: {0}", tr("Priority")))
            if k == "pinned":
                v = 1 if as_int(int(v) if isinstance(v, bool) else (v or 0), tr("Pinned")) else 0
            if k in ("due", "start") and v is not None and not valid_date(v):
                raise BadInput(tr("Invalid value: {0}", tr("Date") if k == "due" else tr("Start|date")))
            if k == "due_time" and v is not None and not valid_hm(v):
                raise BadInput(tr("Invalid value: {0}", tr("Time")))
            if k == "duration" and v is not None:
                v = as_int(v, tr("Duration"), 1, DURATION_MAX)
            if k == "reminders":
                v = clean_reminders(v)
            if k == "repeat":
                v = "" if v is None else clean_repeat(v)
            if k == "repeat_from":
                v = "done" if v == "done" else "due"
            if k == "ttype":
                v = "" if v in (None, "") else v
                if v and v not in TICKET_TYPES:
                    raise BadInput(tr("Invalid value: {0}", tr("Type")))
            if k == "sort":
                if isinstance(v, bool) or not isinstance(v, (int, float)) or not math.isfinite(v):
                    try:
                        v = float(v)
                    except (TypeError, ValueError):
                        raise BadInput(tr("Invalid value: {0}", "sort")) from None
                    if not math.isfinite(v):
                        raise BadInput(tr("Invalid value: {0}", "sort"))
            out[k] = v
    if out.get("due") is None and "due" in out:
        out["due_time"] = None
        out["start"] = None
        out["reminders"] = out.get("reminders", "")
    if out.get("start") and out.get("due") and out["start"] > out["due"]:
        out["start"] = out["due"]
    return out


def descendants(c, tid):
    """All subtasks (all levels). Cycle-safe: UNION drops rows already produced and the depth is capped,
    so a parent_id cycle in old / imported data can never make this run forever."""
    return [r[0] for r in c.execute("""WITH RECURSIVE d(id, lvl) AS (
        SELECT id, 1 FROM tasks WHERE parent_id=? UNION
        SELECT t.id, d.lvl + 1 FROM tasks t JOIN d ON t.parent_id=d.id WHERE d.lvl < ?)
        SELECT DISTINCT id FROM d WHERE id != ?""", (tid, MAX_DEPTH + 7, tid))]


def depth(c, tid):
    """0 = top level. Walks up the parent chain."""
    n, cur = 0, tid
    while n < 10:
        r = c.execute("SELECT parent_id FROM tasks WHERE id=?", (cur,)).fetchone()
        if not r or not r[0]:
            return n
        cur, n = r[0], n + 1
    return n


def subtree_height(c, tid):
    h, level = 0, [tid]
    while level and h < 10:
        q = ",".join("?" * len(level))
        level = [r[0] for r in c.execute(f"SELECT id FROM tasks WHERE parent_id IN ({q})", level)]
        if level:
            h += 1
    return h


def ancestors(c, tid, limit=MAX_DEPTH + 7):
    """Parent chain of tid (nearest first); stops at a cycle / after limit steps."""
    out, cur = [], tid
    while len(out) < limit:
        r = c.execute("SELECT parent_id FROM tasks WHERE id=?", (cur,)).fetchone()
        if not r or not r[0] or r[0] in out or r[0] == tid:
            break
        out.append(r[0])
        cur = r[0]
    return out


def check_parent(c, tid, parent):
    """None if tid may become a child of parent, else an error message."""
    if parent is None:
        return None
    try:
        parent, tid = int(parent), (int(tid) if tid is not None else None)
    except (TypeError, ValueError):
        return tr("unknown")
    if tid is not None and (parent == tid or parent in descendants(c, tid) or tid in ancestors(c, parent)):
        return tr("A task cannot be nested under itself")
    if depth(c, parent) + 1 + (subtree_height(c, tid) if tid else 0) >= MAX_DEPTH:
        return tr("At most {0} levels", MAX_DEPTH)
    return None


def can_move(c, src, dst):
    """May the current user move a task from list src into dst? Always within a list and for the owner of
    src; an edit member only if nobody who sees the task now loses access (dst is seen by everyone who sees
    src) -- otherwise a member could pull a shared task (with subtasks and comments) away from the owner."""
    return src == dst or list_role(c, src) == "owner" or list_people(c, src) <= list_people(c, dst)


def check_move(c, src, dst):
    if not can_move(c, src, dst):
        raise Denied(403, tr("Only the list owner can move tasks out of this shared list"))


def move_subtree(c, tid, lid):
    """Subtasks follow their parent into list lid (all levels). A subtask in another list that the current
    user may not move out of (subtask of a foreign parent) stays in its list and becomes top level there."""
    people, ok = list_people(c, lid), {}
    done, level, n = {tid}, [tid], 0
    while level and n < MAX_DEPTH + 7:
        q = ",".join("?" * len(level))
        nxt = []
        for k in c.execute(f"SELECT id, list_id, assignee_id FROM tasks WHERE parent_id IN ({q})", level).fetchall():
            if k["id"] in done:
                continue
            done.add(k["id"])
            if k["list_id"] not in ok:
                ok[k["list_id"]] = can_move(c, k["list_id"], lid)
            if not ok[k["list_id"]]:
                c.execute("UPDATE tasks SET parent_id=NULL WHERE id=?", (k["id"],))
                continue
            c.execute("UPDATE tasks SET list_id=? WHERE id=?", (lid, k["id"]))
            if k["assignee_id"] and k["assignee_id"] not in people:
                c.execute("UPDATE tasks SET assignee_id=NULL WHERE id=?", (k["id"],))
            nxt.append(k["id"])
        level, n = nxt, n + 1


def hard_delete(c, ids, lists=None):
    """Permanently deletes tasks (subtasks go with them: ON DELETE CASCADE). Subtasks in lists the current
    user does not own (lists: set of list ids where they may, see purge_lists) are detached first and stay with
    their list. Returns the attachment paths to unlink."""
    for tid in ids:
        done, level, n = {tid}, [tid], 0
        while level and n < MAX_DEPTH + 7:
            q = ",".join("?" * len(level))
            nxt = []
            for k in c.execute(f"SELECT id, list_id FROM tasks WHERE parent_id IN ({q})", level).fetchall():
                if k["id"] in done:
                    continue
                done.add(k["id"])
                if (k["list_id"] not in lists) if lists is not None else list_role(c, k["list_id"]) != "owner":
                    c.execute("UPDATE tasks SET parent_id=NULL WHERE id=?", (k["id"],))
                else:
                    nxt.append(k["id"])
            level, n = nxt, n + 1
    files = attachment_files(c, ids)
    for tid in ids:
        c.execute("DELETE FROM tasks WHERE id=?", (tid,))
    return files


def set_tags(c, tid, tags, uid=None):
    uid = uid or me()
    c.execute("DELETE FROM task_tags WHERE task_id=? AND user_id=?", (tid, uid))
    for t in dict.fromkeys(x.strip().lstrip("#") for x in tags if x and x.strip().lstrip("#")):
        c.execute("INSERT INTO task_tags(task_id,user_id,tag) VALUES(?,?,?)", (tid, uid, t))


def my_tags(c, tid):
    return [r[0] for r in c.execute("SELECT tag FROM task_tags WHERE task_id=? AND user_id=?", (tid, me()))]


def one_task(c, tid):
    return load_tasks(c, "id=?", (tid,))[0]


def participant_assignee(c, cur, f):
    """Error text when a participant's change of the assignee (f) is not allowed, else None. Participants cannot
    hand tasks to others or take them away (an unassigned task would vanish from their view); on a new subtask under
    one of their tasks (cur None) they may leave it unassigned or take it themselves."""
    if "assignee_id" not in f:
        return None
    new = f["assignee_id"]
    if cur is None:
        return None if new in (None, me()) else tr("Participants can only assign tasks to themselves")
    if _norm(new) == _norm(cur["assignee_id"]):
        return None
    return tr("Participants cannot change who a task is assigned to")


def check_assignee(c, lid, aid):
    """None if aid may be assigned in list lid, else an error message."""
    if aid is None:
        return None
    need_collab()
    try:
        aid = int(aid)
    except (TypeError, ValueError):
        return tr("unknown user")
    return None if aid in list_people(c, lid) else tr("Only the owner or a member of the list can be assigned")


# 2.2.1 (#359): the fields the web API's task / list / comment endpoints know (others: warning, see web_fields)
WEB_TASK_NEW = frozenset(TASK_FIELDS) | {"tags", "ltags", "fields"}
WEB_TASK_EDIT = WEB_TASK_NEW | {"add_tags", "_prev", "_act"}
WEB_LIST_NEW = frozenset({"name", "color", "folder", "view", "kind", "checklist", "dep_shift", "tickets", "ptype"})
WEB_LIST_EDIT = frozenset(LIST_FIELDS) | {"rate", "agent_tidy", "tidy_agent_id", "_prev", "ticket_tpl"}
WEB_COMMENT = frozenset({"body", "suggestion"})


@app.post("/api/tasks")
def task_create():
    b = web_fields(field_alias(body(), "content", "notes"), WEB_TASK_NEW, "POST /api/tasks")
    f = clean_task(b)
    if not f.get("title"):
        return err(tr("Title missing"))
    c = db()
    e = check_parent(c, None, f.get("parent_id"))
    if e:
        return err(e)
    if f.get("parent_id"):  # subtasks live in their parent's list
        role = need_task(c, f["parent_id"])
        f["list_id"] = c.execute("SELECT list_id FROM tasks WHERE id=?", (f["parent_id"],)).fetchone()[0]
    elif f.get("list_id"):
        role = list_role(c, f["list_id"])
        if role != "participant":
            need_list(c, f["list_id"])
    else:
        role, f["list_id"] = "owner", my_inbox(c)
    if role == "participant":  # 1.10.0: a participant's new task is theirs (else it would vanish from their view)
        e = participant_assignee(c, None, f)
        if e:
            return err(e, 403)
        if not f.get("parent_id"):
            f["assignee_id"] = me()
    if f.get("section_id") and not c.execute("SELECT 1 FROM sections WHERE id=? AND list_id=?",
                                              (f["section_id"], f["list_id"])).fetchone():
        f["section_id"] = None
    e = check_assignee(c, f["list_id"], f.get("assignee_id")) or check_url(f) or repeat_problem(f.get("repeat"), f.get("due"))
    if e:
        return err(e)
    if "sort" not in f:
        f["sort"] = c.execute("SELECT COALESCE(MIN(sort),0)-1 FROM tasks WHERE list_id=? AND parent_id IS ?",
                              (f["list_id"], f.get("parent_id"))).fetchone()[0]
        if f.get("parent_id"):  # subtasks append at the end
            f["sort"] = c.execute("SELECT COALESCE(MAX(sort),0)+1 FROM tasks WHERE parent_id=?",
                                  (f["parent_id"],)).fetchone()[0]
    if b.get("fields"):
        need_project(c, f["list_id"], "fields")
    if f.get("ttype") and not (f.get("content") or "").strip():  # 2.4.0 (#340): a new bug / feature gets its note template
        tpl = ticket_template(c, f["list_id"], f["ttype"])
        if tpl:
            f["content"] = tpl
    ts = iso(now_utc())
    f["created_by"] = me()
    if f.get("assignee_id"):
        f["assigned_by"] = me()
    cols = list(f) + ["created_at", "updated_at"]
    cur = c.execute(f"INSERT INTO tasks({','.join(cols)}) VALUES({','.join('?' * len(cols))})",
                    [f[k] for k in f] + [ts, ts])
    if b.get("tags"):
        set_tags(c, cur.lastrowid, b["tags"])
    if b.get("ltags"):
        set_ltags(c, cur.lastrowid, b["ltags"], log=False)  # BadInput: 400, nothing stored
    if b.get("fields"):
        set_field_values(c, cur.lastrowid, f["list_id"], b["fields"], log=False)  # BadInput: 400, nothing stored
    log_act(c, cur.lastrowid, "created")
    agent_task_mentions(c, cur.lastrowid)
    agent_tidy_events(c, cur.lastrowid)
    if f.get("assignee_id"):
        task_event(c, cur.lastrowid, "assign")
    newtask_events(c, cur.lastrowid)
    if f.get("parent_id"):
        log_act(c, f["parent_id"], "subtask", {"id": cur.lastrowid, "title": f["title"][:200]})
    bump(c)
    c.commit()
    return jsonify(one_task(c, cur.lastrowid))


# ---- 2.1.0 (#335): "Waiting on external" (German "Warten auf Extern"): who / what the task waits for + a follow-up day.
# The task keeps its status (open). On the follow-up day (at the all-day reminder time of the person it is for) that
# person gets a push "Follow up" + a News item, and every agent that follows the task (assignee, creator, commented) the
# event followup_due. Once per date; a new date fires again. Clearing it is one call (DELETE).
WAIT_NOTE_MAX = 300


def set_waiting(c, tid, b):
    """{note?, until?} -> sets / changes the waiting state (caller commits). BadInput on invalid values."""
    unknown = sorted(k for k in b if k not in ("note", "until"))
    if unknown:
        raise UnknownFields(unknown)
    note = b.get("note")
    if note is not None and not isinstance(note, str):
        raise BadInput(tr("Invalid value: {0}", "note"))
    note = (note or "").strip()[:WAIT_NOTE_MAX]
    until = b.get("until") or None
    if until is not None and not valid_date(until):
        raise BadInput(tr("Invalid value: {0}", "until"))
    cur = c.execute("SELECT waiting_at, wait_until, wait_fired FROM tasks WHERE id=?", (tid,)).fetchone()
    fired = cur["wait_fired"] if cur["waiting_at"] and cur["wait_until"] == until else ""
    c.execute("UPDATE tasks SET waiting_at=?, wait_note=?, wait_until=?, wait_by=?, wait_fired=?, updated_at=? WHERE id=?",
              (cur["waiting_at"] or iso(now_utc()), note, until, me() or None, fired, iso(now_utc()), tid))
    log_act(c, tid, "waiting", {"note": note[:200], "until": until})


def clear_waiting(c, tid):
    """True when the task was waiting (caller commits)."""
    if not c.execute("SELECT waiting_at FROM tasks WHERE id=?", (tid,)).fetchone()["waiting_at"]:
        return False
    c.execute("UPDATE tasks SET waiting_at=NULL, wait_note='', wait_until=NULL, wait_by=NULL, wait_fired='', updated_at=? WHERE id=?",
              (iso(now_utc()), tid))
    log_act(c, tid, "waiting_rm")
    return True


@app.put("/api/tasks/<int:tid>/waiting")
def task_waiting_set(tid):
    c = db()
    need_task(c, tid)
    set_waiting(c, tid, body())
    bump(c)
    c.commit()
    return jsonify(one_task(c, tid))


@app.delete("/api/tasks/<int:tid>/waiting")
def task_waiting_clear(tid):
    c = db()
    need_task(c, tid)
    if clear_waiting(c, tid):
        bump(c)
        c.commit()
    return jsonify(one_task(c, tid))


def _wd_followups(c, users, S, LG, now):
    """The follow-up day of waiting tasks: push + News to the person it is for, followup_due to the following agents."""
    today = now.date().isoformat()
    rows = c.execute("""SELECT t.*, l.name AS list_name, l.is_inbox AS list_inbox, l.owner_id AS list_owner FROM tasks t
                        JOIN lists l ON l.id=t.list_id WHERE t.waiting_at IS NOT NULL AND t.wait_until IS NOT NULL
                        AND t.wait_until<=? AND t.wait_fired!=t.wait_until AND t.status=0 AND t.deleted_at IS NULL
                        AND l.archived=0""", (today,)).fetchall()
    for t in rows:
        try:
            _wd_followup(c, t, users, S, LG, now)
        except Exception as e:  # noqa: BLE001
            _wd_fail(c, "follow-up of task", t["id"], e)


def _wd_followup(c, t, users, S, LG, now):
    ag = agent_ids(c)
    rcpt = next((u for u in (t["assignee_id"], t["created_by"], t["wait_by"], t["list_owner"])
                 if u and u in users and u not in ag and (u == t["list_owner"] or task_visible(c, t["id"], u, full=True))), None)
    s, lg = S.get(rcpt, USER_DEFAULTS), LG.get(rcpt, "en")
    allday = s.get("allday_time") if valid_hm(s.get("allday_time")) else "09:00"
    if t["wait_until"] == now.date().isoformat() and now.strftime("%H:%M") < allday:
        return  # today, but not yet the time of day
    c.execute("UPDATE tasks SET wait_fired=? WHERE id=?", (t["wait_until"], t["id"]))
    push = None
    if rcpt and task_visible(c, t["id"], rcpt, full=True):
        cs = collab_user(c, rcpt, None)
        if cs:
            news_add(c, rcpt, "followup", task_id=t["id"], data={"note": t["wait_note"][:200], "until": t["wait_until"]}, s=cs)
        if notif_ok(c, rcpt, s, "followup", "push"):
            lname = tr("Inbox", lg=lg) if t["list_inbox"] and t["list_name"] == "Eingang" else t["list_name"]
            push = (tr("Follow up: {0}", t["title"], lg=lg),
                    (tr("Waiting on: {0}", t["wait_note"], lg=lg) + " · " if t["wait_note"] else "") + lname)
    follow = {t["assignee_id"], t["created_by"]} | {r[0] for r in c.execute(
        "SELECT DISTINCT user_id FROM comments WHERE task_id=? AND deleted_at IS NULL", (t["id"],))}
    for aid in sorted(agent_ids(c) & follow):
        if task_visible(c, t["id"], aid, full=True):
            agent_emit(c, aid, "followup_due", agent_task_data(c, t["id"], aid, waiting=waiting_of(t)), actor=None)
    c.commit()  # before the push: sending it writes to the database itself (push tags)
    if push:
        notify(rcpt, push[0], push[1], push_prio(s), f"{PUBLIC_URL}/#t/{t['id']}", s=s, task=t["id"])


@app.patch("/api/tasks/<int:tid>")
def task_update(tid):
    c = db()
    need_task(c, tid)
    conflicts = []
    old = c.execute("SELECT due, status, deleted_at FROM tasks WHERE id=?", (tid,)).fetchone()
    b = web_fields(field_alias(body(), "content", "notes"), WEB_TASK_EDIT, "PATCH /api/tasks/{tid}")
    e = apply_update(c, tid, b, conflicts)
    if e:
        return err(e)
    new_due = c.execute("SELECT due FROM tasks WHERE id=?", (tid,)).fetchone()[0]
    shifted = dep_shift(c, tid, old["due"], new_due) if old["status"] == 0 and not old["deleted_at"] else []
    bump(c)
    c.commit()
    return jsonify({**one_task(c, tid), "conflicts": conflicts, "shifted": shifted})


# "Move dependent tasks along" (list setting dep_shift, package D2): when a task's due date moves LATER, the open
# tasks waiting on it that would now start before it is due move by the same number of days (start and due, so
# the duration stays), and so on down the chain. Only tasks in lists with the setting on that the user may change,
# breadth-first, at most DEP_SHIFT_MAX tasks and DEP_SHIFT_DEPTH levels, each task once. Every move is a normal
# change (activity line, reminders re-armed, webhooks). Moving a task earlier never moves anything.
DEP_SHIFT_MAX, DEP_SHIFT_DEPTH = 50, 10


def dep_shift(c, root, old_due, new_due, seen=None, moved=None):
    """Returns [{id, title, start, due, prev_start, prev_due}] of the tasks moved along. seen / moved: shared by the
    calls of one request (D3: a whole list moved -- its own tasks are never moved twice, the cap counts once)."""
    try:
        delta = (date.fromisoformat(new_due) - date.fromisoformat(old_due)).days if old_due and new_due else 0
    except ValueError:
        return []
    moved = [] if moved is None else moved
    if delta <= 0:
        return moved
    uid = me()
    seen = {root} if seen is None else seen
    seen.add(root)
    level = [(root, new_due)]
    for _ in range(DEP_SHIFT_DEPTH):
        nxt = []
        for bid, bdue in level:
            for w in c.execute("""SELECT t.id, t.title, t.start, t.due, t.list_id FROM task_deps d JOIN tasks t ON t.id=d.task_id
                                  JOIN lists l ON l.id=t.list_id
                                  WHERE d.blocker_id=? AND t.status=0 AND t.deleted_at IS NULL AND t.due IS NOT NULL
                                  AND l.dep_shift=1 AND l.kind='project' ORDER BY t.id""", (bid,)).fetchall():
                if w["id"] in seen or (w["start"] or w["due"]) >= bdue or list_role(c, w["list_id"], uid) not in WRITE_ROLES:
                    continue
                if len(moved) >= DEP_SHIFT_MAX:
                    return moved
                seen.add(w["id"])
                try:
                    nd = (date.fromisoformat(w["due"]) + timedelta(days=delta)).isoformat()
                    ns = (date.fromisoformat(w["start"]) + timedelta(days=delta)).isoformat() if w["start"] else None
                except (ValueError, OverflowError):
                    continue
                if apply_update(c, w["id"], {"due": nd, "start": ns, "_act": "dep_shift"}):
                    continue
                moved.append({"id": w["id"], "title": w["title"], "start": ns, "due": nd, "prev_start": w["start"], "prev_due": w["due"]})
                nxt.append((w["id"], nd))
        if not nxt:
            break
        level = nxt
    return moved


# ---------------------------------------------------------------- roadmap (package D3)
# "All" as a timeline: every visible, not archived list with its dated tasks, lists grouped by folder, a summary span
# per list (earliest start -- or due without a start -- to the latest due of its OPEN dated tasks; every such task,
# not only the ones inside the requested window) and the list progress (same numbers as the project progress).
# POST /api/lists/<id>/shift moves every open dated task of a list (subtasks too) by the same number of days in one
# transaction: start and due, so durations stay; tasks without a date stay where they are. Edit rights on the list.
# Moving LATER also moves dependent tasks in other lists along, but only where that list has "Move dependent tasks
# along" on (dep_shift: same rules and caps as a single task). More than SHIFT_MAX_TASKS dated tasks: refused.
SHIFT_MAX_TASKS, SHIFT_MAX_DAYS, ROADMAP_MAX_DAYS = 500, 3650, 1100


def _flag(v, what):
    if v in (None, ""):
        return False
    if str(v).lower() in ("1", "true", "yes"):
        return True
    if str(v).lower() in ("0", "false", "no"):
        return False
    raise BadInput(tr("Invalid value: {0}", what))


def roadmap_build(c, uid, a):
    """a: the query args (from, to, projects_only, include_done). The JSON of GET /api/roadmap and /api/v1/roadmap."""
    t0 = local_now().date()
    try:
        lo = date.fromisoformat(a["from"]) if a.get("from") else t0 - timedelta(days=14)
        hi = date.fromisoformat(a["to"]) if a.get("to") else lo + timedelta(days=194)
    except ValueError:
        raise BadInput(tr("Invalid value: {0}", "from/to")) from None
    if hi < lo or (hi - lo).days > ROADMAP_MAX_DAYS:
        raise BadInput(tr("Date range too large"))
    po, inc = _flag(a.get("projects_only"), "projects_only"), _flag(a.get("include_done"), "include_done")
    lists = [d for d in visible_lists(c, uid) if not d["archived"] and (not po or d.get("kind") == "project")]
    try:
        order = [f for f in json.loads(usettings(c, uid).get("folders") or "[]") if isinstance(f, str) and f]
    except ValueError:
        order = []
    folders = list(dict.fromkeys(order + [d["folder"] for d in lists if d["folder"] and not d["is_inbox"]]))
    rank = {f: i for i, f in enumerate(folders)}
    lists.sort(key=lambda d: (-d["is_inbox"], 0 if d["is_inbox"] or not d["folder"] else 1 + rank[d["folder"]], d["sort"], d["id"]))
    folders = [f for f in folders if any(d["folder"] == f and not d["is_inbox"] for d in lists)]
    ids = [d["id"] for d in lists]
    spans, undated, tasks, deps = {}, {}, {}, []
    if ids:
        q = ",".join("?" * len(ids))
        tv = tvis(c, uid)
        for r in c.execute(f"""SELECT list_id, MIN(COALESCE(start, due)) AS s, MAX(due) AS e, COUNT(*) AS n FROM tasks
                               WHERE list_id IN ({q}) AND {tv} AND status=0 AND deleted_at IS NULL AND due IS NOT NULL GROUP BY list_id""", ids):
            spans[r["list_id"]] = r
        undated = dict(c.execute(f"""SELECT list_id, COUNT(*) FROM tasks WHERE list_id IN ({q}) AND {tv} AND status=0 AND deleted_at IS NULL
                                     AND due IS NULL GROUP BY list_id""", ids).fetchall())
        st = "status IN (0, 2)" if inc else "status=0"
        rows = c.execute(f"""SELECT id, list_id, parent_id, title, start, due, status, priority, assignee_id FROM tasks
                             WHERE list_id IN ({q}) AND {tv} AND deleted_at IS NULL AND {st} AND due IS NOT NULL AND due>=?
                             AND COALESCE(start, due)<=? ORDER BY COALESCE(start, due), due, id""", [*ids, lo.isoformat(), hi.isoformat()]).fetchall()
        for r in rows:
            tasks.setdefault(r["list_id"], []).append({"id": r["id"], "parent_id": r["parent_id"], "title": r["title"], "start": r["start"],
                                                       "due": r["due"], "status": STATUS_NAMES.get(r["status"], "open"),
                                                       "priority": PRIO_NAMES.get(r["priority"], "none"), "assignee_id": r["assignee_id"]})
        tids = [r["id"] for r in rows]
        for i in range(0, len(tids), 900):
            part = tids[i:i + 900]
            deps += [{"task_id": r[0], "blocker_id": r[1]} for r in c.execute(
                f"""SELECT d.task_id, d.blocker_id FROM task_deps d JOIN tasks b ON b.id=d.blocker_id
                    WHERE d.task_id IN ({','.join('?' * len(part))}) AND b.deleted_at IS NULL AND b.list_id IN {vis_sql()}
                    AND {tvis(c, uid, "b.")}
                    ORDER BY d.task_id, d.blocker_id""", [*part, uid, uid])]
    groups = []
    for d in lists:
        sp = spans.get(d["id"])
        groups.append({"list": v1_list(d), "folder": "" if d["is_inbox"] else d["folder"] or "",
                       "span": {"start": sp["s"], "end": sp["e"]} if sp else None, "open_dated": sp["n"] if sp else 0,
                       "undated": undated.get(d["id"], 0), "can_edit": d["role"] in WRITE_ROLES, "tasks": tasks.get(d["id"], [])})
    return {"from": lo.isoformat(), "to": hi.isoformat(), "projects_only": po, "folders": folders, "groups": groups, "deps": deps}


@app.get("/api/roadmap")
def roadmap():
    return jsonify(roadmap_build(db(), me(), request.args))


@app.post("/api/lists/<int:lid>/shift")
def list_shift(lid):
    """{days}: every open dated task of the list moves by that many days (see "roadmap"). One transaction."""
    b = body()
    c = db()
    need_list(c, lid)  # unknown / not visible: 404, view only: 403
    days = as_int(b.get("days"), "days", -SHIFT_MAX_DAYS, SHIFT_MAX_DAYS)
    if not days:
        return err(tr("Invalid value: {0}", "days"))
    rows = c.execute("""SELECT id, title, start, due FROM tasks WHERE list_id=? AND status=0 AND deleted_at IS NULL
                        AND due IS NOT NULL ORDER BY id""", (lid,)).fetchall()
    if len(rows) > SHIFT_MAX_TASKS:
        return err(tr("This list has {0} tasks with a date, at most {1} can be moved at once", len(rows), SHIFT_MAX_TASKS), 409)
    plan = []
    for r in rows:  # every new date first: nothing is written when one of them is out of range
        try:
            plan.append((r, (date.fromisoformat(r["due"]) + timedelta(days=days)).isoformat(),
                         (date.fromisoformat(r["start"]) + timedelta(days=days)).isoformat() if r["start"] else None))
        except (ValueError, OverflowError):
            return err(tr("Invalid value: {0}", "days"))
    moved, shifted = [], []
    for r, nd, ns in plan:
        e = apply_update(c, r["id"], {"due": nd, "start": ns})
        if e:
            c.rollback()
            return err(e)
        moved.append({"id": r["id"], "title": r["title"], "start": ns, "due": nd, "prev_start": r["start"], "prev_due": r["due"]})
    if days > 0:
        seen = {r["id"] for r in rows}
        for m in moved:
            dep_shift(c, m["id"], m["prev_due"], m["due"], seen=seen, moved=shifted)
    if moved:
        bump(c)
    c.commit()
    return jsonify(ok=True, count=len(moved), days=days, moved=moved, shifted=shifted)


def _norm(v):
    if isinstance(v, list):
        return sorted(str(x) for x in v)
    return None if v in ("", None) else str(v)


def apply_update(c, tid, b, conflicts=None):
    """b may carry `_prev` = the values the client saw before its edit (offline replay, detail typing).
    A field whose server value differs from `_prev` was changed elsewhere meanwhile: it is NOT
    overwritten but reported back as a conflict (client lets the user pick).
    The caller checked write access to the task; moves are checked here (Denied)."""
    prev = b.get("_prev") if isinstance(b.get("_prev"), dict) else None
    if prev:
        row = c.execute("SELECT * FROM tasks WHERE id=?", (tid,)).fetchone()
        b = dict(b)
        for k, old in prev.items():
            if k not in b or k.startswith("_"):
                continue
            if k == "fields":  # D4: custom field values, compared per field ({field id: value})
                if not isinstance(old, dict) or not isinstance(b["fields"], dict):
                    continue
                fv = dict(b["fields"])
                have = dict(c.execute("SELECT field_id, value FROM task_field_values WHERE task_id=?", (tid,)).fetchall())
                for fk, fold in old.items():
                    if fk not in fv or not str(fk).isdigit():
                        continue
                    cur = have.get(int(fk))
                    if _norm(cur) != _norm(fold) and _norm(cur) != _norm(fv[fk]):
                        if conflicts is not None:
                            conflicts.append({"field": f"field:{int(fk)}", "server": cur, "mine": fv[fk]})
                        del fv[fk]
                b["fields"] = fv
                continue
            if k == "tags":
                cur = my_tags(c, tid)
            elif k in row.keys():
                cur = row[k]
            else:
                continue
            if _norm(cur) != _norm(old) and _norm(cur) != _norm(b[k]):
                if conflicts is not None:
                    conflicts.append({"field": k, "server": cur, "mine": b[k]})
                del b[k]
    f = clean_task(b)
    if "title" in f and not f["title"]:
        return tr("Title missing")
    e = check_url(f)
    if e:
        return e
    cur = c.execute("SELECT * FROM tasks WHERE id=?", (tid,)).fetchone()  # also the "before" of the activity log
    if f.get("ttype") and f["ttype"] != cur["ttype"] and "content" not in f and not (cur["content"] or "").strip():
        tpl = ticket_template(c, f.get("list_id") or cur["list_id"], f["ttype"])  # 2.4.0 (#340): empty notes get the template
        if tpl:
            f["content"] = tpl
    if has_request_context() and getattr(g, "user", None) and list_role(c, cur["list_id"]) == "participant":
        e = participant_assignee(c, cur, f)
        if e:
            raise Denied(403, e)
        if "list_id" in f and f["list_id"] and f["list_id"] != cur["list_id"]:
            raise Denied(403, tr("Participants cannot move tasks to another list"))
        if "parent_id" in f and f["parent_id"] != cur["parent_id"] and not f["parent_id"] and cur["assignee_id"] != me():
            raise Denied(403, tr("Participants can only move subtasks within their own tasks"))
    if "repeat" in f and f["repeat"] != cur["repeat"]:
        e = repeat_problem(f["repeat"], f.get("due", cur["due"]))
        if e:
            return e
    if "start" in f or "due" in f:  # keep start <= due against the stored other half
        st, du = f.get("start", cur["start"]), f.get("due", cur["due"])
        if st and (not du or st > du):
            f["start"] = du
    if "parent_id" in f:
        e = check_parent(c, tid, f["parent_id"])
        if e:
            return e
        if f["parent_id"]:  # indent: follow the new parent's list / section
            need_task(c, f["parent_id"])
            p = c.execute("SELECT list_id, section_id FROM tasks WHERE id=?", (f["parent_id"],)).fetchone()
            f["list_id"] = p["list_id"]
            f["section_id"] = p["section_id"]
    if "list_id" in f:
        if not f["list_id"]:
            del f["list_id"]
        elif f["list_id"] != cur["list_id"]:
            need_list(c, f["list_id"])  # moving out needs write on the source (caller), in on the target
            check_move(c, cur["list_id"], f["list_id"])
    lid = f.get("list_id", cur["list_id"])
    if f.get("section_id") and not c.execute("SELECT 1 FROM sections WHERE id=? AND list_id=?", (f["section_id"], lid)).fetchone():
        f["section_id"] = None
    if "assignee_id" in f and (collab_all() or _norm(f["assignee_id"]) != _norm(cur["assignee_id"])):
        e = check_assignee(c, lid, f["assignee_id"])
        if e:
            return e
    elif lid != cur["list_id"] and cur["assignee_id"] and cur["assignee_id"] not in list_people(c, lid):
        f["assignee_id"] = None  # the assignee has no access to the new list
    if "assignee_id" in f and _norm(f["assignee_id"]) != _norm(cur["assignee_id"]):
        f["assigned_by"] = me() if f["assignee_id"] else None
    if "fields" in b:  # custom field values: validated before anything is written
        if b["fields"]:
            need_project(c, lid, "fields")
        try:
            fl = {r["id"]: r for r in c.execute("SELECT * FROM list_fields WHERE list_id=?", (lid,))}
            if not isinstance(b["fields"], dict) or any(not str(k).isdigit() or int(k) not in fl for k in b["fields"]):
                raise BadInput(tr("Unknown field"))
            for k, v in b["fields"].items():
                field_value(c, fl[int(k)], v, lid)
        except BadInput as e:
            return str(e)
    if f:
        # a changed date / reminder set re-arms the reminder
        if any(k in f for k in ("due", "due_time", "reminders", "assignee_id")):
            f["reminded"] = "[]"
        f["updated_at"] = iso(now_utc())
        c.execute(f"UPDATE tasks SET {','.join(k + '=?' for k in f)} WHERE id=?", [*f.values(), tid])
        if "list_id" in f:  # subtasks follow their parent (all levels)
            move_subtree(c, tid, f["list_id"])
            if "section_id" not in f:
                c.execute("UPDATE tasks SET section_id=NULL WHERE id=?", (tid,))
    if f:
        log_changes(c, tid, cur, b.get("_act"))
        new_a = c.execute("SELECT assignee_id FROM tasks WHERE id=?", (tid,)).fetchone()[0]
        assignment_events(c, tid, cur["assignee_id"], new_a)
    if f and "list_id" in f and f["list_id"] != cur["list_id"]:
        ltags_follow(c, tid, f["list_id"])
    if "ltags" in b:
        try:
            set_ltags(c, tid, b["ltags"])
        except BadInput as e:
            return str(e)
    if f and ("title" in f or "content" in f):
        agent_task_mentions(c, tid, (cur["title"] or "") + "\n" + (cur["content"] or ""))
    if "tags" in b:
        set_tags(c, tid, b["tags"])
    elif "add_tags" in b:
        set_tags(c, tid, my_tags(c, tid) + list(b["add_tags"]))
    if "fields" in b and set_field_values(c, tid, lid, b["fields"]):
        c.execute("UPDATE tasks SET updated_at=? WHERE id=?", (iso(now_utc()), tid))
    return None


def next_due(t):
    """Next occurrence (date, keeps due_time) for a recurring task, or None."""
    if not t["repeat"] or not t["due"]:
        return None
    try:
        base = t["due"] if t["repeat_from"] != "done" else local_now().date().isoformat()
        rule = rr_rule(t["repeat"], base)
        if rule is None:
            print("rrule not usable:", t["id"], repr(t["repeat"]), flush=True)
            return None
        d = date.fromisoformat(base)
        nxt = rule.after(datetime(d.year, d.month, d.day))
        return nxt.date().isoformat() if nxt and nxt.year <= DATE_MAX_Y else None
    except (ValueError, TypeError, OverflowError) as e:
        print("rrule error:", t["id"], t["repeat"], e, flush=True)
        return None


def repeat_problem(rep, due):
    """Error text if a new / changed rule never produces a date from due on, else None."""
    if rep and due and not rr_feasible(rr_norm(rep), due):
        return tr("Repeat: the rule has no date in the next 10 years")
    return None


def rr_count(repeat):
    m = re.search(r"(?:^|;)COUNT=(\d+)", repeat or "")
    return int(m.group(1)) if m else None


def rr_with_count(repeat, n):
    return re.sub(r"(^|;)COUNT=\d+", lambda m: f"{m.group(1)}COUNT={n}", repeat)


@app.post("/api/tasks/<int:tid>/complete")
def task_complete(tid):
    c = db()
    need_task(c, tid)
    t = c.execute("SELECT * FROM tasks WHERE id=?", (tid,)).fetchone()
    b = body()
    # the same recurring task ticked on two devices (one offline): only the first tick advances it
    if t["repeat"] and b.get("expect_due") and t["status"] == 0 and b["expect_due"] != t["due"]:
        return jsonify({**one_task(c, tid), "next_due": None, "skipped": True})
    st = int(b.get("status", 2))
    undo = {}
    nxt = do_complete(c, tid, st, undo)
    log_act(c, tid, "wont" if st == -1 else "reopen" if st == 0 else "complete", {"next": nxt} if nxt else None)
    if st == 2:
        task_event(c, tid, "complete")
    if st != 0:
        unblock_events(c, completed_ids(c, tid))
        push_handled(c, me(), [tid])  # 2.0.5: close its notification on my other devices
    bump(c)
    c.commit()
    return jsonify({**one_task(c, tid), "next_due": nxt, "undo": signed(tid, undo)})


def do_complete(c, tid, status=2, undo=None):
    """undo (dict, filled in): what POST /api/tasks/<id>/undo needs to take this completion back."""
    t = c.execute("SELECT * FROM tasks WHERE id=?", (tid,)).fetchone()
    ts = iso(now_utc())
    who = (me() or None) if status != 0 else None  # 0 = public link: nobody's completion (statistics)
    cnt = rr_count(t["repeat"])
    nxt = next_due(t) if status == 2 and (cnt is None or cnt > 1) else None
    if undo is not None:
        undo.update(op="complete", at=ts, status=t["status"], repeat=t["repeat"], due=t["due"], start=t["start"],
                    reminded=t["reminded"], copy_id=None, kids=[])
    if status == 2 and t["repeat"] and not nxt:  # last repeat (COUNT used up / past UNTIL): done for good
        c.execute("UPDATE tasks SET repeat='' WHERE id=?", (tid,))
    if nxt:
        # keep a completed copy in the history, move the original forward
        cols = [k for k in t.keys() if k not in ("id", "tt_id")]
        vals = {k: t[k] for k in cols}
        vals.update(status=2, repeat="", completed_at=ts, updated_at=ts, reminded="[]", completed_by=who)
        cur = c.execute(f"INSERT INTO tasks({','.join(cols)}) VALUES({','.join('?' * len(cols))})",
                        [vals[k] for k in cols])
        for r in c.execute("SELECT user_id, tag FROM task_tags WHERE task_id=?", (tid,)).fetchall():
            c.execute("INSERT INTO task_tags(task_id,user_id,tag) VALUES(?,?,?)", (cur.lastrowid, r["user_id"], r["tag"]))
        c.execute("INSERT INTO task_field_values(task_id,field_id,value) SELECT ?, field_id, value FROM task_field_values WHERE task_id=?",
                  (cur.lastrowid, tid))
        c.execute("INSERT OR IGNORE INTO sample_items(user_id,kind,item_id) SELECT user_id, 'task', ? FROM sample_items "
                  "WHERE kind='task' AND item_id=?", (cur.lastrowid, tid))
        start = t["start"]
        if start:  # timeline range moves along with the due date
            start = (date.fromisoformat(start) + (date.fromisoformat(nxt) - date.fromisoformat(t["due"]))).isoformat()
        c.execute("UPDATE tasks SET due=?, start=?, reminded='[]', updated_at=? WHERE id=?", (nxt, start, ts, tid))
        if cnt:
            c.execute("UPDATE tasks SET repeat=? WHERE id=?", (rr_with_count(t["repeat"], cnt - 1), tid))
        for d in descendants(c, tid):
            k = c.execute("SELECT status, completed_at, completed_by FROM tasks WHERE id=?", (d,)).fetchone()
            if undo is not None and k["status"] != 0:
                undo["kids"].append([d, k["status"], k["completed_at"], k["completed_by"]])
            c.execute("UPDATE tasks SET status=0, completed_at=NULL, completed_by=NULL WHERE id=?", (d,))
        if undo is not None:
            undo.update(copy_id=cur.lastrowid, next=nxt)
    else:
        c.execute("UPDATE tasks SET status=?, completed_at=?, completed_by=?, updated_at=? WHERE id=?",
                  (status, ts, who, ts, tid))
        if status != 0:  # completing a parent completes its open subtasks (all levels)
            for d in descendants(c, tid):
                c.execute("UPDATE tasks SET status=?, completed_at=?, completed_by=?, updated_at=? WHERE id=? AND status=0",
                          (status, ts, who, ts, d))
    return nxt


def undo_sig(tid, u):
    """HMAC over an undo payload (task, user, content): the client hands it back unchanged or not at all."""
    key = UNDO_KEY.get("k") or UNDO_KEY.setdefault("k", gsetting(db(), "undo_key"))
    msg = json.dumps({"tid": tid, "uid": me(), **{k: v for k, v in u.items() if k != "sig"}}, sort_keys=True, default=str)
    return hmac.new(key.encode(), msg.encode(), hashlib.sha256).hexdigest()


def signed(tid, u):
    return {**u, "sig": undo_sig(tid, u)} if u else u


UNDO_KEY = {}


def undo_status(c, tid, u):
    """Takes back a completion (op complete: the dict do_complete filled) or a reopen (op reopen: the
    status / completed_at / completed_by the task had). The caller checked write access. Returns an
    error text or None. Only acts while the task is still in the state the action left it in."""
    t = c.execute("SELECT * FROM tasks WHERE id=?", (tid,)).fetchone()
    if not t or not isinstance(u, dict) or not hmac.compare_digest(str(u.get("sig") or ""), undo_sig(tid, u)):
        return tr("unknown")
    ts = iso(now_utc())
    people = list_people(c, t["list_id"])

    def who(v):  # a completer from the client: only someone of this list, else me
        try:
            return int(v) if int(v) in people else me()
        except (TypeError, ValueError):
            return me()

    def when(v):
        try:
            parse_iso(str(v))
            return str(v)
        except ValueError:
            return ts
    if u.get("op") == "reopen":
        st = int(u.get("status") or 0)
        if t["status"] != 0 or st not in (2, -1):
            return tr("Changed in the meantime, nothing to undo")
        c.execute("UPDATE tasks SET status=?, completed_at=?, completed_by=?, updated_at=? WHERE id=?",
                  (st, when(u.get("completed_at")), who(u.get("completed_by")), ts, tid))
        log_act(c, tid, "wont" if st == -1 else "complete")
        return None
    if u.get("op") != "complete" or not u.get("at"):
        return tr("unknown")
    at = str(u["at"])
    cp = u.get("copy_id")
    if cp:  # recurring: drop the completed copy, move the task back to the occurrence it was on
        row = c.execute("SELECT * FROM tasks WHERE id=?", (int(cp),)).fetchone()
        if t["status"] != 0 or t["due"] != u.get("next") or not row or row["list_id"] != t["list_id"] or row["completed_at"] != at or row["status"] == 0 \
                or row["created_at"] != t["created_at"] or row["title"] != t["title"] or row["repeat"] \
                or row["id"] < tid or row["parent_id"] != t["parent_id"]:
            return tr("Changed in the meantime, nothing to undo")
        files = attachment_files(c, [row["id"]])
        c.execute("DELETE FROM tasks WHERE id=?", (row["id"],))
        unlink_files(files)
        try:
            due = date.fromisoformat(str(u.get("due"))).isoformat()
            start = date.fromisoformat(str(u["start"])).isoformat() if u.get("start") else None
            rem = json.dumps([str(x) for x in json.loads(u.get("reminded") or "[]")][-20:])
        except (ValueError, TypeError):
            return tr("unknown")
        c.execute("UPDATE tasks SET due=?, start=?, repeat=?, reminded=?, updated_at=? WHERE id=?",
                  (due, start, str(u.get("repeat") or "")[:500], rem, ts, tid))
        for k in u.get("kids") or []:
            try:
                d, st, cat, cby = int(k[0]), int(k[1]), when(k[2]), who(k[3])
            except (TypeError, ValueError, IndexError):
                continue
            if st not in (2, -1):
                continue
            c.execute("UPDATE tasks SET status=?, completed_at=?, completed_by=? WHERE id=? AND parent_id IS NOT NULL AND status=0 AND list_id=?",
                      (st, cat, cby, d, t["list_id"]))
    else:
        if t["status"] == 0 or t["completed_at"] != at:
            return tr("Changed in the meantime, nothing to undo")
        c.execute("UPDATE tasks SET status=0, completed_at=NULL, completed_by=NULL, updated_at=? WHERE id=?", (ts, tid))
        if u.get("repeat") and not t["repeat"]:  # the last occurrence had ended the repetition
            c.execute("UPDATE tasks SET repeat=? WHERE id=?", (str(u["repeat"])[:500], tid))
        for d in descendants(c, tid):  # subtasks completed together with it
            c.execute("UPDATE tasks SET status=0, completed_at=NULL, completed_by=NULL, updated_at=? WHERE id=? AND completed_at=?",
                      (ts, d, at))
    # the "completed" News items this completion created for others
    c.execute("DELETE FROM notifications WHERE task_id=? AND kind='complete' AND actor_id=? AND created_at>=?",
              (tid, me(), at))
    fam = [tid, *descendants(c, tid)]  # ... and the "unblock" items / lines it caused (the tasks wait again)
    q = ",".join("?" * len(fam))
    c.execute(f"DELETE FROM notifications WHERE kind='unblock' AND actor_id=? AND created_at>=? AND json_extract(data,'$.blocker') IN ({q})",
              (me(), at, *fam))
    c.execute(f"DELETE FROM activity WHERE kind='unblocked' AND user_id=? AND created_at>=? AND json_extract(data,'$.id') IN ({q})",
              (me(), at, *fam))
    log_act(c, tid, "reopen")
    return None


@app.post("/api/tasks/<int:tid>/undo")
def task_undo(tid):
    """Undo toast: takes back the completion / reopen described by the body (see undo_status)."""
    c = db()
    need_task(c, tid)
    e = undo_status(c, tid, body())
    if e:
        c.rollback()
        return err(e, 409)
    bump(c)
    c.commit()
    return jsonify(one_task(c, tid))


@app.post("/api/tasks/<int:tid>/skip")
def task_skip(tid):
    """'Skip this occurrence': move a recurring task to its next date without a done copy."""
    c = db()
    need_task(c, tid)
    t = c.execute("SELECT * FROM tasks WHERE id=?", (tid,)).fetchone()
    if not t["repeat"] or not t["due"]:
        return err(tr("Not a recurring task"))
    cnt = rr_count(t["repeat"])
    base = dict(t)
    base["repeat_from"] = "due"  # skipping always means: the next regular date
    nxt = next_due(base) if cnt is None or cnt > 1 else None
    if not nxt:
        return err(tr("This is already the last occurrence"))
    start = t["start"]
    if start:
        start = (date.fromisoformat(start) + (date.fromisoformat(nxt) - date.fromisoformat(t["due"]))).isoformat()
    rep_new = rr_with_count(t["repeat"], cnt - 1) if cnt else t["repeat"]
    c.execute("UPDATE tasks SET due=?, start=?, repeat=?, reminded='[]', updated_at=? WHERE id=?",
              (nxt, start, rep_new, iso(now_utc()), tid))
    log_act(c, tid, "skip", {"next": nxt})
    bump(c)
    c.commit()
    return jsonify({**one_task(c, tid), "next_due": nxt})


@app.post("/api/tasks/<int:tid>/reopen")
def task_reopen(tid):
    c = db()
    need_task(c, tid)
    old = c.execute("SELECT status, completed_at, completed_by FROM tasks WHERE id=?", (tid,)).fetchone()
    if old["status"] != 0:
        log_act(c, tid, "reopen")
    c.execute("UPDATE tasks SET status=0, completed_at=NULL, completed_by=NULL, updated_at=? WHERE id=?", (iso(now_utc()), tid))
    bump(c)
    c.commit()
    undo = {"op": "reopen", "status": old["status"], "completed_at": old["completed_at"], "completed_by": old["completed_by"]}
    return jsonify({**one_task(c, tid), "undo": signed(tid, undo) if old["status"] != 0 else None})


@app.delete("/api/tasks/<int:tid>")
def task_delete(tid):
    c = db()
    role = need_task(c, tid)
    if role == "participant":
        raise Denied(403, tr("Participants cannot delete tasks"))
    files = []
    if request.args.get("hard") == "1":
        if role != "owner":  # shared list: edit members only move tasks to the trash
            raise Denied(403, tr("Only the list owner can delete tasks permanently"))
        wh_note(c, tid, "purge")
        files = hard_delete(c, [tid])
    else:
        trash_task(c, tid)
    bump(c)
    c.commit()
    unlink_files(files)
    return jsonify(ok=True)


def trash_task(c, tid):
    """Moves a task (and its subtasks) to the trash with a history line (web client, REST API)."""
    do_delete(c, tid)
    log_act(c, tid, "delete")


def do_delete(c, tid):
    ts = iso(now_utc())
    for i in [tid, *descendants(c, tid)]:
        c.execute("UPDATE tasks SET deleted_at=COALESCE(deleted_at, ?) WHERE id=?", (ts, i))


@app.post("/api/tasks/<int:tid>/restore")
def task_restore(tid):
    c = db()
    need_task(c, tid)
    restore_task(c, tid)
    bump(c)
    c.commit()
    return jsonify(ok=True)


def restore_task(c, tid):
    r = c.execute("SELECT deleted_at FROM tasks WHERE id=?", (tid,)).fetchone()
    if r:
        c.execute("UPDATE tasks SET deleted_at=NULL WHERE id=?", (tid,))
        for d in descendants(c, tid):  # children deleted together with it come back too
            c.execute("UPDATE tasks SET deleted_at=NULL WHERE id=? AND deleted_at=?", (d, r["deleted_at"]))
        # restoring a subtask whose parent is gone makes it top-level
        c.execute("""UPDATE tasks SET parent_id=NULL WHERE id=? AND parent_id IN
                     (SELECT id FROM tasks WHERE deleted_at IS NOT NULL)""", (tid,))
        if r["deleted_at"]:
            log_act(c, tid, "restore")


@app.post("/api/tasks/purge-done")
def purge_done():
    """Settings > 'Delete all completed': every done / won't-do task in MY lists -> trash
    (shared lists of other owners are left alone)."""
    c = db()
    n = c.execute("""UPDATE tasks SET deleted_at=? WHERE status!=0 AND deleted_at IS NULL
                     AND list_id IN (SELECT id FROM lists WHERE owner_id=?)""", (iso(now_utc()), me())).rowcount
    bump(c)
    c.commit()
    return jsonify(count=n)


def purge_lists(c, uid=None):
    """Ids of the lists whose trash the user may empty for good: the lists they OWN; instance admins (2.0.5) also the
    shared lists of other owners where they may edit (member or list admin). Everyone else's deleted tasks in shared
    lists stay in the trash: only the list owner deletes them permanently."""
    uid = uid or me()
    u = c.execute("SELECT is_admin FROM users WHERE id=?", (uid,)).fetchone()
    q, a = (wr_sql(), (uid, uid)) if u and u["is_admin"] else ("(SELECT id FROM lists WHERE owner_id=?)", (uid,))
    return {r[0] for r in c.execute(f"SELECT id FROM lists WHERE id IN {q}", a)}


@app.delete("/api/trash")
def trash_empty():
    """Hard-deletes the trash of the lists purge_lists() allows. {deleted, kept}: kept = deleted tasks the user sees in
    the trash but may not delete for good (shared lists of other owners)."""
    c = db()
    uid = me()
    ok = purge_lists(c, uid)
    rows = c.execute(f"SELECT id, list_id FROM tasks WHERE deleted_at IS NOT NULL AND list_id IN {wr_sql()}", (uid, uid)).fetchall()
    ids = [r["id"] for r in rows if r["list_id"] in ok]
    files = hard_delete(c, ids, lists=ok)
    bump(c)
    c.commit()
    unlink_files(files)
    return jsonify(ok=True, deleted=len(ids), kept=len(rows) - len(ids))


# ---------------------------------------------------------------- attachments

def safe_name(n):
    n = os.path.basename((n or "").replace("\\", "/")).strip()
    n = re.sub(r"[\x00-\x1f/\\:*?\"<>|]", "_", n)[:150]
    return n or "datei"


@app.post("/api/tasks/<int:tid>/attachments")
def attachment_upload(tid):
    c = db()
    need_task(c, tid)
    files = request.files.getlist("file")
    if not files:
        return err(tr("File missing"))
    saved = []
    e = save_attachments(c, tid, files, saved=saved)
    if e:
        c.rollback()
        unlink_files(saved)
        return err(e)
    log_act(c, tid, "attach", {"names": [safe_name(f.filename) for f in files][:20], "n": len(files)})
    bump(c)
    c.commit()
    return jsonify(one_task(c, tid))


def save_attachments(c, tid, files, comment_id=None, saved=None):
    """Store uploaded werkzeug files for a task (or one of its comments). Returns an error message or
    None (caller commits; on an error the caller rolls back and unlinks `saved`)."""
    try:
        os.makedirs(os.path.join(ATT_DIR, str(tid)), exist_ok=True)
    except OSError as e:
        aa_count("storage", "attachments", aa_oserr(e))
        raise
    ts = iso(now_utc())
    for f in files:
        name = safe_name(f.filename)
        rel = os.path.join(str(tid), f"{uuid.uuid4().hex[:12]}-{name}")
        full = os.path.join(ATT_DIR, rel)
        try:
            f.save(full)
        except OSError as e:
            aa_count("storage", "attachments", aa_oserr(e))
            raise
        size = os.path.getsize(full)
        if size > MAX_FILE_MB * 1024 * 1024:
            os.remove(full)
            return tr("{0}: larger than {1} MB", name, MAX_FILE_MB)
        if saved is not None:
            saved.append(rel)
        mime = (f.mimetype if f.mimetype and f.mimetype != "application/octet-stream" else None) \
            or mimetypes.guess_type(name)[0] or "application/octet-stream"
        c.execute("INSERT INTO attachments(task_id,name,mime,size,path,created_at,comment_id) VALUES(?,?,?,?,?,?,?)",
                  (tid, name, mime, size, rel, ts, comment_id))
    if comment_id is None:
        c.execute("UPDATE tasks SET updated_at=? WHERE id=?", (ts, tid))
    return None


def need_attachment(c, aid, write):
    """Task files: read = sees the task, write = may change it. Comment files: read = sees the task
    (and the comment is not deleted), write = the comment's author (or the list owner, moderation)."""
    a = c.execute("SELECT * FROM attachments WHERE id=?", (aid,)).fetchone()
    if not a:
        raise Denied(404)
    if a["comment_id"] is None:
        need_task(c, a["task_id"], write, full=True)
        return a
    role = need_task(c, a["task_id"], write=False, full=True)
    cm = c.execute("SELECT user_id, deleted_at FROM comments WHERE id=?", (a["comment_id"],)).fetchone()
    if not cm or cm["deleted_at"]:
        raise Denied(404)
    if write and cm["user_id"] != me() and role not in MANAGE_ROLES:
        raise Denied(403)
    return a


@app.get("/api/attachments/<int:aid>")
def attachment_get(aid):
    a = need_attachment(db(), aid, False)
    full = os.path.join(ATT_DIR, a["path"])
    if not os.path.isfile(full):
        return err(tr("File missing on the server"), 404)
    inline = a["mime"] in INLINE_TYPES and request.args.get("dl") != "1"
    resp = send_file(full, mimetype=a["mime"] if inline else "application/octet-stream",
                     as_attachment=not inline, download_name=a["name"], conditional=True, max_age=0)
    if a["mime"] != "application/pdf":  # the browser pdf viewer does not run inside a sandboxed CSP
        resp.headers["Content-Security-Policy"] = "default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; sandbox"
    resp.headers["Cache-Control"] = "private, max-age=86400"
    return resp


# ---------------------------------------------------------------- paperless
# 2.1.0 (#180): several connections.
#  - Connection 0 = the legacy one from the environment (PAPERLESS_TOKEN / PAPERLESS_API / PAPERLESS_PUBLIC_URL, named
#    "Paperless"): the archive of the token owner, for users an admin gave "Paperless access" (as before). Its token
#    stays in the environment. Links from before 2.1.0 belong to it (paperless_links.conn_id NULL).
#  - Server connections (pl_conns.kind 'server'), set up by an admin: name + URL, NO shared token. Every user the admin
#    allows enters their OWN Paperless API token, so Paperless' permissions and groups apply per person.
#  - Personal connections (kind 'personal'): name + URL + token of one user. Only that user sees and uses them; admins can
#    neither see nor grant them (not in the admin UI, not in any API answer for someone else).
# Tokens are write-only (no API answer or page ever contains one: "set" / "not set" only) and encrypted at rest
# (AES-GCM, key KALMIDO_SECRET_KEY from the environment, never in the DB / data dir; associated data = connection + user).
# Without the key no token can be stored (the legacy connection keeps working). Requests to personal connections go
# through the SSRF guard of the calendar subscriptions (public addresses only, internal hosts only where an admin
# allowed them), and no connection follows redirects, so a token only ever goes to the host of its connection.
PL_CONN_MAX = 10          # personal connections per user
PL_SERVER_MAX = 20        # server connections
PL_NAME_MAX, PL_TOKEN_MAX = 60, 400
PL_MAX_BYTES = 25 * 1024 * 1024


class PaperlessError(Exception):
    pass


def pl_key_error():
    return tr("Set KALMIDO_SECRET_KEY on the server to store Paperless tokens (32 random bytes, base64)")


def pl_seal(cid, uid, token):
    if not SECRET_KEY:
        raise BadInput(pl_key_error())
    n = os.urandom(12)
    return "v1." + _b64u(n + AESGCM(SECRET_KEY).encrypt(n, token.encode(), f"kalmido-pl:{cid}:{uid}".encode()))


def pl_unseal(cid, uid, s):
    """The token or '' (no key, another key, damaged): then it counts as not set."""
    if not SECRET_KEY or not s or not s.startswith("v1."):
        return ""
    try:
        raw = _b64u_dec(s[3:])
        return AESGCM(SECRET_KEY).decrypt(raw[:12], raw[12:], f"kalmido-pl:{cid}:{uid}".encode()).decode()
    except (InvalidTag, ValueError, TypeError):
        return ""


def pl_norm_url(u):
    """The base URL of a Paperless server (http(s), no credentials / query / fragment; a trailing /api is dropped)."""
    u = cal_norm_url(u)
    if not u or not u.lower().startswith(("http://", "https://")):
        return None
    p = urllib.parse.urlsplit(u)
    if p.query or p.fragment:
        return None
    u = u.rstrip("/")
    if u.lower().endswith("/api"):
        u = u[:-4]
    return u


def pl_legacy():
    return {"id": 0, "kind": "legacy", "name": "Paperless", "url": PL_PUBLIC, "api": PL_API, "token": PL_TOKEN,
            "guard": False, "allow": frozenset()}


def pl_token_row(c, cid, uid):
    return c.execute("SELECT token FROM pl_tokens WHERE conn_id=? AND user_id=?", (cid, uid)).fetchone()


def pl_may(c, r, uid):
    """May uid use connection row r at all (token aside)?"""
    if r["kind"] == "personal":
        return r["owner_id"] == uid
    return bool(c.execute("SELECT 1 FROM pl_conn_users WHERE conn_id=? AND user_id=?", (r["id"], uid)).fetchone())


def pl_conn(c, cid, uid):
    """Connection cid as uid may use it right now (their token set) -> dict with token, else None."""
    cid = int(cid or 0)
    u = c.execute("SELECT * FROM users WHERE id=?", (uid,)).fetchone() if uid else None
    if not u or is_agent(u):
        return None
    if not cid:
        return pl_legacy() if PL_TOKEN and u["paperless_access"] else None
    r = c.execute("SELECT * FROM pl_conns WHERE id=?", (cid,)).fetchone()
    if not r or not pl_may(c, r, uid):
        return None
    tk = pl_token_row(c, cid, uid)
    token = pl_unseal(cid, uid, tk["token"]) if tk else ""
    if not token:
        return None
    guard = r["kind"] == "personal"
    return {"id": r["id"], "kind": r["kind"], "name": r["name"], "url": r["url"], "api": r["url"], "token": token,
            "guard": guard, "allow": cal_allow(c) if guard else frozenset()}


def pl_conns_for(c, uid):
    """The connections uid sees (Settings, the link dialog): never a token, only whether theirs is set."""
    u = c.execute("SELECT * FROM users WHERE id=?", (uid,)).fetchone()
    if not u or is_agent(u):
        return []
    out = []
    if PL_TOKEN and u["paperless_access"]:
        out.append({"id": 0, "kind": "legacy", "name": "Paperless", "url": PL_PUBLIC, "token_set": True, "usable": True})
    for r in c.execute("""SELECT p.* FROM pl_conns p WHERE (p.kind='personal' AND p.owner_id=?) OR (p.kind='server' AND p.id IN
                          (SELECT conn_id FROM pl_conn_users WHERE user_id=?)) ORDER BY p.kind DESC, p.name COLLATE NOCASE, p.id""",
                          (uid, uid)):
        tk = pl_token_row(c, r["id"], uid)
        ok = bool(tk) and bool(pl_unseal(r["id"], uid, tk["token"]))
        out.append({"id": r["id"], "kind": r["kind"], "name": r["name"], "url": r["url"], "token_set": bool(tk),
                    "token_ok": ok, "usable": ok})
    return out


def pl_state(c, u):
    """/api/state: enabled = at least one usable connection; configured = the legacy env connection exists (admin UI);
    conns = what I see (no tokens); key = tokens can be stored; url = the first usable connection (old clients)."""
    conns = pl_conns_for(c, u["id"])
    use = [x for x in conns if x["usable"]]
    return {"enabled": bool(use), "configured": bool(PL_TOKEN), "url": use[0]["url"] if use else "", "conns": conns,
            "key": bool(SECRET_KEY), "personal": not is_agent(u)}


def pl_usable_ids(c, uid):
    """Ids of the connections uid can use now (0 = legacy): link titles / thumbnails are only shown for these."""
    if not uid:
        return set()
    return {x["id"] for x in pl_conns_for(c, uid) if x["usable"]}


def pl_forget_user(c, uid):
    """A user is deleted / becomes an agent: their personal connections, tokens and grants go (list bells too)."""
    c.execute("DELETE FROM pl_tokens WHERE conn_id IN (SELECT id FROM pl_conns WHERE kind='personal' AND owner_id=?)", (uid,))
    c.execute("DELETE FROM pl_conns WHERE kind='personal' AND owner_id=?", (uid,))
    c.execute("DELETE FROM pl_tokens WHERE user_id=?", (uid,))
    c.execute("DELETE FROM pl_conn_users WHERE user_id=?", (uid,))
    c.execute("DELETE FROM list_bell WHERE user_id=?", (uid,))


def pl_req(cn, path, method="GET", body=None, ctype=None, raw=False, timeout=20):
    """One request to connection cn (pl_conn): the token only goes to that connection's own host (no redirects)."""
    if not cn or not cn.get("token"):
        raise PaperlessError(tr("Paperless is not set up"))
    legacy = cn["id"] == 0
    hdr = {"Authorization": f"Token {cn['token']}", "Accept": "application/json"}
    if ctype:
        hdr["Content-Type"] = ctype
    req = urllib.request.Request(cn["api"] + path, data=body, headers=hdr, method=method)
    try:
        opener = _cal_opener(cn["allow"]) if cn.get("guard") else None
        with (opener.open(req, timeout=timeout) if opener else safe_urlopen(req, timeout=timeout)) as r:
            data = r.read(PL_MAX_BYTES + 1)
            if len(data) > PL_MAX_BYTES:
                raise PaperlessError(tr("Paperless: the answer is too large"))
            if legacy:
                aa_ok("paperless")
            return (data, r.headers.get("Content-Type", "")) if raw else json.loads(data or b"null")
    except urllib.error.HTTPError as e:
        if legacy and (e.code in (401, 403) or e.code >= 500):  # admin alert after aa_integ_min minutes of this
            aa_fail("paperless", {401: "HTTP 401 unauthorised", 403: "HTTP 403 forbidden"}.get(e.code, f"HTTP {e.code}"))
        elif legacy:
            aa_ok("paperless")
        if 300 <= e.code < 400:
            raise PaperlessError(tr("Paperless: the server redirects to another address, which is not followed")) from e
        msg = {401: N_("invalid token"), 403: N_("no permission"), 404: N_("document not found")}.get(e.code)
        raise PaperlessError(f"Paperless: {tr(msg)}" if msg else
                             f"Paperless: HTTP {e.code} {e.read()[:200].decode('utf-8', 'replace')}") from e
    except PaperlessError:
        raise
    except (urllib.error.URLError, TimeoutError, OSError, CalError, http.client.HTTPException, ValueError) as e:
        rs = getattr(e, "reason", None)
        if isinstance(e, CalError) or isinstance(rs, CalError):
            ce = e if isinstance(e, CalError) else rs
            if getattr(ce, "code", "") == "blocked":
                raise PaperlessError(tr("Paperless: this address is in an internal network; an admin can allow the host")) from e
        if legacy:
            aa_fail("paperless", aa_err(e))
        raise PaperlessError(tr("Paperless not reachable ({0})", type(e).__name__ if not legacy else e)) from e


_corr = {}


def pl_correspondents(cn):
    key = (cn["id"], hashlib.sha256(cn["token"].encode()).hexdigest()[:16])
    hit = _corr.get(key)
    if not hit or time.time() - hit[0] > 600:
        j = pl_req(cn, "/api/correspondents/?page_size=1000&fields=id,name")
        if len(_corr) > 200:
            _corr.clear()
        hit = _corr[key] = (time.time(), {r["id"]: r["name"] for r in j.get("results", [])})
    return hit[1]


def pl_doc(cn, doc_id):
    d = pl_req(cn, f"/api/documents/{int(doc_id)}/?fields=id,title,created,correspondent")
    return {"doc_id": d["id"], "title": d.get("title") or tr("Document {0}", d['id']),
            "correspondent": pl_correspondents(cn).get(d.get("correspondent"), "") if d.get("correspondent") else "",
            "created": (d.get("created") or "")[:10]}


@app.errorhandler(PaperlessError)
def paperless_error(e):
    return err(str(e), 502)


def pl_access(u=None):
    """The legacy connection (environment token) is the whole archive of the token owner: only users an admin granted access."""
    u = u if u is not None else (g.user if has_request_context() and getattr(g, "user", None) else None)
    return bool(PL_TOKEN) and bool(u) and bool(u["paperless_access"])


def pl_conn_arg(v):
    try:
        return max(0, int(v or 0))
    except (TypeError, ValueError):
        raise BadInput(tr("Invalid value: {0}", "conn")) from None


def need_paperless(c=None, cid=0):
    """The connection cid for the current user, or 403 / 502."""
    c = c or db()
    cn = pl_conn(c, cid, me())
    if cn:
        return cn
    if not cid and not PL_TOKEN:
        raise PaperlessError(tr("Paperless is not set up"))
    if not cid:
        raise Denied(403, tr("No access to Paperless (an admin can allow it)"))
    raise Denied(403, tr("No access to this Paperless connection (or your token is not set)"))


PL_THUMB_TYPES = {"image/webp", "image/png", "image/jpeg", "image/gif", "image/avif"}


@app.get("/api/paperless/search")
def paperless_search():
    cn = need_paperless(db(), pl_conn_arg(request.args.get("conn")))
    q = (request.args.get("q") or "").strip()
    fields = "id,title,created,correspondent,page_count,mime_type"
    base = f"/api/documents/?page_size=20&fields={fields}"
    if q:
        j = pl_req(cn, base + "&query=" + urllib.parse.quote(q))
        if not j.get("count") and re.fullmatch(r"[\w\s.-]+", q):  # word fragments: prefix search ("stadtw*")
            j = pl_req(cn, base + "&query=" + urllib.parse.quote(" ".join(w + "*" for w in q.split())))
        if not j.get("count"):  # last resort: plain title match
            j = pl_req(cn, base + "&ordering=-created&title__icontains=" + urllib.parse.quote(q))
    else:
        j = pl_req(cn, base + "&ordering=-added")
    corr = pl_correspondents(cn)
    items = []
    for d in j.get("results", []):
        hit = (d.get("__search_hit__") or {}).get("highlights") or ""
        items.append({"id": d["id"], "title": d.get("title") or "", "created": (d.get("created") or "")[:10],
                      "correspondent": corr.get(d.get("correspondent"), "") if d.get("correspondent") else "",
                      "pages": d.get("page_count"),
                      "snippet": re.sub(r"\s+", " ", re.sub(r"</?b>", "", hit)).strip()[:160]})
    return jsonify(items=items, count=j.get("count", 0), url=cn["url"], conn=cn["id"])


@app.get("/api/paperless/thumb/<int:doc_id>")
def paperless_thumb(doc_id):
    cn = need_paperless(db(), pl_conn_arg(request.args.get("conn")))
    data, ctype = pl_req(cn, f"/api/documents/{doc_id}/thumb/", raw=True)
    ctype = (ctype or "").split(";")[0].strip().lower()
    if ctype not in PL_THUMB_TYPES:  # never serve upstream html/svg/... from our origin
        return err(tr("Paperless: unexpected thumbnail type"), 502)
    resp = Response(data, mimetype=ctype)
    resp.headers["Cache-Control"] = "private, max-age=86400"
    resp.headers["X-Content-Type-Options"] = "nosniff"
    resp.headers["Content-Security-Policy"] = "default-src 'none'; img-src 'self'; style-src 'unsafe-inline'; sandbox"
    return resp


@app.post("/api/tasks/<int:tid>/paperless")
def paperless_link(tid):
    c = db()
    need_task(c, tid)
    b = body()
    cid = pl_conn_arg(b.get("conn"))
    cn = need_paperless(c, cid)
    try:
        doc_id = int(b.get("doc_id") or 0)
    except (TypeError, ValueError):
        return err(tr("unknown"))
    if not c.execute("SELECT 1 FROM paperless_links WHERE task_id=? AND doc_id=? AND COALESCE(conn_id,0)=?",
                     (tid, doc_id, cid)).fetchone():
        d = pl_doc(cn, doc_id)
        c.execute("""INSERT INTO paperless_links(task_id,doc_id,title,correspondent,created,status,added_at,conn_id,added_by)
                     VALUES(?,?,?,?,?,'ok',?,?,?)""", (tid, d["doc_id"], d["title"], d["correspondent"], d["created"],
                                                      iso(now_utc()), cid or None, me()))
        log_act(c, tid, "paperless", {"title": d["title"], "conn": cid})
        bump(c)
        c.commit()
    return jsonify(one_task(c, tid))


