def _csv_cell(v):
    v = str(v or "")
    return "'" + v if v[:1] in ("=", "+", "-", "@", "\t", "\r") else v


@app.get("/api/time/export.csv")
def time_csv():
    """Same filters as the report, one row per entry. German: ';' and decimal comma (Excel)."""
    need_time()
    c = db()
    uid = me()
    rep = time_report(c, uid, dict(request.args))
    lg = lang()
    de = lg == "de"
    num = (lambda x: f"{x:.2f}".replace(".", ",")) if de else (lambda x: f"{x:.2f}")
    names = {l["id"]: l["name"] for l in rep["lists"]}
    buf = io.StringIO()
    w = csv.writer(buf, delimiter=";" if de else ",", lineterminator="\r\n")
    w.writerow([tr("List"), tr("Task"), tr("User"), tr("Start|time"), tr("End|time"), tr("Duration (h)"),
                tr("Duration (h:mm)"), tr("Rounded (h)"), tr("Amount ({0})", rep["currency"]), tr("Note")])
    for e in rep["entries"]:
        lid = e["list_id"] if e["list_id"] in names else 0
        ln = names.get(lid, "")
        lst = next((x for x in rep["lists"] if x["id"] == lid), None)
        ln = tr("Inbox") if lst and lst["is_inbox"] and ln == "Eingang" else (ln or tr("No list"))
        s0 = parse_iso(e["start"]).astimezone(TZ)
        en = parse_iso(e["end"]).astimezone(TZ) if e["end"] else None
        sec, rs = e["seconds"], e["rounded"]
        w.writerow([_csv_cell(ln), _csv_cell(e["title"] or tr("No task")), _csv_cell(e["user_name"]),
                    s0.strftime("%Y-%m-%d %H:%M"), en.strftime("%Y-%m-%d %H:%M") if en else tr("running"),
                    num(sec / 3600), f"{sec // 3600}:{sec % 3600 // 60:02d}", num(rs / 3600),
                    num(e["amount"]) if e["amount"] is not None else "", _csv_cell(e["note"])])
    name = f"{tr('timesheet|file')}-{rep['from'] or 'all'}-{rep['to'] or local_now().date().isoformat()}.csv"
    name = re.sub(r"[^A-Za-z0-9._-]", "_", name)
    return Response("﻿" + buf.getvalue(), mimetype="text/csv; charset=utf-8",
                    headers={"Content-Disposition": f'attachment; filename="{name}"'})


def time_watchdog(c, users, S, LG):
    """Forgotten timers: a push after time_remind_h, auto-stop after time_autostop_h (end = start + N h)."""
    if not time_all():
        return
    ref = now_utc()
    for r in c.execute("SELECT e.*, t.title AS t_title FROM time_entries e LEFT JOIN tasks t ON t.id=e.task_id "
                       "WHERE e.end IS NULL").fetchall():
        try:
            _time_watch_one(c, r, users, S, LG, ref)
        except Exception as e:  # noqa: BLE001
            _wd_fail(c, "time entry", r["id"], e)


def _time_watch_one(c, r, users, S, LG, ref):
    uid = r["user_id"]
    if uid not in users:
        return
    s, lg = S[uid], LG[uid]
    rem_h, stop_h = _num(s.get("time_remind_h")), _num(s.get("time_autostop_h"))
    start = parse_iso(r["start"])
    hrs = (ref - start).total_seconds() / 3600
    seen = r["list_id"] is not None and list_role(c, r["list_id"], uid) and \
        (not r["task_id"] or task_visible(c, r["task_id"], uid, full=True))
    label = (r["t_title"] if seen else None) or r["task_title"] or tr("No task", lg=lg)
    fnum = (lambda x: f"{x:.1f}".rstrip("0").rstrip(".").replace(".", "," if lg == "de" else "."))
    if stop_h > 0 and hrs >= stop_h:
        end = start + timedelta(hours=stop_h)
        n = c.execute("UPDATE time_entries SET end=?, seconds=?, auto_stopped=1, updated_at=? WHERE id=? AND end IS NULL",
                      (iso(end), int(stop_h * 3600), iso(ref), r["id"])).rowcount
        bump(c)
        c.commit()
        if n:
            notify(uid, tr("Timer stopped automatically", lg=lg),
                   tr("{0} ran {1} h and was stopped at {2}. Correct the end time if needed.", label, fnum(stop_h),
                      end.astimezone(TZ).strftime("%H:%M"), lg=lg), push_prio(s, 4), f"{PUBLIC_URL}/#time", s=s)
    elif rem_h > 0 and hrs >= rem_h and not r["reminded"]:
        c.execute("UPDATE time_entries SET reminded=1 WHERE id=?", (r["id"],))
        c.commit()
        notify(uid, tr("Timer still running", lg=lg), tr("{0} has been running for {1} h. Still on it?", label, fnum(hrs), lg=lg),
               push_prio(s), f"{PUBLIC_URL}/#time", s=s)


# ---------------------------------------------------------------- settings / export (per user)

SETTINGS_SERVER_ONLY = ("digest_sent", "ntfy_topic", "features_rev", "onboard", "sample_ask", "agent_share")
SETTINGS_FLAGS = ("hide_blocked_today", "progress_subtasks", "ical_alarms", "time_focus", "paperless_keep", "celebrate", "cal_today")
SETTINGS_NUM = {"pomo_focus": (0, 600), "pomo_short": (0, 600), "pomo_long": (0, 600), "pomo_long_every": (1, 50),
                "time_rounding": (0, 1440), "time_remind_h": (0, 1000), "time_autostop_h": (0, 1000), "time_target": (0, 24)}


def clean_setting(k, v):
    """A user setting from the client as the stored string; None = leave unchanged; BadInput if invalid.
    The watchdog reads these for every user, so malformed values are never stored."""
    bad = BadInput(tr("Invalid value: {0}", k))
    if isinstance(v, (dict, list)) and k not in ("folders", "folders_closed", "show_done_views"):
        raise bad
    sv = "" if v is None else str(v).strip()
    if k == "allday_time":
        if not valid_hm(sv):
            raise bad
        return sv
    if k == "digest_time":
        if sv and not valid_hm(sv):
            raise bad
        return sv
    if k == "default_reminder":
        return clean_reminders(sv)
    if k == "hide_progress":
        ids = [x.strip() for x in sv.split(",") if x.strip()]
        if len(ids) > 500 or not all(x.isdigit() and len(x) < 12 for x in ids):
            raise bad
        return ",".join(dict.fromkeys(ids))
    if k == "roadmap":
        return clean_roadmap_pref(v)
    if k in SETTINGS_FLAGS:
        if sv in ("true", "True"):
            return "1"
        if sv in ("false", "False", ""):
            return "0"
        if sv not in ("0", "1"):
            raise bad
        return sv
    if k in SETTINGS_NUM:
        if sv == "":
            return None
        try:
            x = float(sv.replace(",", "."))
        except ValueError:
            raise bad from None
        lo, hi = SETTINGS_NUM[k]
        if not math.isfinite(x) or not lo <= x <= hi:
            raise bad
        return sv.replace(",", ".")
    if k == "tour":  # the client can only finish the tour (restarting it is local)
        if sv != "done":
            raise bad
        return sv
    if k == "ical_scope":
        if sv not in ("all", "mine"):
            raise bad
        return sv
    if k == "push_priority":
        if sv not in PUSH_PRIORITIES:
            raise bad
        return sv
    if k == "push_channel":
        if sv not in PUSH_CHANNELS:
            raise bad
        return sv
    if k == "news_kinds":
        ks = [x for x in sv.split(",") if x]
        if any(x not in NEWS_GROUPS for x in ks):
            raise bad
        return ",".join(dict.fromkeys(ks))
    if k in ("features", "nav_order"):
        if len(sv) > 500 or not re.fullmatch(r"[a-z_,]*", sv):
            raise bad
        return sv
    if k == "folders":
        try:
            arr = json.loads(v) if isinstance(v, str) else v
        except ValueError:
            raise bad from None
        if not isinstance(arr, list) or len(arr) > 200 or not all(isinstance(x, str) for x in arr):
            raise bad
        return json.dumps(list(dict.fromkeys(f for f in (clean_folder(x) for x in arr) if f)), ensure_ascii=False)
    if k == "folders_closed":  # 2.4.0 (#361): the folders this user folded in the sidebar (paths)
        try:
            arr = json.loads(v) if isinstance(v, str) else v
        except ValueError:
            raise bad from None
        if not isinstance(arr, list) or len(arr) > 400 or not all(isinstance(x, str) for x in arr):
            raise bad
        return json.dumps(list(dict.fromkeys(f for f in (clean_folder(x, False) for x in arr) if f)), ensure_ascii=False)
    if k == "show_done_views":
        return clean_done_views(v)
    if k == "comment_order":  # 2.4.2 (#386)
        if sv not in ("old", "new"):
            raise bad
        return sv
    if k == "time_currency":
        return sv[:8]
    if k == "lang":
        return sv
    return sv[:200]


DONE_VIEWS_MAX = 500


def clean_done_views(v):
    """Per-view "Show completed" (json object route key -> 0/1) -> stored json; BadInput if malformed."""
    bad = BadInput(tr("Invalid value: {0}", "show_done_views"))
    if v in (None, ""):
        return "{}"
    try:
        o = json.loads(v) if isinstance(v, str) else v
    except ValueError:
        raise bad from None
    if not isinstance(o, dict) or len(o) > DONE_VIEWS_MAX:
        raise bad
    out = {}
    for k, x in o.items():
        if not isinstance(k, str) or not 0 < len(k) <= 120 or x not in (0, 1, "0", "1"):
            raise bad
        out[k] = int(x)
    return json.dumps(out, ensure_ascii=False, separators=(",", ":"))


ROADMAP_KEY_RE = re.compile(r"(l\d{1,12}|f:.{1,80})", re.S)


def clean_roadmap_pref(v):
    """The roadmap view prefs (json object, see USER_DEFAULTS["roadmap"]) -> stored json; BadInput if malformed."""
    bad = BadInput(tr("Invalid value: {0}", "roadmap"))
    if v in (None, ""):
        return ""
    try:
        o = json.loads(v) if isinstance(v, str) else v
    except ValueError:
        raise bad from None
    if not isinstance(o, dict) or len(json.dumps(o)) > 20000:
        raise bad
    out = {}
    for k, x in o.items():
        if k == "v" and x in ("list", "timeline"):
            out[k] = x
        elif k == "z" and x in ("week", "month", "quarter"):
            out[k] = x
        elif k == "def" and x in ("auto", "c", "e"):
            out[k] = x
        elif k in ("po", "hd", "nd") and (x is None or isinstance(x, bool)):  # 2.0.6: nd = "No date" rows
            out[k] = x
        elif k == "who" and isinstance(x, str) and re.fullmatch(r"|me|none|\d{1,12}", x):
            out[k] = x
        elif k == "ls" and isinstance(x, list) and len(x) <= 500 and all(isinstance(i, int) and not isinstance(i, bool) and 0 < i < 10 ** 12 for i in x):
            out[k] = list(dict.fromkeys(x))
        elif k == "t" and isinstance(x, dict) and len(x) <= 1000 and all(isinstance(g_, str) and ROADMAP_KEY_RE.fullmatch(g_) and y in (0, 1) and not isinstance(y, bool) for g_, y in x.items()):
            out[k] = x
        else:
            raise bad
    return json.dumps(out, ensure_ascii=False, separators=(",", ":"))


@app.patch("/api/settings")
def settings_update():
    b = body()
    c = db()
    vals = {}
    if "notify" in b:  # 2.1.0 (#317): the notification matrix
        cur = usettings(c, me())
        v = b["notify"]
        if isinstance(v, str):  # the web app: the whole stored value (undo / redo send the old one back, '' = defaults)
            vals["notify"] = notif_update({**cur, "notify": ""}, v)["notify"] if v.strip() else ""
            b = {k: x for k, x in b.items() if k != "notify"}
        else:  # a partial change {event: {news?, push?}} (writes notify + news_kinds)
            if "news_kinds" in b:
                cur["news_kinds"] = clean_setting("news_kinds", b["news_kinds"])
            vals.update(notif_update(cur, v))
            b = {k: x for k, x in b.items() if k not in ("notify", "news_kinds")}
    for k, v in b.items():
        if k in USER_DEFAULTS and k not in SETTINGS_SERVER_ONLY:
            if k == "lang" and v not in LANGS:
                continue
            v = clean_setting(k, v)  # BadInput: 400, nothing stored
            if v is not None:
                vals[k] = v
    for k, v in vals.items():
        uset(c, me(), k, v)
    bump(c)
    c.commit()
    return jsonify(ok=True)


